  str_homestory_chat_15222003 = "為什麼這樣說？",
  str_homestory_chat_15222004 = "在空谷，沒有無情的壓榨，沒有無盡的加班......",
  str_homestory_chat_15222005 = "最重要的一點，可以盡情地睡懶覺！",
  str_homestory_chat_15222006 = "是因為不存在壓榨嗎？",
  str_homestory_chat_15222007 = "你猜得不錯。但這不是全部。",
  str_homestory_chat_15222008 = "我已經在空谷內發現了四個睡午覺的好地方。",
  str_homestory_chat_15222009 = "睡到太陽下山，都不會有人打攪呢。",
  str_homestory_chat_15222010 = "看來妳對空谷很滿意。",
  str_homestory_chat_15222011 = "這個世界上，沒有人會不滿意空谷的！",
  str_homestory_chat_15223001 = "在忙嗎？",
  str_homestory_chat_15223002 = "啊！PlayerName，我列了一份不咕咕清單，你要一起來挑戰嗎？",
  str_homestory_chat_15223003 = "怎麼忽然勤快起來了，不像妳啊。",
  str_homestory_chat_15223004 = "給我看看......",
  str_homestory_chat_15223005 = "挑戰不咕咕睡覺......挑戰不咕咕散步......",
  str_homestory_chat_15223006 = "挑戰不咕咕吃完快要過期的薯片......",
  str_homestory_chat_15223007 = "不愧是妳......",
  str_homestory_chat_15223008 = "多謝誇獎呢。",
  str_homestory_chat_15223009 = "這些完全不用挑戰啊！",
  str_homestory_chat_15223010 = "明明「不咕咕散步」還是很有挑戰性的......",
  str_homestory_chat_15251001 = "聽說你看到了什麼特殊的魚？",
  str_homestory_chat_15251002 = "前幾天我在河邊偷懶——咕！思考怎樣更有效率地工作的時候……",
  str_homestory_chat_15251003 = "是思考怎樣更有效率地偷懶吧？",
  str_homestory_chat_15251004 = "咕！是工作、工作！我們還是說這個魚吧，你不感興趣？",
  str_homestory_chat_15251005 = "感興趣。",
  str_homestory_chat_15251006 = "不過我似乎還需要點什麼，才能完成手上的工作。咕咕！",
  str_homestory_chat_15251007 = "好吧，我就知道……妳需要什麼？",
  str_homestory_chat_15251008 = "要一些短葉亞氏樹的種子。",
  str_homestory_chat_15251009 = "我馬上去找。",
  str_homestory_chat_14899999 = "你在跟我打招呼嗎？",
  str_homestory_chat_14801001 = "啊，是的",
  str_homestory_chat_14801002 = "跟妳打招呼......有什麼不對嗎？",
  str_homestory_chat_14801003 = "沒有。只是我不會閒到專門停下來跟人打招呼。",
  str_homestory_chat_14801004 = "畢竟，我要處理的事情太多了。",
  str_homestory_chat_14801005 = "喂，就這樣簡單粗暴地結束對話？",
  str_homestory_chat_14801006 = "如果有話說，就第一時間說出來。",
  str_homestory_chat_14821001 = "妳在找什麼？",
  str_homestory_chat_14821002 = "你看到知更了嗎？",
  str_homestory_chat_14821003 = "知更！知更！！",
  str_homestory_chat_14821004 = "沒看見......",
  str_homestory_chat_14821005 = "妳很著急找她嗎？我可以幫妳。",
  str_homestory_chat_14821006 = "當然很著急，我已經十分鐘沒有見到她了！",
  str_homestory_chat_14821007 = "我從來沒有這麼久沒看見她！",
  str_homestory_chat_14821008 = "這......這未免有點誇張......",
  str_homestory_chat_14821009 = "就在那裡......",
  str_homestory_chat_14821010 = "話說，為什麼感覺妳永遠都在找妹妹的路上？",
  str_homestory_chat_14821011 = "你什麼意思？你在暗示什麼？",
  str_homestory_chat_14821012 = "不......不，我沒有什麼意思......",
  str_homestory_chat_14821013 = "妳還是趕緊去找妳妹妹吧。",
  str_homestory_chat_14822001 = "妳在發呆嗎？",
  str_homestory_chat_14822002 = "嗯......你們這裡就沒有什麼有趣的東西嗎？",
  str_homestory_chat_14822003 = "「有趣的東西」？",
  str_homestory_chat_14822004 = "比如，年代久遠的花瓶、刻著古老文字的石頭......",
  str_homestory_chat_14822005 = "你們這裡有嗎？",
  str_homestory_chat_14822006 = "有啊！",
  str_homestory_chat_14822007 = "下次我帶妳去。",
  str_homestory_chat_14822008 = "不錯啊，想不到你還提供尋寶陪同服務。",
  str_homestory_chat_14822009 = "沒有......",
  str_homestory_chat_14822010 = "果然不出我所料。",
  str_homestory_chat_14822011 = "算了，沒有也不是什麼大不了的事情。",
  str_homestory_chat_14823001 = "妳好像很閒",
  str_homestory_chat_14823002 = "真無聊，都沒有架可以打。",
  str_homestory_chat_14823003 = "是誰在進入這裡之前，抒發了一番——",
  str_homestory_chat_14823004 = "「刀口舔血的日子過慣了，也該過過安逸日子了？」",
  str_homestory_chat_14823005 = "行行，你說得對。",
  str_homestory_chat_14823006 = "你讓開。",
  str_homestory_chat_14823007 = "你想幹嘛？",
  str_homestory_chat_14823008 = "讓我在樹上砍上幾刀，等過了一把癮......",
  str_homestory_chat_14823009 = "我就能繼續過安逸日子了。",
  str_homestory_chat_14823010 = "喂喂！不要破壞環境啊！",
  str_homestory_chat_14824001 = "接下來有什麼計畫？",
  str_homestory_chat_14824002 = "計畫嗎？完全沒想好。",
  str_homestory_chat_14824003 = "如果每天的生活都按照計畫來，那就太無聊了。",
  str_homestory_chat_14824004 = "難道你每天都會按照計畫生活嗎？",
  str_homestory_chat_14824005 = "會喔！",
  str_homestory_chat_14824006 = "每天做好計畫，會有一種安定感。",
  str_homestory_chat_14824007 = "原來PlayerName是這樣認為的嗎？",
  str_homestory_chat_14824008 = "我還以為你會更隨意一些！",
  str_homestory_chat_14824009 = "不會……",
  str_homestory_chat_14824010 = "畢竟計畫每次都趕不上變化。",
  str_homestory_chat_14824011 = "就是說啊！",
  str_homestory_chat_14824012 = "每天都會有不一樣的事情發生，這樣才讓人期待！",
  str_homestory_chat_14825001 = "妳想買衣服？",
  str_homestory_chat_14825002 = "你這個空庭，好像沒有賣衣服的地方？",
  str_homestory_chat_14825003 = "因為不需要啊……要買衣服去影鎮不就好了，烈雀？",
  str_homestory_chat_14825004 = "是要買給你啊，拆船工。",
  str_homestory_chat_14825005 = "啊？買給我？",
  str_homestory_chat_14825006 = "為什麼？",
  str_homestory_chat_14825007 = "因為你穿來穿去都是那幾件啊，看都看膩了。",
  str_homestory_chat_14825008 = "這……倒是沒錯。",
  str_homestory_chat_14825009 = "我不要。",
  str_homestory_chat_14825010 = "所以，要不要和我去影鎮逛一圈？",
  str_homestory_chat_14825011 = "我考慮看看吧。",
  str_homestory_chat_14825012 = "考慮什麼呀？再穿那一身到處跑，恐怕連丘布也要看膩了。",
  str_homestory_chat_14826001 = "練習？",
  str_homestory_chat_14826002 = "有時候要是需要鍛鍊一下刀法，也不能總是拿那些魚和樹來比劃吧。",
  str_homestory_chat_14826003 = "原來樹上那些劃痕是妳幹的啊……",
  str_homestory_chat_14826004 = "幫我找個好的陪練吧！",
  str_homestory_chat_14826005 = "這裡沒有。",
  str_homestory_chat_14826006 = "還是用樹吧。",
  str_homestory_chat_14826007 = "還是……用石頭？",
  str_homestory_chat_14826008 = "你在敷衍我是吧，拆船工。",
  str_homestory_chat_14826009 = "因為這裡是個和平的地方，來到這裡就應該放鬆。",
  str_homestory_chat_14826010 = "看來我要自己尋找目標了。那些丘布應該不錯！",
  str_homestory_chat_14826011 = "動作慢又不會反擊，看起來還很耐打的樣子。",
  str_homestory_chat_14826012 = "拜託不要！",
  str_homestory_chat_12299999 = "今天天氣這麼好，來一杯柴油嗎？",
  str_homestory_chat_12221001 = "算了",
  str_homestory_chat_12221002 = "這麼好喝的老柴油，確定不來一杯？",
  str_homestory_chat_12221003 = "老柴油......真是無法理解你呢。",
  str_homestory_chat_12222001 = "你覺得這裡怎麼樣？",
  str_homestory_chat_12222002 = "這裡確實是個很不錯的地方——",
  str_homestory_chat_12222003 = "就是柴油賣得貴了點。",
  str_homestory_chat_12222004 = "畢竟要從很遠的地方運過來。",
