  str_homestory_chat_12222009 = "！！！",
  str_homestory_chat_12222010 = "生氣了嗎？",
  str_homestory_chat_12222011 = "感謝你，老大，讓我知道了這個消息——",
  str_homestory_chat_12222012 = "我終於能喝上免費的柴油了！",
  str_homestory_chat_12223001 = "不說柴油的事情......",
  str_homestory_chat_12223002 = "你在看什麼呢？",
  str_homestory_chat_12223003 = "老大，你看見菈比了嗎？",
  str_homestory_chat_12223004 = "你找她有什麼事嗎？",
  str_homestory_chat_12223005 = "我已經半天沒有見到她了......",
  str_homestory_chat_12223006 = "萬一她要是出了什麼事，而我卻不在她身邊保護她——",
  str_homestory_chat_12223007 = "我一定會後悔一輩子的！",
  str_homestory_chat_12223008 = "老大，快救救菈比！救救我！",
  str_homestory_chat_12223009 = "......冷靜，冷靜。那些都只是你的內心戲。",
  str_homestory_chat_11299999 = "我的夥伴，你好。",
