  str_homestory_chat_11221003 = "也不用啦",
  str_homestory_chat_11221004 = "在這裡，大家都是朋友，不會鬧矛盾的。",
  str_homestory_chat_11221005 = "你說得也有一定的道理。",
  str_homestory_chat_11221006 = "不過，防患於未然，是我身為執行者必做的事情。",
