  str_homestory_chat_11221010 = "我的夥伴，感謝你對我工作價值的肯定。",
  str_homestory_chat_11221011 = "這份安寧，就由我守護。",
  str_homestory_chat_11222001 = "發生了什麼事？",
  str_homestory_chat_11222002 = "我剛才制止了一位破壞空谷環境的傢伙。",
  str_homestory_chat_11222003 = "咦，那人做了什麼？",
