  str_homestory_chat_11223001 = "妳看起來很高興......",
  str_homestory_chat_11223002 = "今天發生了什麼好事情嗎？",
  str_homestory_chat_11223003 = "在我的幫助下，一隻走失的貓咪找到了主人。",
