  str_homestory_chat_11224008 = "好厲害的效率！",
  str_homestory_chat_11225001 = "妳要找丘布？",
  str_homestory_chat_11225002 = "對。你是怎麼看待牠們的？",
  str_homestory_chat_11225003 = "很好的夥伴。",
  str_homestory_chat_11225004 = "只是夥伴嗎......",
  str_homestory_chat_11225005 = "空庭的建設者。",
  str_homestory_chat_11225006 = "建設者？",
  str_homestory_chat_11225007 = "唉，看來你似乎沒發現牠們身上的良好品質。",
  str_homestory_chat_11225008 = "什麼品質？",
  str_homestory_chat_11225009 = "遵守紀律，我看你給牠們下達的命令，每次都能完成。",
  str_homestory_chat_11225010 = "如果能組織牠們，維護空庭的治安......簡直完美。",
