  str_homestory_chat_12523006 = "沒有啊",
  str_homestory_chat_12523007 = "可是，它都不足以讓彼岸號通行。",
  str_homestory_chat_12523008 = "難道我的彼岸號要辛苦地飄在天上嗎？",
  str_homestory_chat_12523009 = "等等！為什麼要在人走的地方開火車啊！",
  str_homestory_chat_12524001 = "聽說你有個計畫......",
  str_homestory_chat_12524002 = "是的，PlayerName，這塊空地上不建點什麼嗎？",
  str_homestory_chat_12524003 = "建什麼？",
  str_homestory_chat_12524004 = "舞台啊——",
  str_homestory_chat_12524005 = "屬於藝術家的我和彼岸號的舞台！",
  str_homestory_chat_12524006 = "怎麼樣？是不是一個極富激情和創造力的建議？",
  str_homestory_chat_12524007 = "什麼都不建",
  str_homestory_chat_12524008 = "PlayerName，你看這片空地，不覺得它是如此蒼白嗎？",
  str_homestory_chat_12524009 = "等待著真正的激情和藝術氣息為它塗滿色彩——",
  str_homestory_chat_12524010 = "所以呢？",
  str_homestory_chat_12524011 = "所以，建一座舞台吧！為了藝術家和彼岸號！",
  str_homestory_chat_12524012 = "唔，我考慮一下。",
  str_homestory_chat_12525001 = "今天的舞會......",
  str_homestory_chat_12525002 = "你是說......今天晚上會舉辦舞會嗎？",
  str_homestory_chat_12525003 = "我是不會去的！惡靈藝術家命運的盡頭，就是孤寂。",
  str_homestory_chat_12525004 = "可你看起來很想去......",
  str_homestory_chat_12525005 = "咳，那是你看錯了。",
  str_homestory_chat_12525006 = "不過，你執意邀請的話，我也可以賞臉光顧......",
  str_homestory_chat_12525007 = "好吧，那我執意邀請。",
  str_homestory_chat_12525008 = "那好吧，再見",
  str_homestory_chat_12525009 = "......你就不再堅持邀請一下嗎？",
  str_homestory_chat_12525010 = "好吧......",
  str_homestory_chat_12525011 = "咳咳，卡戎，今天晚上有舞會，你一定要來。",
  str_homestory_chat_12525012 = "行，看在知音你的面子上，我勉強答應了。",
  str_homestory_chat_12526001 = "我有一個疑問",
  str_homestory_chat_12526002 = "哦？既然PlayerName提出了疑問，那麼我必定會為你解答。",
  str_homestory_chat_12526003 = "所以是什麼事困擾了你呢，我的知音？",
  str_homestory_chat_12526004 = "明明別的火車都會在鐵軌上行駛......",
  str_homestory_chat_12526005 = "為什麼只有你的彼岸號不需要鐵軌？！",
  str_homestory_chat_12526006 = "哈哈哈，問得好！",
  str_homestory_chat_12526007 = "彼岸號是我的朋友，它就像我的靈感，而靈感是自由的。",
  str_homestory_chat_12526008 = "若是被軌道這種既定的東西束縛，又怎麼能稱得上自由呢？",
  str_homestory_chat_12526009 = "那也不能讓它在空谷裡亂跑啊！",
  str_homestory_chat_10699999 = "PlayerName，你想和我聊天嗎？",
  str_homestory_chat_10601001 = "是啊",
  str_homestory_chat_10601002 = "我非常樂意，不過，你需要注意一下時間。",
  str_homestory_chat_10601003 = "你接下來還有好幾個計畫，別忘了。",
  str_homestory_chat_10621001 = "對於甜品......",
  str_homestory_chat_10621002 = "妳有什麼樣式方面的建議嗎？",
  str_homestory_chat_10621003 = "你們準備做甜品？",
  str_homestory_chat_10621004 = "對啊，我們想為大家準備一些零食。",
  str_homestory_chat_10621005 = "唔，我推薦草莓椰奶糕......",
  str_homestory_chat_10621006 = "不過，如果做起來很麻煩，換成別的也可以。",
  str_homestory_chat_10621007 = "草莓椰奶糕......",
  str_homestory_chat_10621008 = "是卡蓮最喜歡的甜點吧？",
  str_homestory_chat_10621009 = "不是我想吃，我只是......只是誠心推薦給你們。",
  str_homestory_chat_10621010 = "這次有高手相助！",
  str_homestory_chat_10621011 = "一定沒問題的。",
  str_homestory_chat_10621012 = "總之，做出來了，妳一定要來嚐一嚐啊！",
  str_homestory_chat_10622001 = "今天天氣不錯！",
  str_homestory_chat_10622002 = "是的，這裡的天氣一如既往地好呢。",
  str_homestory_chat_10622003 = "妳很喜歡晴天吧",
  str_homestory_chat_10622004 = "晴天，是讓人心情愉悅的天氣。",
  str_homestory_chat_10622005 = "不過，總是晴天，也會出問題。",
  str_homestory_chat_10622006 = "正是因為並非每一天都是晴天......",
  str_homestory_chat_10622007 = "遇上晴天，才會讓人愉快。",
  str_homestory_chat_10622008 = "PlayerName，你說出了很有哲理的話。",
  str_homestory_chat_10622009 = "是啊",
  str_homestory_chat_10622010 = "或許，打動人的，不僅是晴天......",
  str_homestory_chat_10622011 = "還有這裡和平寧靜的氣氛吧。",
  str_homestory_chat_10622012 = "真希望這樣的日子能永遠持續下去。",
  str_homestory_chat_10623001 = "有沒有空？",
  str_homestory_chat_10623002 = "PlayerName，有什麼事需要我幫忙的嗎？",
  str_homestory_chat_10623003 = "唔，有",
  str_homestory_chat_10623004 = "不過，也不是什麼特別重要的事情。",
  str_homestory_chat_10623005 = "妳有別的事情要忙的話，就先去忙別的吧。",
  str_homestory_chat_10623006 = "讓我想想......",
  str_homestory_chat_10623007 = "都是一些小事情，不需要妳出馬。",
  str_homestory_chat_10623008 = "好像沒有",
  str_homestory_chat_10623009 = "事情都做完了嗎？",
  str_homestory_chat_10623010 = "雖然還有一些事沒做，但不需要麻煩妳啦。",
  str_homestory_chat_10623011 = "可是，我很想為大家做點力所能及的事情。",
  str_homestory_chat_10624001 = "聽說妳有事要和我說？",
  str_homestory_chat_10624002 = "PlayerName，薇絲告訴我說......",
  str_homestory_chat_10624003 = "前幾天的釣魚比賽，你遲到了？",
  str_homestory_chat_10624004 = "是的......",
  str_homestory_chat_10624005 = "我出發時還有半個小時，沒有想到目的地太遠......",
