  str_homestory_chat_10624007 = "我能召喚馬出來，載你過去。",
  str_homestory_chat_10624008 = "總之，絕對不能養成遲到的壞習慣。",
  str_homestory_chat_10625001 = "聽說妳要釣魚？",
  str_homestory_chat_10625002 = "是的，你們最近有釣魚計畫嗎？",
  str_homestory_chat_10625003 = "有！",
  str_homestory_chat_10625004 = "看來我要好好準備一下。",
