  str_homestory_chat_10625006 = "連帳篷傘和長槍都帶上了。",
  str_homestory_chat_10625007 = "帳篷傘是為了防止釣魚中途下雨......",
  str_homestory_chat_10625008 = "長槍用來對付逃跑的魚，可以一擊致命。",
  str_homestory_chat_10625009 = "我不喜歡有計畫之外的事情發生。",
  str_homestory_chat_10625010 = "準備充足，是從容成功的前提。",
  str_homestory_chat_10625011 = "感覺又學到了點什麼......",
  str_homestory_chat_10626001 = "有什麼建議嗎？",
  str_homestory_chat_10626002 = "我最近想在這裡增加一些裝飾，但不知道要加什麼才好。",
  str_homestory_chat_10626003 = "裝飾嗎？讓我想一想......",
  str_homestory_chat_10626004 = "增加一些可以用來鍛鍊武藝的設備，如何？",
