  str_homestory_chat_12801001 = "沒有",
  str_homestory_chat_12801002 = "只是想和妳打個招呼。",
  str_homestory_chat_12801003 = "您的問候讓拉斐爾很高興呢！",
  str_homestory_chat_12801004 = "來，這些聖水炸彈請您收下，它們一定會派上用場的！",
  str_homestory_chat_12821001 = "妳在看什麼？",
  str_homestory_chat_12821002 = "哇，拉斐爾的虎牙好像又長了一點呢。",
  str_homestory_chat_12821003 = "想不到，十字架居然能當鏡子......",
  str_homestory_chat_12821004 = "您想和拉斐爾比比虎牙的長度嗎？",
  str_homestory_chat_12821005 = "來，站到十字架前面來。",
  str_homestory_chat_12821006 = "不了吧......",
  str_homestory_chat_12821007 = "放心啦，拉斐爾的十字架照得很清楚的！",
