  str_homestory_chat_12823005 = "我明白了！",
  str_homestory_chat_12823006 = "明白了什麼？",
  str_homestory_chat_12823007 = "您一定是覺得我做的糕點太精緻了......",
  str_homestory_chat_12823008 = "不忍心食用它！",
  str_homestory_chat_12823009 = "......妳就當這是真相吧。",
  str_homestory_chat_12823010 = "為什麼又找我？",
  str_homestory_chat_12823011 = "因為大家都說，PlayerName擁有世界上最強的美食鑑賞力！",
