  str_homestory_chat_12823013 = "告訴我，我就為妳推薦鑑賞力更強的人！",
  str_homestory_chat_10799999 = "哼哼～哼～啊，PlayerName，您叫我？",
  str_homestory_chat_10721001 = "打擾到妳唱歌了？",
  str_homestory_chat_10721002 = "沒......沒有的事，剛才我......哎。",
  str_homestory_chat_10721003 = "您有什麼事找我嗎？",
  str_homestory_chat_10722001 = "妳在找什麼呢？",
  str_homestory_chat_10722002 = "PlayerName，這裡會有兔子嗎？",
  str_homestory_chat_10722003 = "有吧？",
  str_homestory_chat_10722004 = "我似乎看到......有些人組織了打獵活動......",
