  str_homestory_chat_10722009 = "反正我沒有看到過。",
  str_homestory_chat_10722010 = "......這樣也好，至少在這裡，我不會看見受到傷害的牠們。",
  str_homestory_chat_10723001 = "習慣這裡了嗎？",
  str_homestory_chat_10723002 = "這裡的風，很溫柔......",
  str_homestory_chat_10723003 = "妳也這樣覺得？",
  str_homestory_chat_10723004 = "PlayerName，對您來講，幸福是什麼呢？",
