  str_homestory_chat_10723008 = "這樣嗎......",
  str_homestory_chat_10723009 = "和平與寧靜",
  str_homestory_chat_10723010 = "沒有欺騙、沒有流血，所有孩子的臉上都能綻放笑容......",
  str_homestory_chat_10723011 = "那真的是......了不起的幸福啊。",
  str_homestory_chat_10751001 = "特殊的魚在哪裡？",
  str_homestory_chat_10751002 = "好舒服的風……",
  str_homestory_chat_10751003 = "風？我怎麼沒感覺到？",
  str_homestory_chat_10751004 = "可能是您帶來的吧。您很著急嗎？",
  str_homestory_chat_10751005 = "確實……好像聽說妳看到什麼特殊的魚？",
