  str_homestory_chat_10751008 = "都不是……別管這個了，魚在哪裡啊？",
  str_homestory_chat_10751009 = "「兔子」……我記得他好像說了一句喜歡什麼樹。",
  str_homestory_chat_10751010 = "或許是……小葉昆嵐樹？",
  str_homestory_chat_10751011 = "看來我又要跑一趟了……",
  str_homestory_chat_10751012 = "什麼？",
  str_homestory_chat_10751013 = "沒事！小葉昆嵐樹的種子吧？好弄～",
  str_homestory_chat_10751014 = "那就謝謝了。",
  str_homestory_chat_10199999 = "我收到你的問候了。",
  str_homestory_chat_10121001 = "好的",
  str_homestory_chat_10121002 = "我很好。你還有什麼想要說的嗎？",
  str_homestory_chat_10121003 = "嗯，那個......我......",
  str_homestory_chat_10121004 = "等候你措辭，看來我需要一點點耐心了。",
  str_homestory_chat_10122001 = "妳在找我？",
  str_homestory_chat_10122002 = "PlayerName，我希望你能注意到一個事實。",
  str_homestory_chat_10122003 = "什麼事實？",
  str_homestory_chat_10122004 = "這裡的水邊，很適合種白水仙。",
  str_homestory_chat_10122005 = "......",
  str_homestory_chat_10122006 = "怎麼？需要我一條一條列舉適合的原因嗎？",
  str_homestory_chat_10122007 = "不用了......我會考慮的。",
  str_homestory_chat_10123001 = "住得還習慣嗎？",
  str_homestory_chat_10123002 = "嗯......雖然這裡許多地方都無法與北境媲美......",
  str_homestory_chat_10123003 = "但它仍然有非常值得稱頌的地方。",
  str_homestory_chat_10123004 = "是什麼？",
  str_homestory_chat_10123005 = "這裡的天空、氣息和水流，都非常潔淨。",
  str_homestory_chat_10123006 = "生活在這裡，光靈們的靈魂將得到滋養。",
  str_homestory_chat_10123007 = "聽起來，確實是讚美呢......",
  str_homestory_chat_10123008 = "哪裡比不上北境了？！",
  str_homestory_chat_10123009 = "我希望你不要糾結這些細枝末節......",
  str_homestory_chat_10123010 = "而忽視了真正有價值的東西——",
  str_homestory_chat_10123011 = "我認為，潔淨的家園可以滋養光靈的靈魂。",
  str_homestory_chat_10123012 = "希望你永遠守護著這裡的寧和與純淨。",
