  str_homestory_chat_10221003 = "感覺你近日瑣事繁多，還是多多休息為好。",
  str_homestory_chat_10221004 = "那我就休息一會吧。",
  str_homestory_chat_10221005 = "你可以和我一起，去那邊的樹下靜思。",
