  str_homestory_chat_12122006 = "就忍不住想到各色各樣的花朵～",
  str_homestory_chat_12122007 = "只可惜，一些不聽話的孩子，就像長出了錯誤枝條的花兒。",
  str_homestory_chat_12122008 = "遇到這樣的花朵，我也會毫不留情地幫牠修剪呢～",
  str_homestory_chat_12122009 = "嗯......我是不是聽到了什麼很可怕的話？",
  str_homestory_chat_11499999 = "PlayerName，很高興與你見面。",
  str_homestory_chat_11401001 = "你好，舒瓦茲",
  str_homestory_chat_11401002 = "能夠拜訪你的家園，我還需感謝邀請。",
  str_homestory_chat_11401003 = "這種小事，就不用客氣啦。",
  str_homestory_chat_11401004 = "希望這裡能在你的治理下，欣欣向榮。",
  str_homestory_chat_11421001 = "你覺得這裡怎麼樣？",
  str_homestory_chat_11421002 = "井井有條，很不錯，看來用了很多心力。",
  str_homestory_chat_11421003 = "PlayerName，治理此處，難免會遇上困難。",
  str_homestory_chat_11421004 = "如需助力，我決不會吝嗇時間。",
  str_homestory_chat_11421005 = "謝謝了！",
  str_homestory_chat_11421006 = "在這方面，我要向城主多多請教。",
  str_homestory_chat_11421007 = "治理一片土地，秩序是一切的核心。",
  str_homestory_chat_11421008 = "它可能嚴苛，但必不可少。",
  str_homestory_chat_11421009 = "（啊......現在要開始討論嗎......）",
  str_homestory_chat_11421010 = "暫時不需要......",
  str_homestory_chat_11421011 = "大家都是朋友，談不上什麼「治理」啦。",
  str_homestory_chat_11421012 = "但願你的方式也能為這裡帶來繁榮。",
  str_homestory_chat_11422001 = "很歡迎你到這裡來",
  str_homestory_chat_11422002 = "你的家園和白夜城一樣，擁有著令人心曠神怡的晴天。",
  str_homestory_chat_11422003 = "這種天氣適合——",
  str_homestory_chat_11422004 = "釣魚！",
  str_homestory_chat_11422005 = "端坐在河邊，等待悠遊的獵物上鉤......",
  str_homestory_chat_11422006 = "這是此處流行的休閒方式？",
  str_homestory_chat_11422007 = "您想試試嗎？",
  str_homestory_chat_11422008 = "倒也不錯。",
  str_homestory_chat_11422009 = "跑步！",
  str_homestory_chat_11422010 = "這是屬於年輕人的運動。",
  str_homestory_chat_11422011 = "我很樂意在一旁觀賞。",
  str_homestory_chat_11423001 = "在看書？",
  str_homestory_chat_11423002 = "在這樣的日光中，捧卷閱讀是最舒適的消遣方式。",
  str_homestory_chat_11423003 = "PlayerName，如果你感興趣，我也可藉予你觀覽。",
  str_homestory_chat_11423004 = "謝謝了！",
  str_homestory_chat_11423005 = "能吸引您的書，一定很有趣吧。",
  str_homestory_chat_11423006 = "我並不為「有趣」而閱讀。",
  str_homestory_chat_11423007 = "在其中，我更願意神遊宇宙之無垠，窺探人性之幽深。",
  str_homestory_chat_11423008 = "不過，如果你能從中得到趣味，也是很好的。",
  str_homestory_chat_11423009 = "不用了......",
  str_homestory_chat_11423010 = "雖然我很想看看書休息一下，但任務實在太多......",
  str_homestory_chat_11423011 = "如果應付不來，託付給我是一個很好的選擇。",
  str_homestory_chat_12999999 = "啊啦，果然是你啊......",
  str_homestory_chat_12921001 = "啊，是的",
  str_homestory_chat_12921002 = "在風裡，我已經感知到你的到來了。",
  str_homestory_chat_12921003 = "有這麼神奇嗎？",
  str_homestory_chat_12921004 = "你有著特殊的氣息呢。",
  str_homestory_chat_12922001 = "妳看起來很悠閒呢",
  str_homestory_chat_12922002 = "我發現......待在籠子裡曬太陽，會發生一些有趣的事情......",
  str_homestory_chat_12922003 = "是什麼？",
  str_homestory_chat_12922004 = "臉上有些地方會發燙，有些地方則冰涼涼的。",
  str_homestory_chat_12922005 = "為什麼會這樣？",
  str_homestory_chat_12922006 = "我也不知道呢......",
  str_homestory_chat_12922007 = "不想思考，思考太累了。",
  str_homestory_chat_12922008 = "是因為籠子？",
  str_homestory_chat_12922009 = "籠子會在臉上投下陰影，陽光照不到，自然就變涼了。",
  str_homestory_chat_12922010 = "也許你說得是對的。",
  str_homestory_chat_12922011 = "但我不想去分辨，思考太累了。",
  str_homestory_chat_12923001 = "看來妳很喜歡這裡",
  str_homestory_chat_12923002 = "暖洋洋的陽光......",
  str_homestory_chat_12923003 = "......呼......是的呢，感覺自己就像絲絮一樣......",
  str_homestory_chat_12923004 = "......呼......嗯，我沒有睡著......",
  str_homestory_chat_12923005 = "（我還是不要打攪她睡覺了。）",
  str_homestory_chat_12924001 = "妳在做什麼？",
  str_homestory_chat_12924002 = "你聽見了嗎？",
  str_homestory_chat_12924003 = "在這裡，有著豐富的聲音......",
  str_homestory_chat_12924004 = "來自溪水、樹林和山谷，連綿不絕。",
  str_homestory_chat_12924005 = "是的",
  str_homestory_chat_12924006 = "在白夜城，聽到最多的是風聲，其他聲音都是光靈發出的。",
  str_homestory_chat_12924007 = "相較之下，我更喜歡這裡的聲音呢。",
  str_homestory_chat_12924008 = "我都沒注意到",
  str_homestory_chat_12924009 = "妳這麼一說，我才感受到......",
  str_homestory_chat_12924010 = "聆聽，會帶來意料之外的快樂。",
  str_homestory_chat_12925001 = "木材？",
  str_homestory_chat_12925002 = "啊啦，其實是木料，有沒有那種又輕又結實的呢？",
  str_homestory_chat_12925003 = "嗯……妳突然想要木料，打算用來做什麼？",
  str_homestory_chat_12925004 = "想改造一下這個籠子呢，畢竟它很大，也很重。",
  str_homestory_chat_12925005 = "確實，如果木料輕一些，妳也能輕鬆一點吧。",
  str_homestory_chat_12925006 = "不過妳說的那種木材，似乎很難在空庭找到。",
  str_homestory_chat_12925007 = "這裡都是一些奇怪的樹，感覺很難製成木料。",
  str_homestory_chat_12925008 = "而且……那些丘布可能也不會答應吧。",
  str_homestory_chat_12926001 = "高處？",
  str_homestory_chat_12926002 = "我正在空庭裡找一個風景好的地方，想來想去……",
  str_homestory_chat_12926003 = "還是高一點的地方比較好，如果能俯瞰整個空庭就更好了。",
  str_homestory_chat_12926004 = "啊啦，所以就想問問你。",
  str_homestory_chat_12926005 = "有的。",
  str_homestory_chat_12926006 = "或許那座風信塔可以？",
  str_homestory_chat_12926007 = "但是那個丘布會答應嗎？",
  str_homestory_chat_12926008 = "確實……不會。",
  str_homestory_chat_12926009 = "沒有。",
  str_homestory_chat_12926010 = "啊啦……看來果然沒辦法實現呢。",
  str_homestory_chat_12926011 = "妳原本打算怎麼做？",
  str_homestory_chat_12926012 = "我想把籠子掛在高處，享受微風吹過，籠子輕搖的感覺。",
  str_homestory_chat_12926013 = "很舒服，特別容易入睡呢。",
  str_homestory_chat_12926014 = "確實，但是高處也可能刮大風，這樣籠子就會劇烈晃動吧。",
  str_homestory_chat_12926015 = "對喔，你說得有道理。",
  str_homestory_chat_12926016 = "所以，還是保持現狀比較好。",
