  str_homestory_chat_12324003 = "是安東們......你想和牠們也聊聊天嗎？",
  str_homestory_chat_12324004 = "不必了......",
  str_homestory_chat_12324005 = "牠們......有時候確實會讓人害怕呢......",
  str_homestory_chat_12324006 = "不過，相信我，安東們都是好孩子！",
  str_homestory_chat_12324007 = "好啊！",
  str_homestory_chat_12324008 = "那......那我幫你把牠們叫出來......",
  str_homestory_chat_12325001 = "在忙什麼？",
  str_homestory_chat_12325002 = "是......是PlayerName呀......",
  str_homestory_chat_12325003 = "我住進來已經有段時間了，得到過許多人的幫助......",
  str_homestory_chat_12325004 = "所以，我想為大家泡一些咖啡，但是......我......",
  str_homestory_chat_12325005 = "遇到了困難嗎？",
  str_homestory_chat_12325006 = "嗯......我，不知道大家會不會喜歡咖啡......",
  str_homestory_chat_12325007 = "所以......在猶豫......",
  str_homestory_chat_12325008 = "不用那麼緊張，克娜莉！",
  str_homestory_chat_12325009 = "克娜莉泡的咖啡一直都很好喝，而且——",
  str_homestory_chat_12325010 = "比起咖啡本身，更重要的是妳的心意呀！",
  str_homestory_chat_13699999 = "好無聊，你終於要給我找點事做了？",
  str_homestory_chat_13601001 = "沒什麼事，就打個招呼",
  str_homestory_chat_13601002 = "打招呼而已？",
  str_homestory_chat_13601003 = "......我就不該打起精神回應你的無聊問候。",
  str_homestory_chat_13621001 = "最近怎麼樣？",
  str_homestory_chat_13621002 = "這裡的食物，清淡到狗都不吃。",
  str_homestory_chat_13621003 = "你想吃什麼？",
  str_homestory_chat_13621004 = "什麼都可以。",
  str_homestory_chat_13621005 = "剛才，是誰在嫌棄這裡的食物？",
  str_homestory_chat_13621006 = "總之，什麼辣味調料、鹽，多放一點就可以了。",
  str_homestory_chat_13621007 = "就這？",
  str_homestory_chat_13621008 = "我和我的狗，要求都很低的。",
  str_homestory_chat_13622001 = "在幹什麼？",
  str_homestory_chat_13622002 = "......安靜，影子們在休息。",
  str_homestory_chat_13622003 = "影子也需要休息？",
  str_homestory_chat_13622004 = "......是。",
  str_homestory_chat_13622005 = "沒有其他解釋了？",
  str_homestory_chat_13622006 = "......沒了。",
  str_homestory_chat_13622007 = "你只是不想和我聊天",
  str_homestory_chat_13622008 = "你可以暫時這麼理解。",
  str_homestory_chat_13622009 = "等影子休息好了，再來找我也不遲。",
  str_homestory_chat_13623001 = "嗨，休拉德",
  str_homestory_chat_13623002 = "這裡有不少人養狗。",
  str_homestory_chat_13623003 = "你有意見嗎？",
  str_homestory_chat_13623004 = "因為狗會咬人？",
  str_homestory_chat_13623005 = "不是。",
  str_homestory_chat_13623006 = "因為狗會叫？",
  str_homestory_chat_13623007 = "不啞的狗都會叫。",
  str_homestory_chat_13623008 = "那你是因為什麼有意見？",
  str_homestory_chat_13623009 = "我說過我對別人養狗有意見嗎？",
  str_homestory_chat_13623010 = "......",
  str_homestory_chat_14999999 = "老大，找我有什麼事嗎？要我幫你揍人？",
  str_homestory_chat_14901001 = "只是打個招呼",
  str_homestory_chat_14901002 = "唉......只是這樣啊。",
  str_homestory_chat_14901003 = "要揍人時，別忘了叫上我啊！",
  str_homestory_chat_14921001 = "要幫忙嗎？",
  str_homestory_chat_14921002 = "老大，你看我的鎧甲上有灰塵嗎？",
  str_homestory_chat_14921003 = "很乾淨",
  str_homestory_chat_14921004 = "居然沒有嗎？",
  str_homestory_chat_14921005 = "我還盼著能擦擦鎧甲，打發時間。",
  str_homestory_chat_14921006 = "你很無聊嗎？",
  str_homestory_chat_14921007 = "在這裡，連一個可以和我打一架的人都沒有。",
  str_homestory_chat_14921008 = "當然無聊。",
  str_homestory_chat_14921009 = "這裡有點",
  str_homestory_chat_14921010 = "我看看，謝謝你啊，老大。",
  str_homestory_chat_14922001 = "你看起來氣色不太好......",
  str_homestory_chat_14922002 = "老大，我好餓啊......",
  str_homestory_chat_14922003 = "我已經連著吃了好幾天蔬菜了......",
  str_homestory_chat_14922004 = "蔬菜有利於健康",
  str_homestory_chat_14922005 = "老大，這種話，對我這種沒有肉就活不下去的人來說......",
  str_homestory_chat_14922006 = "太過於殘忍了吧！",
  str_homestory_chat_14922007 = "我也不想吃蔬菜啊！",
  str_homestory_chat_14922008 = "但是我快沒錢了，只能忍了！",
  str_homestory_chat_14922009 = "老大，我們過得好苦啊！",
  str_homestory_chat_14951001 = "水中的大蝦……",
  str_homestory_chat_14951002 = "你也看到了！空庭的老大！",
  str_homestory_chat_14951003 = "別那樣叫我了……",
  str_homestory_chat_14951004 = "好的！這裡的老大，沒想到這裡也看到那種大蝦。",
  str_homestory_chat_14951005 = "牠們可真大！如果賣到影鎮，應該能掙不少！",
  str_homestory_chat_14951006 = "真的？",
  str_homestory_chat_14951007 = "沒錯，那種大蝦好像因為好鬥，所以很適合用來觀賞。",
  str_homestory_chat_14951008 = "看到牠們互相打來打去，一對大鼇就和我的兩柄大劍似的……",
  str_homestory_chat_14951009 = "真令我手癢癢，不由得想下場比劃兩下……",
  str_homestory_chat_14951010 = "你們的體型差太多了吧……",
  str_homestory_chat_14951011 = "唉，我也就只能看看，所以影鎮也有很多人抱著跟我一樣的想法。",
  str_homestory_chat_14951012 = "有時候那打鬥過程，真的很令人心潮澎湃啊！",
  str_homestory_chat_14951013 = "看來在影鎮還是個搶手貨？",
  str_homestory_chat_14951014 = "（估計能賺一筆……）",
  str_homestory_chat_14951015 = "看來你對這種大蝦很熟悉？",
  str_homestory_chat_14951016 = "自然！首先，牠們的名字叫「魁蝦」。",
  str_homestory_chat_14951017 = "其次，我已經發現好幾處地方有牠們的身影了。",
  str_homestory_chat_14951018 = "居然有好幾處！",
  str_homestory_chat_14951019 = "而且還有不同種呢。",
  str_homestory_chat_14951020 = "會很多嗎？",
  str_homestory_chat_14951021 = "其實不多，就兩種。比較常見的是那種藍色的。",
  str_homestory_chat_14951022 = "對，我看到的也是那種。",
  str_homestory_chat_14951023 = "那自然是了，除了這種藍色的，還有一種棕色的，那才是高級貨。",
  str_homestory_chat_14951024 = "但是更不容易發現就是了……",
  str_homestory_chat_14951025 = "要怎麼獲得呢？",
  str_homestory_chat_14951026 = "首先要有那種藍色魁蝦，學名是「藍漫魁蝦」。",
  str_homestory_chat_14951027 = "如果你有的話，就能用牠來交換更大的棕色魁蝦的釣魚點。",
  str_homestory_chat_14951028 = "就只有這些？",
  str_homestory_chat_14951029 = "看來你也學會討價還價了！這樣吧，還會給空庭的老大額外的報酬的。",
  str_homestory_chat_14951030 = "總之，不會虧了你！",
  str_homestory_chat_14951031 = "不過，那些藍漫魁蝦要在哪裡能釣到？",
  str_homestory_chat_14951032 = "啊？你不是看到了嗎？",
  str_homestory_chat_14951033 = "以防萬一嘛，能知道更多的釣魚點不是更好嗎？",
  str_homestory_chat_14951034 = "好吧！我知道不少釣魚點，應該都能找到藍漫魁蝦。",
  str_homestory_chat_14951035 = "當然憑藉你的本事，應該沒問題，這樣就可以來交換那個「棕磊魁蝦」的釣魚點了！",
  str_homestory_chat_14951036 = "原來那棕色大蝦叫這個名字啊……",
