  str_homestory_chat_11822001 = "好像沒什麼事做",
  str_homestory_chat_11822002 = "是的，好無聊啊！",
  str_homestory_chat_11822003 = "我也是......",
  str_homestory_chat_11822004 = "妳有什麼好主意嗎？",
  str_homestory_chat_11822005 = "這種時候，就應該來一場金屬演唱會！",
  str_homestory_chat_11822006 = "我的電吉他能轟走所有的無聊情緒！",
  str_homestory_chat_11822007 = "怎麼樣，PlayerName，是個好主意吧？",
  str_homestory_chat_11822008 = "唔，我考慮一下。",
  str_homestory_chat_11823001 = "妳在說什麼？",
  str_homestory_chat_11823002 = "哈密瓜、蛋黃醬......",
  str_homestory_chat_11823003 = "那是什麼咒語嗎？",
  str_homestory_chat_11823004 = "不，那是世界上最好吃的東西！",
  str_homestory_chat_11823005 = "在切好的冰涼涼的哈密瓜上淋滿蛋黃醬......",
  str_homestory_chat_11823006 = "一口咬下去，所有的煩惱都煙消雲散......",
