  str_homestory_chat_11701001 = "妳好呀！菈比！",
  str_homestory_chat_11701002 = "今天有什麼計畫嗎？",
  str_homestory_chat_11701003 = "暫時沒有",
  str_homestory_chat_11701004 = "那要不要和我一起去打洞呢？",
  str_homestory_chat_11701005 = "還......還是等一下吧。",
  str_homestory_chat_11721001 = "妳好像在想什麼？",
  str_homestory_chat_11721002 = "PlayerName，想不想听我規劃的撤退路線？",
  str_homestory_chat_11721003 = "撤退路線？",
  str_homestory_chat_11721004 = "任何一個成熟的家園都不可以缺少撤退路線！",
  str_homestory_chat_11721005 = "這是為了大家的安全！",
  str_homestory_chat_11721006 = "好吧，那我看看。",
  str_homestory_chat_11721007 = "我已經施工了一部分，鑽出了三個洞唷！",
  str_homestory_chat_11721008 = "不是吧？！",
  str_homestory_chat_11722001 = "妳在看什麼？",
  str_homestory_chat_11722002 = "PlayerName，我換了新的鑽頭唷！",
  str_homestory_chat_11722003 = "真想現在就試一試！",
  str_homestory_chat_11722004 = "別，別......",
  str_homestory_chat_11722005 = "上回你鑽的洞還沒有填平呢！",
  str_homestory_chat_11722006 = "你不滿意我規劃的地下撤退路線嗎？",
  str_homestory_chat_11722007 = "倒......倒也不是，就是鑽洞之前，好歹通知我一聲。",
  str_homestory_chat_11722008 = "明白啦，明白啦！我會記住的！",
  str_homestory_chat_11751001 = "那魚在什麼地方？",
  str_homestory_chat_11751002 = "啊！撤退！",
  str_homestory_chat_11751003 = "撤退？喂喂……",
  str_homestory_chat_11751004 = "你、你不是來抓我的？",
  str_homestory_chat_11751005 = "抓妳？妳做了什麼？",
  str_homestory_chat_11751006 = "就那個……不是為了方便撤退嗎？我就想著在空庭裡挖個地道什麼的。",
  str_homestory_chat_11751007 = "到時候真的要守不住了，就從那裡一溜煙地逃跑！啊不，撤退～",
  str_homestory_chat_11751008 = "哦，真是有勞妳了。",
  str_homestory_chat_11751009 = "就在挖地道的時候，看到了那個魚，對了！你是不是就是為了這件事而來的？",
  str_homestory_chat_11751010 = "啊？對哦，反正那地道好像沒什麼用，丘布們又堵上了。",
  str_homestory_chat_11751011 = "堵！！！",
  str_homestory_chat_11751012 = "那還怎麼撤退！萬一真的有事怎麼辦！！！",
  str_homestory_chat_11751013 = "不會的，而且妳挖這個地道也沒經過我同意啊。",
  str_homestory_chat_11751014 = "說的也是……",
  str_homestory_chat_11751015 = "對了，我是來問魚的，妳在哪裡看到的？地道附近？",
  str_homestory_chat_11751016 = "其實有點距離，現在暫時不太想說，挖地道太累了……",
