  str_homestory_chat_11922008 = "不......不，還是算了吧......",
  str_homestory_chat_11922009 = "還是不了吧......",
  str_homestory_chat_11922010 = "我看到您眼中流露出了恐懼。",
  str_homestory_chat_11922011 = "何必畏懼，這一次的飲品，可由您挑選。",
  str_homestory_chat_11923001 = "在看書？",
  str_homestory_chat_11923002 = "我很喜歡在這裡讀一些東西。",
  str_homestory_chat_11923003 = "在這裡，總是能找到安靜的地方，遠離一切喧囂......",
  str_homestory_chat_11923004 = "讓我去探索古籍最深處的奧義。",
  str_homestory_chat_11923005 = "這是肯定嗎？",
  str_homestory_chat_11923006 = "當然。",
  str_homestory_chat_11923007 = "你作為這裡的守護者，理應受到我的讚美。",
  str_homestory_chat_11924001 = "妳有話要和我說？",
  str_homestory_chat_11924002 = "有件事需要與您商量。",
