  str_homestory_chat_10921002 = "我的朋友，我能暫時將白箱託付給您嗎？",
  str_homestory_chat_10921003 = "不要......",
  str_homestory_chat_10921004 = "在這樣的天氣下，您的拒絕格外冷酷啊。",
