  str_homestory_chat_10923007 = "踏上去往真理國度的道路嗎？",
  str_homestory_chat_10923008 = "......我覺得不需要呢。",
  str_homestory_chat_10599999 = "你......你好呀......",
  str_homestory_chat_10521001 = "今天是蜜雅嗎？",
  str_homestory_chat_10521002 = "是啊，她......還在沉睡呢。",
  str_homestory_chat_10522001 = "今天天氣不錯",
