  str_homestory_chat_17021004 = "噢，那叫你什麼呢？小鬼，你可以自己挑一個。",
  str_homestory_chat_17021005 = "我會考慮的。",
  str_homestory_chat_17021006 = "這，這個......",
  str_homestory_chat_17022001 = "感覺這裡如何？",
  str_homestory_chat_17022002 = "這裡比影鎮要好。",
  str_homestory_chat_17022003 = "為什麼忽然這麼說？",
  str_homestory_chat_17022004 = "因為桑咚——在這裡，牠想飛就飛，飛多高都可以。",
