  str_homestory_chat_18221003 = "頂著這對巨大的角走路......好累......",
  str_homestory_chat_18221004 = "要不要我幫妳托一會？",
  str_homestory_chat_18221005 = "別，別碰我的角......您會很危險的！",
  str_homestory_chat_18222001 = "有什麼事？",
  str_homestory_chat_18222002 = "我想告訴您......",
  str_homestory_chat_18222003 = "我很喜歡這裡！可以隨意探險，又不用擔心被暗鬼追逐。",
  str_homestory_chat_18222004 = "今天，我要開啟新的冒險之旅了，請祝我旅途順利吧！",
  str_homestory_chat_18222005 = "好，旅途愉快，一路順風！",
  str_homestory_chat_19299999 = "......",
  str_homestory_chat_19201001 = "妳好",
  str_homestory_chat_19201002 = "你和我打招呼做什麼？",
  str_homestory_chat_19201003 = "你和我打了招呼，我就一定要和你打招呼嗎？",
  str_homestory_chat_19201004 = "呃，呃......",
  str_homestory_chat_19201005 = "行，我說一句「你好」，你會滿意嗎？",
  str_homestory_chat_19221001 = "要聊天嗎？",
  str_homestory_chat_19221002 = "聊天？你想聊什麼？",
  str_homestory_chat_19221003 = "不過，話說在前面，你和我聊天，我不一定會回答你。",
  str_homestory_chat_19221004 = "這不是已經在回答了嗎？",
  str_homestory_chat_19221005 = "......我不一定回答——我也有可能回答，明白了嗎？",
  str_homestory_chat_19221006 = "行，我放棄和妳聊天",
  str_homestory_chat_19221007 = "你怎麼能這麼輕易就放棄呢？",
  str_homestory_chat_19221008 = "因為別人的幾句話就放棄一件事，你不覺得這樣不好嗎？",
  str_homestory_chat_19221009 = "......",
  str_homestory_chat_19222001 = "妳在想什麼？",
  str_homestory_chat_19222002 = "你覺得昨天的晚餐好吃嗎？",
  str_homestory_chat_19222003 = "好吃！",
  str_homestory_chat_19222004 = "我真沒辦法理解你的口味，你怎麼會覺得好吃呢？",
  str_homestory_chat_19222005 = "配菜裡有蘿蔔！蘿蔔會毀掉一整道菜餚，你不知道嗎？",
  str_homestory_chat_19222006 = "是嗎？我還真不知道。",
  str_homestory_chat_19222007 = "不好吃......",
  str_homestory_chat_19222008 = "你為什麼會覺得不好吃？",
  str_homestory_chat_19222009 = "我問了好幾個人，都說不好吃。",
  str_homestory_chat_19222010 = "你們太奇怪了。雖然說有一些不常見的菜餚，比如烤蜥蜴......",
  str_homestory_chat_19222011 = "但也不至於到不好吃的地步吧？",
  str_homestory_chat_19222012 = "呃，這......",
  str_homestory_chat_19223001 = "筆記好多......",
  str_homestory_chat_19223002 = "PlayerName，需要我幫你整理嗎？",
  str_homestory_chat_19223003 = "我今天有不少空閒時間。",
  str_homestory_chat_19223004 = "好啊！",
  str_homestory_chat_19223005 = "不過，我得先找找我的筆記......",
  str_homestory_chat_19223006 = "居然連閱讀筆記都不收好，你也太沒有條理了。",
  str_homestory_chat_19223007 = "等一下，我也去幫你收拾。",
  str_homestory_chat_19223008 = "我根本沒有閱讀筆記......",
  str_homestory_chat_19223009 = "居然有人閱讀不做筆記，你是不會做筆記嗎？",
  str_homestory_chat_19223010 = "不會的話，就來請教我啊。",
  str_homestory_chat_14599999 = "您好。",
  str_homestory_chat_14501001 = "你好，聖釘",
  str_homestory_chat_14501002 = "您的問候讓我這個罪人感到惶惑。",
  str_homestory_chat_14501003 = "不過，我會忍受這種惶惑的。",
  str_homestory_chat_14501004 = "......打個招呼，造成的後果有這麼嚴重嗎？",
  str_homestory_chat_14521001 = "你在懺悔？",
  str_homestory_chat_14521002 = "您要和我一起嗎？",
  str_homestory_chat_14521003 = "不要......",
  str_homestory_chat_14521004 = "說得也是，像您這樣生活在陽光下的人，必不會像我一樣——",
  str_homestory_chat_14521005 = "滿身罪孽，必須用懺悔才能洗刷......",
  str_homestory_chat_14521006 = "呃......這......反省雖好，但也不宜過多......",
  str_homestory_chat_14521007 = "也可以......",
  str_homestory_chat_14521008 = "來吧，跟隨我，面對真理，訴說自己的罪惡吧。",
  str_homestory_chat_14521009 = "......罪惡？這個詞會不會太嚴重了點？",
  str_homestory_chat_14522001 = "你怎麼了？",
  str_homestory_chat_14522002 = "......這裡的陽光，太過刺眼了。",
  str_homestory_chat_14522003 = "你很討厭陽光嗎？",
  str_homestory_chat_14522004 = "我怎麼會討厭陽光？",
  str_homestory_chat_14522005 = "應該是......陽光不願照耀我這樣的罪人吧。",
  str_homestory_chat_14522006 = "你是不是不能曬太陽？",
  str_homestory_chat_14522007 = "我在故事書裡看到，有一些生物曬到太陽就會受傷。",
  str_homestory_chat_14522008 = "我確實會被太陽曬傷......只不過，受到傷害的不是身體——",
  str_homestory_chat_14522009 = "而是我承載著罪孽的心。",
  str_homestory_chat_14522010 = "......",
  str_homestory_chat_14523001 = "你的身上......",
  str_homestory_chat_14523002 = "不用擔心我身上的血跡。",
  str_homestory_chat_14523003 = "想讓血跡乾涸，於我而言，不是一件容易的事。",
  str_homestory_chat_14523004 = "你又打架了？",
  str_homestory_chat_14523005 = "這段時間，我很少犯下這種罪孽。",
  str_homestory_chat_14523006 = "那就好......不過，你還是先去止下血吧。",
  str_homestory_chat_14523007 = "你又扎自己了？",
  str_homestory_chat_14523008 = "我只是在釋放自己的能力......不過，或許，這也是一種贖罪的方式。",
  str_homestory_chat_14523009 = "流淌的血液，讓我感受到真實。",
  str_homestory_chat_14523010 = "我覺得你還是止住血比較好。",
  str_homestory_chat_14523011 = "既然是您的要求，我會考慮的。",
  str_homestory_chat_16899999 = "PlayerName，你好呀！",
  str_homestory_chat_16801001 = "妳好呀！溫蒂！",
  str_homestory_chat_16801002 = "今天你沒有新信件喔！",
  str_homestory_chat_16801003 = "好的，我知道啦。",
  str_homestory_chat_16801004 = "沒有信件，不要傷心。溫蒂可以給你寫一封！",
  str_homestory_chat_16821001 = "找我？",
  str_homestory_chat_16821002 = "哇，我的羽毛上是不是粘了什麼臟東西！",
  str_homestory_chat_16821003 = "快幫我看看！",
  str_homestory_chat_16821004 = "沒有啊......",
  str_homestory_chat_16821005 = "真的嗎？可是為什麼感覺有些不對勁。",
  str_homestory_chat_16821006 = "真想狠狠地扇兩下翅膀！",
  str_homestory_chat_16821007 = "等......等一下再扇，我還在這裡！",
  str_homestory_chat_16821008 = "在這裡！",
  str_homestory_chat_16821009 = "快......快幫我弄下來！",
  str_homestory_chat_16821010 = "哈哈，我騙妳的。",
  str_homestory_chat_16821011 = "......可惡，你是不是想被我扇一下？",
  str_homestory_chat_16822001 = "妳似乎很悠閒的樣子",
  str_homestory_chat_16822002 = "在這裡待久了，有點無聊......",
  str_homestory_chat_16822003 = "為什麼？",
  str_homestory_chat_16822004 = "這裡的土地，根本踢不起來沙子呢......",
  str_homestory_chat_16822005 = "在紅油沙漠，踢擊揚起飛沙，又酷又厲害。",
  str_homestory_chat_16822006 = "在這裡，踢擊沒有了飛沙，好像也沒有那麼厲害了......",
  str_homestory_chat_16822007 = "......明白了，我會幫你找一片沙地的。",
