  str_homestory_chat_16823002 = "沒錯！",
  str_homestory_chat_16823003 = "那麼......是哪方面的呢？",
  str_homestory_chat_16823004 = "主要是材料啦，這裡有又輕又結實的材料嗎？",
  str_homestory_chat_16823005 = "因為我飛得很快，加上在風沙地區，磨損得很厲害的！",
  str_homestory_chat_16823006 = "材料嗎......去影鎮不就行了，那邊什麼布料都有的。",
  str_homestory_chat_16823007 = "主要是影鎮的布料太貴了！而且黑心商人很多！",
