  str_homestory_chat_16823009 = "原來這才是妳的目的啊......",
  str_homestory_chat_16824001 = "妳在看什麼？",
  str_homestory_chat_16824002 = "我？我沒在看什麼呀，我在感受風。",
  str_homestory_chat_16824003 = "這裡太安靜了，什麼風也沒有，有什麼風比較強烈的地方嗎？",
  str_homestory_chat_16824004 = "沒有。",
  str_homestory_chat_16824005 = "......這裡果然是個安靜的地方，只能說實在太安靜了。",
  str_homestory_chat_16824006 = "渾身都發癢，恨不得我自己轉幾圈弄個小颶風出來。",
