  str_homestory_chat_16824010 = "因為在沙漠上飛行，會經常遇到強風的！",
  str_homestory_chat_16824011 = "那妳直接在紅油沙漠測試不就可以了......",
  str_homestory_chat_16825001 = "妳在找快遞？",
  str_homestory_chat_16825002 = "對，似乎貨物包裹又丟了！",
