  str_homestory_chat_16825004 = "那就是丟了，只不過丟在哪裡，我不能確認。",
  str_homestory_chat_16825005 = "反正應該是在這一帶......沒關係啦。",
  str_homestory_chat_16825006 = "沒......沒關係？",
  str_homestory_chat_16825007 = "對呀。",
  str_homestory_chat_16825008 = "妳這個信使的工作態度，也太隨便了吧。",
