  str_homestory_chat_15901003 = "嗚，好感動的說。",
  str_homestory_chat_15921001 = "住得習慣嗎？",
  str_homestory_chat_15921002 = "在這裡，我終於過上了夢寐以求的生活！",
  str_homestory_chat_15921003 = "像我這種普通的傢伙，最適合待在這裡的說！",
  str_homestory_chat_15921004 = "妳很喜歡這裡？",
