  str_homestory_chat_19623008 = "這樣啊......我應該多放點牛奶和方糖的......",
  str_homestory_chat_19623009 = "畢竟，很少有人和我一樣，喜歡喝苦咖啡。",
  str_homestory_chat_19624001 = "感覺這裡怎麼樣？",
  str_homestory_chat_19624002 = "這裡的人都很友善呢。",
  str_homestory_chat_19624003 = "很高興妳這麼想！",
  str_homestory_chat_19624004 = "我剛到影鎮的時候，被騙走了不少錢。",
  str_homestory_chat_19624005 = "而在這裡，我從來沒有遇到過騙子。",
