  str_homestory_chat_20325001 = "妳要訓練？",
  str_homestory_chat_20325002 = "對，最近在這裡待太久了，總覺得審訊技巧都生疏了。",
  str_homestory_chat_20325003 = "那種事不練也行……",
  str_homestory_chat_20325004 = "怎麼可以！這可是我唯一的樂趣——啊不，拿手絕活。",
  str_homestory_chat_20325005 = "妳就直說想審訊什麼吧。很可惜這裡不行的。",
  str_homestory_chat_20325006 = "怎麼可以這樣！",
  str_homestory_chat_20325007 = "都來到空庭了，還是好好享受生活吧……",
  str_homestory_chat_20325008 = "享受……對我來說，審訊也是一種享受啊。",
  str_homestory_chat_20325009 = "還是……就拿丘布來練手？牠們看起來方方正正白白胖胖的。",
  str_homestory_chat_20325010 = "絕對！不行！",
  str_homestory_chat_20326001 = "宿舍……",
  str_homestory_chat_20326002 = "你怎麼知道？我隨便說一句，就傳到你耳裡了。",
  str_homestory_chat_20326003 = "既然你來問，正好省得我去找你。我要蓋一間宿舍，你覺得怎麼樣？",
  str_homestory_chat_20326004 = "為什麼？",
  str_homestory_chat_20326005 = "先別問為什麼，你就說答不答應就好？",
  str_homestory_chat_20326006 = "那可不行！一定要先說出妳的意圖。",
  str_homestory_chat_20326007 = "不行吧……",
  str_homestory_chat_20326008 = "啊？還沒問就不行，為什麼？",
  str_homestory_chat_20326009 = "總覺得有問題。妳到底為什麼要蓋宿舍？",
  str_homestory_chat_20326010 = "嗯……是為維多利亞大人蓋的啦。",
