  str_homestory_chat_20326013 = "我、我考慮一下吧。",
  str_homestory_chat_19399999 = "你好啊，年輕人。",
  str_homestory_chat_19301001 = "妳好，彌加德",
  str_homestory_chat_19301002 = "今天下定決心來做我的解剖對象了嗎？",
  str_homestory_chat_19301003 = "沒......沒有！絕對沒有！",
  str_homestory_chat_19301004 = "那就再給你一點時間考慮吧。",
  str_homestory_chat_19321001 = "有空嗎？",
  str_homestory_chat_19321002 = "年輕人，想和我聊什麼？",
  str_homestory_chat_19321003 = "最好是有趣一點的。那些瑣碎小事，我可沒心情聽你講。",
  str_homestory_chat_19321004 = "啊......那我該怎麼做？",
  str_homestory_chat_19321005 = "你在心裡評判一下，自己即將講的事情夠不夠有趣。",
  str_homestory_chat_19321006 = "......",
  str_homestory_chat_19321007 = "我決定放棄開口。",
  str_homestory_chat_19321008 = "嗯，很好。",
  str_homestory_chat_19322001 = "待得還習慣嗎？",
  str_homestory_chat_19322002 = "挺舒服的，就是有時候有些無聊。",
  str_homestory_chat_19322003 = "要是有酒就好了。",
  str_homestory_chat_19322004 = "這裡有很多酒啊......",
