  str_homestory_chat_19322009 = "要不然，我列個清單，你去訂購一批？",
  str_homestory_chat_19322010 = "也可以。",
  str_homestory_chat_19323001 = "今天要做什麼？",
  str_homestory_chat_19323002 = "感覺很適合睡覺，你不覺得嗎？",
  str_homestory_chat_19323003 = "不覺得......",
  str_homestory_chat_19323004 = "一想到還有那麼多事沒做完，我就完全睡不著。",
  str_homestory_chat_19323005 = "那你去忙吧，我先去睡覺了。",
