  str_homestory_chat_19323008 = "你與我所見略同。",
  str_homestory_chat_19323009 = "那走吧，一起去睡覺。",
  str_homestory_chat_19323010 = "......不......不，等等，我......我還有事沒做完！",
  str_homestory_chat_19799999 = "你好，PlayerName。",
  str_homestory_chat_19701001 = "你好",
  str_homestory_chat_19701002 = "你生病了嗎？",
  str_homestory_chat_19701003 = "......沒有啊，為什麼會這麼問？",
  str_homestory_chat_19701004 = "如果有人這樣問候我，那麼他很有可能是來找我看病的。",
