  str_homestory_chat_19721002 = "如果有需要的話，我可以在這裡推廣我的洗手方法。",
  str_homestory_chat_19721003 = "好啊！",
  str_homestory_chat_19721004 = "這樣一來，大家會更不容易生病吧。",
