  str_homestory_chat_19721006 = "洗上五分鐘。",
  str_homestory_chat_19721007 = "......啊這......",
  str_homestory_chat_19721008 = "應該不用吧......",
  str_homestory_chat_19721009 = "畢竟不是所有人都願意洗五分鐘的手......",
  str_homestory_chat_19721010 = "......你觀察過我洗手嗎？",
  str_homestory_chat_19722001 = "你討厭陽光嗎？",
