  str_homestory_chat_18723002 = "這裡很安全，不用隨時都緊繃繃的。",
  str_homestory_chat_18723003 = "我既然受你的邀請來到這裡，就會保護好這裡的平民。",
  str_homestory_chat_18723004 = "那......感謝你的幫助。",
  str_homestory_chat_18723005 = "不必言謝，擁有貴族的身分，就必須盡到貴族的責任。",
  str_homestory_chat_18723006 = "雖然在這裡，沒有地位的差異——",
  str_homestory_chat_18723007 = "但是，我的實力也是身分的組成部分。",
  str_homestory_chat_15699999 = "你好，孩子，今天過得怎麼樣？",
  str_homestory_chat_15601001 = "很不錯！",
  str_homestory_chat_15601002 = "我很欣慰能聽到這樣的回答。",
  str_homestory_chat_15621001 = "在想什麼呢？",
  str_homestory_chat_15621002 = "這裡的夜晚，很適合獨自一人靜坐。",
  str_homestory_chat_15621003 = "你想來試試嗎？",
  str_homestory_chat_15621004 = "可以啊！",
  str_homestory_chat_15621005 = "我會替你挑選個安靜的好位置。",
  str_homestory_chat_15621006 = "別忘了我們的約定。",
  str_homestory_chat_15621007 = "還是不要了......",
  str_homestory_chat_15621008 = "你害怕嗎？",
  str_homestory_chat_15621009 = "不用擔心，在這裡，沒有什麼能傷害你。",
  str_homestory_chat_15622001 = "你在這裡住得習慣嗎？",
  str_homestory_chat_15622002 = "這裡甚至比北境更好——",
  str_homestory_chat_15622003 = "真沒想到，我會在這裡安定下來。",
  str_homestory_chat_15622004 = "不久前，我還以為「安家」對我來說，是一件很遙遠的事。",
  str_homestory_chat_15622005 = "那就好......",
  str_homestory_chat_15622006 = "說實話，這裡的氣溫要舒適很多。",
  str_homestory_chat_15622007 = "北境實在冷得過分......",
  str_homestory_chat_15622008 = "這樣我就放心了。",
  str_homestory_chat_19599999 = "您好，先生，有什麼吩咐嗎？",
  str_homestory_chat_19501001 = "暫時沒有",
  str_homestory_chat_19501002 = "無論什麼事，只要不超出我的能力範圍，我一定能做到最好。",
  str_homestory_chat_19501003 = "那就先謝謝了。",
  str_homestory_chat_19521001 = "妳剛才手裡拿著的是什麼？",
  str_homestory_chat_19521002 = "是野果，先生。",
  str_homestory_chat_19521003 = "最近我在樹林裡找到不少野果。",
  str_homestory_chat_19521004 = "需要我帶您去看看嗎？",
  str_homestory_chat_19521005 = "好啊！",
  str_homestory_chat_19521006 = "不過，我現在還有些其他事要做......",
