  str_homestory_chat_19521008 = "等您有空，我再來找您。",
  str_homestory_chat_19521009 = "不了......",
  str_homestory_chat_19521010 = "沒關係，我可以替您摘一些回來嚐嚐。",
  str_homestory_chat_19521011 = "好啊，謝謝妳！",
  str_homestory_chat_19522001 = "住得還好嗎？",
  str_homestory_chat_19522002 = "這裡有不少舒適的洞穴，我已經在裡面放了不少東西了。",
  str_homestory_chat_19522003 = "您可以隨時來參觀。",
  str_homestory_chat_19522004 = "妳更喜歡住在洞穴裡？",
