  str_homestory_chat_19522006 = "或許，您並不會介意？",
  str_homestory_chat_16299999 = "你好，PlayerName，很高興見到你。",
  str_homestory_chat_16201001 = "你今天有什麼打算嗎？",
  str_homestory_chat_16201002 = "或許，我會去樹林裡散散步。",
  str_homestory_chat_16221001 = "看來你很喜歡這裡",
  str_homestory_chat_16221002 = "感謝你，PlayerName，邀請我來到這裡。",
  str_homestory_chat_16221003 = "在這裡，我又認識不少朋友。",
  str_homestory_chat_16221004 = "那就好",
  str_homestory_chat_16221005 = "只要能交到真誠的朋友，在哪裡都無所謂。",
