  str_homestory_chat_16222006 = "這不好吧......",
  str_homestory_chat_16222007 = "啊，這樣啊......",
  str_homestory_chat_16222008 = "我把它們種在花盆裡，也不可以嗎？",
  str_homestory_chat_16223001 = "妳似乎有感而發？",
  str_homestory_chat_16223002 = "是的，每次到這裡，都不禁感嘆此地的地利。",
  str_homestory_chat_16223003 = "地利？",
  str_homestory_chat_16223004 = "隱祕、安全，氣候宜人，水草豐美。",
