  str_homestory_chat_16223006 = "聽說妳之前守護的風脈之森，不就是這樣的地方嗎？",
  str_homestory_chat_16223007 = "我記得在北境也是一個好去處。",
  str_homestory_chat_16223008 = "那只是對北境而言。跟空庭比起來，還是這裡好。",
  str_homestory_chat_16223009 = "有時我甚至會胡思亂想，如果能成為這裡的守護者……",
