  str_homestory_chat_16224001 = "水？",
  str_homestory_chat_16224002 = "是的，請問導航員瞭解水嗎？",
  str_homestory_chat_16224003 = "瞭解。",
  str_homestory_chat_16224004 = "那莉亞製造的水泡，你知道是怎麼回事嗎？",
  str_homestory_chat_16224005 = "這個……我不知道。",
  str_homestory_chat_16224006 = "不瞭解。",
  str_homestory_chat_16224007 = "唉……看來想要知道莉亞那個水泡，還得問別人。",
