  str_homestory_chat_16224015 = "但那顆種子卻在陽光下帶著神奇的祖母綠光澤。",
  str_homestory_chat_16224016 = "水……真奇妙，就和莉亞一樣。",
  str_homestory_chat_16224017 = "原來如此……",
