  str_homestory_chat_16723001 = "妳在找什麼？",
  str_homestory_chat_16723002 = "這裡的草地裡會不會藏著小精靈呀？",
  str_homestory_chat_16723003 = "有可能......",
  str_homestory_chat_16723004 = "那我可以邀請你一起找小精靈嗎？",
