  str_homestory_chat_16723006 = "應該沒有吧？",
  str_homestory_chat_16723007 = "沒有小精靈，應該會有地精吧！",
  str_homestory_chat_16723008 = "讓我來找一找～",
  str_homestory_chat_13099999 = "PlayerName，又見到你了啊！",
  str_homestory_chat_13001001 = "你好，醒山",
  str_homestory_chat_13001002 = "你怎麼好像整天都在這裡閒逛？",
  str_homestory_chat_13001003 = "......我明明很忙的，好嗎？",
  str_homestory_chat_13021001 = "你在幹什麼？",
  str_homestory_chat_13021002 = "PlayerName，這裡有垃圾可以撿嗎？",
  str_homestory_chat_13021003 = "為什麼要撿垃圾？",
  str_homestory_chat_13021004 = "廢話，當然是因為垃圾裡藏著好東西——",
  str_homestory_chat_13021005 = "可以賣錢！",
