  str_homestory_chat_13021011 = "怎麼聽起來那麼像古代科技？",
  str_homestory_chat_13022001 = "你在找我？",
  str_homestory_chat_13022002 = "PlayerName，什麼時候，我們再去飈一次車？",
  str_homestory_chat_13022003 = "飆車？好啊！",
  str_homestory_chat_13022004 = "不過我得找個空閒的時候。",
  str_homestory_chat_13022005 = "行啊，你先想著。",
  str_homestory_chat_13022006 = "到時候還可以多叫些人——",
  str_homestory_chat_13022007 = "把這地方的人都叫出來看！",
  str_homestory_chat_13022008 = "還是不要了吧......",
  str_homestory_chat_13022009 = "飆車這件事，已經給我留下心理陰影了......",
  str_homestory_chat_13022010 = "那更得帶你再去飆一次，幫你好好治治心理陰影。",
  str_homestory_chat_13023001 = "你看起來很閒的樣子......",
  str_homestory_chat_13023002 = "是啊啊啊！好無聊！已經好久沒搶劫了！",
  str_homestory_chat_13023003 = "你不會想搶這裡吧？！",
  str_homestory_chat_13023004 = "就是因為不能搶這裡，你看把我給憋的！",
  str_homestory_chat_13023005 = "以後有什麼值錢的玩意，少在我面前秀......",
  str_homestory_chat_13023006 = "我怕我忍不住，把東西給搶了。",
  str_homestory_chat_20599999 = "你好呀，PlayerName～",
  str_homestory_chat_20501001 = "妳好，伊芙～",
  str_homestory_chat_20501002 = "今天發生了什麼好玩的事嗎？",
  str_homestory_chat_20501003 = "嗯......讓我想想。",
  str_homestory_chat_20501004 = "好，想好了就講給我聽吧！",
  str_homestory_chat_20521001 = "妳在找什麼？",
  str_homestory_chat_20521002 = "PlayerName，你看到我哥哥了嗎？",
  str_homestory_chat_20521003 = "沒有......",
  str_homestory_chat_20521004 = "咦，哥哥去哪裡了呢......",
  str_homestory_chat_20521005 = "如果你看到的話，一定要來告訴我啊！",
  str_homestory_chat_20521006 = "沒問題！",
  str_homestory_chat_20521007 = "在那裡。",
  str_homestory_chat_20521008 = "啊，謝謝你，PlayerName！",
