  str_homestory_chat_20522001 = "住得習慣嗎？",
  str_homestory_chat_20522002 = "我以為我在這裡待久了，會很想念紅油沙漠......",
  str_homestory_chat_20522003 = "沒想到，我適應得遠比想像中的好呢！",
  str_homestory_chat_20522004 = "那就好！",
  str_homestory_chat_20522005 = "大概是因為......熟悉的大家也在這裡......",
