  str_homestory_chat_20524006 = "定好了日子，一定要來告訴我啊！",
  str_homestory_chat_20524007 = "不知道呢......",
  str_homestory_chat_20524008 = "最近實在太忙了......",
  str_homestory_chat_20524009 = "這樣啊......不過，我可以幫PlayerName分擔一些事。",
  str_homestory_chat_20524010 = "還請千萬不要客氣！",
  str_homestory_chat_20499999 = "PlayerName？",
  str_homestory_chat_20401001 = "是的",
  str_homestory_chat_20401002 = "我聽出了你的聲音。",
  str_homestory_chat_20401003 = "僅靠聲音，不會把人弄混嗎？",
  str_homestory_chat_20401004 = "每個人的聲線都是不同的，只要你聽得夠仔細，就能分辨。",
  str_homestory_chat_20421001 = "妳怎麼辨別陰天啊？",
  str_homestory_chat_20421002 = "憑感覺——曬在皮膚上的陽光、頭髮的潮濕程度......",
  str_homestory_chat_20421003 = "不過......這裡氣候總是差不多的溫暖......",
  str_homestory_chat_20421004 = "有時候，我很難分清晴天和陰天。",
