  str_homestory_chat_20421006 = "所以，找個人問問，是最快的方法。",
  str_homestory_chat_20422001 = "妳能辨別花的品種嗎？",
  str_homestory_chat_20422002 = "透過花的香氣什麼的......",
  str_homestory_chat_20422003 = "當然可以！",
  str_homestory_chat_20422004 = "此外，我還能透過觸摸——在腦中勾勒花的形狀。",
  str_homestory_chat_20422005 = "以此來確定花的品種。",
  str_homestory_chat_20422006 = "想學的話，我可以教教你。",
  str_homestory_chat_20423001 = "妳在找什麼？",
  str_homestory_chat_20423002 = "你知道伊芙在哪裡嗎？",
  str_homestory_chat_20423003 = "她不在這裡......",
  str_homestory_chat_20423004 = "......我好像已經很久沒聽到過她的聲音了。",
  str_homestory_chat_20423005 = "不知道她有沒有照顧好我們的黎花。",
  str_homestory_chat_20423006 = "就在那邊",
  str_homestory_chat_20423007 = "需要我帶妳過去嗎？",
