  str_homestory_chat_21322001 = "不了，那綢帶......",
  str_homestory_chat_21322002 = "嗯？你很好奇我手腕上的綢帶？",
  str_homestory_chat_21322003 = "綢帶能解開嗎？",
  str_homestory_chat_21322004 = "暫時不能——原來，你沒有發現？",
  str_homestory_chat_21322005 = "發現什麼？",
  str_homestory_chat_21322006 = "戰鬥前，我會解開綢帶上的一個結——",
  str_homestory_chat_21322007 = "以便釋放光能術的力量。",
  str_homestory_chat_21322008 = "平時的話，還是不要解開為妙。",
  str_homestory_chat_21322009 = "原來如此......",
  str_homestory_chat_21323001 = "那樂曲有點難懂......",
  str_homestory_chat_21323002 = "是嗎？不過這裡似乎有不少懂音樂的人......",
  str_homestory_chat_21323003 = "都有誰？",
  str_homestory_chat_21323004 = "......我不是很清楚他們的名字，不過，我聽過他們演奏樂器——",
  str_homestory_chat_21323005 = "比白夜城的那些傢伙好上許多。",
  str_homestory_chat_21323006 = "我可以為你介紹他們",
  str_homestory_chat_21323007 = "說實話，他們中的大部分，我都叫不出名字......",
  str_homestory_chat_21323008 = "你願替我引薦，那是再好不過的。",
  str_homestory_chat_21323009 = "我就先謝謝你了。",
  str_homestory_chat_21324001 = "有新的樂曲？",
  str_homestory_chat_21324002 = "沒有......PlayerName，你最近有沒有發現新樂譜？",
  str_homestory_chat_21324003 = "有啊！",
  str_homestory_chat_21324004 = "在哪裡？可以帶我去看看嗎？",
  str_homestory_chat_21324005 = "或者你替我先買下，我稍後給你錢......",
