  str_homestory_chat_21324007 = "好的，你快想。",
  str_homestory_chat_21324008 = "沒有......",
  str_homestory_chat_21324009 = "既然這樣......你下次要是看到了，務必告訴我！",
  str_homestory_chat_21324010 = "沒問題！",
  str_homestory_chat_21499999 = "找我有什麼事嗎？",
  str_homestory_chat_21421001 = "沒什麼事",
  str_homestory_chat_21421002 = "你想和我喝一杯？",
  str_homestory_chat_21421003 = "只是打個招呼啦。",
  str_homestory_chat_21421004 = "不過，妳想喝酒的話，我可以請妳。",
  str_homestory_chat_21422001 = "天氣很不錯呀",
  str_homestory_chat_21422002 = "這種天氣很適合出去騎馬。",
  str_homestory_chat_21422003 = "PlayerName，你覺得呢？",
  str_homestory_chat_21422004 = "我也覺得很適合",
  str_homestory_chat_21422005 = "和我一起去騎著馬遛個彎？",
  str_homestory_chat_21422006 = "......等一下，我是不是還得替你找匹馬？",
  str_homestory_chat_21422007 = "不太好吧......",
  str_homestory_chat_21422008 = "哪裡不好了？",
  str_homestory_chat_21422009 = "說出你的理由，不然我會困惑一整天的。",
