  str_homestory_chat_21423003 = "饞什麼？",
  str_homestory_chat_21423004 = "自然是酒，尤其是琴酒——",
  str_homestory_chat_21423005 = "算來，我已經有兩天再加五個小時沒喝上琴酒了。",
