  str_homestory_chat_22701001 = "對呀",
  str_homestory_chat_22701002 = "啊......有點開心呢......",
  str_homestory_chat_22721001 = "有什麼事？",
  str_homestory_chat_22721002 = "最近......有沒有人投訴我？",
  str_homestory_chat_22721003 = "沒有啊",
  str_homestory_chat_22721004 = "那......那就好......",
