  str_homestory_chat_22122003 = "那就好",
  str_homestory_chat_22122004 = "沒什麼人嚷嚷一些虛偽的信條。",
  str_homestory_chat_22122005 = "我的耳朵終於能長時間清淨了。",
  str_homestory_chat_22122006 = "我想，這應該歸功於你。",
  str_homestory_chat_22123001 = "有什麼新鮮事嗎？",
