  str_homestory_chat_22123007 = "直到你回應我......可能是這樣吧。",
  str_homestory_chat_22123008 = "那你恐怕要講到口乾舌燥了。",
  str_homestory_chat_22124001 = "聽說這裡發現了妳的荊棘。",
  str_homestory_chat_22124002 = "對，那其實是我種的。",
  str_homestory_chat_22124003 = "種的……為什麼？",
  str_homestory_chat_22124004 = "話說，你覺得荊棘是一種什麼樣的植物？",
