  str_homestory_chat_22127001 = "今天天氣好像還不錯。",
  str_homestory_chat_22127002 = "確實，不過此地都是這樣的天氣，你為何這樣說？",
  str_homestory_chat_22127003 = "只是在搭話。",
  str_homestory_chat_22127004 = "因為確實很不錯。",
  str_homestory_chat_22127005 = "唉，你最近難道連開場白都不會好好說了嗎。",
  str_homestory_chat_22127006 = "可惜了有這麼多夥伴可以讓你練習。",
  str_homestory_chat_22127007 = "夥伴又不是用來練習交流的……",
  str_homestory_chat_22127008 = "那你就想錯了。",
  str_homestory_chat_22127009 = "喔？",
  str_homestory_chat_22127010 = "既然成為你的夥伴，願意來到空庭，那就代表他們願意和你交流。",
  str_homestory_chat_22127011 = "比方說聊聊日常，或是隨便談天說地，甚至是……",
  str_homestory_chat_22127012 = "嗯，某些特別的思考。",
  str_homestory_chat_22127013 = "因此他們也願意接受你的開場白練習，無論有多尷尬。",
  str_homestory_chat_22127014 = "比如說這個「天氣不錯」，如果那天的天氣不行呢？",
  str_homestory_chat_22127015 = "那就換成「好糟糕的天氣」？",
  str_homestory_chat_22127016 = "喔！你終於明白了！",
  str_homestory_chat_22127017 = "啊？只是這樣？真的？",
  str_homestory_chat_22128001 = "暗鬼？",
  str_homestory_chat_22128002 = "感覺有必要討論一下牠們的問題。",
  str_homestory_chat_22128003 = "是此地的安全？放心，這裡很偏僻，暗鬼跑不到這裡的。",
  str_homestory_chat_22128004 = "不是那樣的問題，是暗鬼究竟為什麼攻擊我們，你有沒有想過？",
  str_homestory_chat_22128005 = "有。",
  str_homestory_chat_22128006 = "喔？是什麼原因？",
  str_homestory_chat_22128007 = "或許是牠們的本能吧。",
  str_homestory_chat_22128008 = "本能嗎……",
  str_homestory_chat_22128009 = "沒有。",
  str_homestory_chat_22128010 = "或許……是牠們的本能？",
  str_homestory_chat_22128011 = "有可能。",
  str_homestory_chat_21599999 = "您好啊，PlayerName。",
  str_homestory_chat_21501001 = "妳好，納努塞爾",
  str_homestory_chat_21501002 = "願今天的您也能在自然之力的護佑下，度過美好的一天。",
  str_homestory_chat_21501003 = "啊，謝謝妳的祝福。",
  str_homestory_chat_21501004 = "這是我應該做的。",
  str_homestory_chat_21521001 = "看來妳熟悉這裡",
  str_homestory_chat_21521002 = "是的，我已經徹底瞭解了。",
  str_homestory_chat_21521003 = "您若是需要往附近運送一些物件，可以隨時來找我。",
  str_homestory_chat_21521004 = "好啊！",
  str_homestory_chat_21521005 = "給這裡的光靈遞送信件，我也完全可以勝任。",
  str_homestory_chat_21521006 = "謝謝妳！",
  str_homestory_chat_21521007 = "還是不麻煩了......",
  str_homestory_chat_21521008 = "您邀請我入住這裡，我還沒能感謝您。",
  str_homestory_chat_21521009 = "把這些小小的工作交給我，就當是我的謝禮吧。",
  str_homestory_chat_21522001 = "天氣很好呀",
  str_homestory_chat_21522002 = "這裡和煦的天氣，真是令人心曠神怡啊。",
  str_homestory_chat_21522003 = "即便降溫，也不會太冷。",
  str_homestory_chat_21522004 = "妳很怕冷？",
  str_homestory_chat_21522005 = "我的身體難以承受太過寒冷的天氣......",
  str_homestory_chat_21522006 = "妳喜歡溫暖的地方？",
  str_homestory_chat_21522007 = "我對氣溫沒有特別的喜惡，它們都是自然的一部分。",
  str_homestory_chat_21522008 = "只是，我不適合長久地待在寒冷之地。",
  str_homestory_chat_21522009 = "所以，這裡的氣候於我而言，剛剛好。",
  str_homestory_chat_21523001 = "平時都在這裡做些什麼？",
  str_homestory_chat_21523002 = "......您問我？",
  str_homestory_chat_21523003 = "對",
  str_homestory_chat_21523004 = "因為我常找不到妳......",
  str_homestory_chat_21523005 = "嗯......那大概是因為，我太喜歡去樹林裡散步了。",
  str_homestory_chat_21523006 = "如果您想放鬆的話，也可以與我一起去散散步。",
  str_homestory_chat_16599999 = "禮好哇，先森！",
  str_homestory_chat_16501001 = "妳好哇，塔塔",
  str_homestory_chat_16501002 = "今天需要塔塔當你滴信屬嗎？",
  str_homestory_chat_16501003 = "謝謝啦，暫時還不用。",
  str_homestory_chat_16521001 = "妳在找什麼？",
  str_homestory_chat_16521002 = "先森先森，這裡有雪花嗎？",
  str_homestory_chat_16521003 = "有啊！",
  str_homestory_chat_16521004 = "這裡有不少人能製造雪花呢。",
  str_homestory_chat_16521005 = "在哪裡在哪裡？偶要去早他們！",
  str_homestory_chat_16521006 = "沒有吧......",
  str_homestory_chat_16521007 = "怎滴沒有嗎......",
  str_homestory_chat_16521008 = "那塔塔用製冰器製作一些吧！",
  str_homestory_chat_16522001 = "妳要和我說什麼？",
  str_homestory_chat_16522002 = "先森，塔塔縮話很好笑嗎？",
  str_homestory_chat_16522003 = "以前偶送信滴時候，只要縮話，總會有人笑。",
  str_homestory_chat_16522004 = "我覺得還好啊",
  str_homestory_chat_16522005 = "只是有點口音而已。",
  str_homestory_chat_16522006 = "說話，只要聽得懂不就好了，沒什麼可笑的。",
  str_homestory_chat_16522007 = "嗚嗚，謝謝先森的安慰。",
  str_homestory_chat_16523001 = "今天好熱......",
  str_homestory_chat_16523002 = "唔，是的。",
  str_homestory_chat_16523003 = "先森，你滋道哪裡涼快嗎？",
  str_homestory_chat_16523004 = "樹下很涼快",
  str_homestory_chat_16523005 = "那塔塔去樹下蹭涼了。",
  str_homestory_chat_16523006 = "先森有素的話，可以去樹下找偶。",
  str_homestory_chat_16523007 = "妳可以吃點冰淇淋",
  str_homestory_chat_16523008 = "那塔塔需要次很多很多冰淇淋才信。",
  str_homestory_chat_22699999 = "你好，導航員。",
  str_homestory_chat_22601001 = "妳好，貝菲爾小姐",
  str_homestory_chat_22601002 = "在社交禮儀這一塊，你做得還挺到位的。",
  str_homestory_chat_22601003 = "貝菲爾小姐有什麼指教嗎？",
  str_homestory_chat_22601004 = "也沒什麼指教——以及，見到你，我也很高興。",
  str_homestory_chat_22621001 = "有什麼新鮮事嗎？",
  str_homestory_chat_22621002 = "聊天？找我聊天，可是要預約的。",
  str_homestory_chat_22621003 = "聊天也要預約？",
  str_homestory_chat_22621004 = "難道我的表述不夠清晰嗎？",
  str_homestory_chat_22621005 = "啊？怎麼預約？",
  str_homestory_chat_22621006 = "我只說一次，你可要記好了啊——",
  str_homestory_chat_22621007 = "首先，找到我的助理；然後，我的助理會為你安排會面。",
  str_homestory_chat_22621008 = "這......這麼麻煩嗎？",
  str_homestory_chat_22621009 = "不過，我現在也沒什麼事，你有話就快說吧。",
  str_homestory_chat_22622001 = "妳找我做什麼？",
  str_homestory_chat_22622002 = "PlayerName，我打算在這裡建個書友會，你覺得怎麼樣？",
  str_homestory_chat_22622003 = "好啊！",
  str_homestory_chat_22622004 = "不過，妳想建個什麼樣的書友會呢？",
  str_homestory_chat_22622005 = "這是商業機密，我就不透露了。",
  str_homestory_chat_22622006 = "建得起來嗎？",
  str_homestory_chat_22622007 = "當然！我已經做了詳細的規劃了。",
  str_homestory_chat_22622008 = "為了找到讀書同好，我可是非常認真的。",
  str_homestory_chat_22623001 = "住得習慣嗎？",
  str_homestory_chat_22623002 = "我很少有不習慣的時候——",
  str_homestory_chat_22623003 = "在這裡，和在影鎮並沒有太大區別。",
  str_homestory_chat_22623004 = "唯一不一樣的，大概是我清閒了許多。",
  str_homestory_chat_22623005 = "那妳會覺得無聊嗎？",
  str_homestory_chat_22623006 = "當作休假就好了。",
  str_homestory_chat_22999999 = "很高興遇見你。",
  str_homestory_chat_22901001 = "你好，也很高興遇到你",
  str_homestory_chat_22901002 = "是有什麼新委託了嗎？",
  str_homestory_chat_22901003 = "新委託倒是沒有......",
  str_homestory_chat_22901004 = "正好，我可以趁著這個時候休息片刻。",
  str_homestory_chat_22921001 = "能取下面具嗎？",
  str_homestory_chat_22921002 = "......你不適應與戴著面具的人講話？",
  str_homestory_chat_22921003 = "有點......",
  str_homestory_chat_22921004 = "確實有人認為戴面具會增加距離感——",
  str_homestory_chat_22921005 = "你可以試試只看我的眼睛，會感覺好一些。",
  str_homestory_chat_22921006 = "如果還是不適應的話，我會為你取下面具的。",
  str_homestory_chat_22921007 = "不是......",
  str_homestory_chat_22921008 = "那你提出這個要求，只是因為好奇？",
  str_homestory_chat_22921009 = "好奇也沒關係，對我來說，這個要求不算冒犯。",
  str_homestory_chat_22922001 = "你在想什麼？",
  str_homestory_chat_22922002 = "最近有不少人請我在他們的衣服上繪製圖案。",
  str_homestory_chat_22922003 = "什麼圖案？",
  str_homestory_chat_22922004 = "比如，「最喜歡的家園角落」這種......",
  str_homestory_chat_22922005 = "為什麼會有這種請求？",
  str_homestory_chat_22922006 = "現在流行在衣服上繪製家園風景......",
  str_homestory_chat_22922007 = "不知是誰掀起的潮流。",
  str_homestory_chat_22922008 = "如果你也想要一件這樣的衣服，我可以免費幫你繪製。",
  str_homestory_chat_22923001 = "你看起來很高興......",
  str_homestory_chat_22923002 = "發生什麼好事了嗎？",
  str_homestory_chat_22923003 = "好事？",
  str_homestory_chat_22923004 = "喔，我今天去樹林裡觀察了幾個小時的昆蟲。",
  str_homestory_chat_22923005 = "所以心情很好。",
  str_homestory_chat_22923006 = "你對昆蟲感興趣嗎？",
  str_homestory_chat_22923007 = "感興趣！",
  str_homestory_chat_22923008 = "下次觀察昆蟲，你跟我一起去吧。",
  str_homestory_chat_22923009 = "不感興趣......",
  str_homestory_chat_22923010 = "興趣都是培養的，說不定多看幾次，就有興趣了。",
  str_homestory_chat_22923011 = "下次觀察昆蟲，你要不要一起來？",
  str_homestory_chat_15599999 = "現在是工作時間......啊，你好。",
  str_homestory_chat_15501001 = "你好，打攪你了嗎？",
  str_homestory_chat_15501002 = "喔，抱歉，看來我養成了不太好的習慣。",
  str_homestory_chat_15501003 = "很高興見到你，PlayerName。",
  str_homestory_chat_15501004 = "我之前常在你工作的時候打擾到你嗎......",
  str_homestory_chat_15501005 = "不......不，是我的問題，我沉浸在工作裡太久了。",
  str_homestory_chat_15521001 = "你對這裡很感興趣？",
  str_homestory_chat_15521002 = "是的，來到這裡後，我又寫了不少游記。",
  str_homestory_chat_15521003 = "對我而言，這裡許多東西都陌生而新鮮。",
  str_homestory_chat_15521004 = "所以我總忍不住將它們記在紙張上——",
  str_homestory_chat_15521005 = "希望這樣的行為不會對你造成困擾。",
  str_homestory_chat_15521006 = "不會的，你想記什麼都可以。",
  str_homestory_chat_15522001 = "為什麼看著我？",
  str_homestory_chat_15522002 = "你最近有認真鍛鍊嗎？",
  str_homestory_chat_15522003 = "有",
  str_homestory_chat_15522004 = "很好，你已經具備追捕逃犯的資格了。",
  str_homestory_chat_15522005 = "沒有......",
  str_homestory_chat_15522006 = "看來......我只能孤身一人去追捕逃犯了。",
  str_homestory_chat_15522007 = "這裡來了逃犯嗎？！",
  str_homestory_chat_15522008 = "唔，或許用「逃犯」形容牠並不准確......",
  str_homestory_chat_15522009 = "到底是什麼啊？！",
  str_homestory_chat_15522010 = "咳咳，一隻兔子，牠吃了不少花圃裡的花......",
  str_homestory_chat_15523001 = "你找我有事情？",
  str_homestory_chat_15523002 = "PlayerName，你有沒有開辦課堂的打算？",
  str_homestory_chat_15523003 = "為什麼這麼問？",
  str_homestory_chat_15523004 = "這裡的遺跡裡藏有不少古老的知識和智慧......",
  str_homestory_chat_15523005 = "難道你不想把它們傳承下去嗎？",
  str_homestory_chat_15523006 = "你說得有道理，我會考慮的。",
  str_homestory_chat_22099999 = "又遇見你了，PlayerName。",
  str_homestory_chat_22001001 = "妳好，海蒂",
  str_homestory_chat_22001002 = "嗯......對了，我最近讀了一本不錯的書，想推薦給你......",
  str_homestory_chat_22001003 = "但不知道你感不感興趣。",
  str_homestory_chat_22001004 = "既然是妳喜歡的書，應該很有趣吧。",
  str_homestory_chat_22021001 = "妳在散步？",
  str_homestory_chat_22021002 = "是的，我帶龐佩去草地上散了一會步。",
  str_homestory_chat_22021003 = "在這裡，我終於不用擔心他踩壞什麼東西了。",
  str_homestory_chat_22021004 = "如果你也想加入我們，我很歡迎。",
  str_homestory_chat_22021005 = "真的可以嗎？",
  str_homestory_chat_22021006 = "和龐佩一起散步，一定很酷吧！",
  str_homestory_chat_22021007 = "我很樂意，只是......",
  str_homestory_chat_22021008 = "我最近有些忙。",
  str_homestory_chat_22021009 = "不必擔心，我的邀約永遠有效。",
  str_homestory_chat_22022001 = "最近有個聚會......",
  str_homestory_chat_22022002 = "妳想參加嗎？",
  str_homestory_chat_22022003 = "感謝你的邀請，但是，我對人群有些過敏。",
  str_homestory_chat_22022004 = "這樣啊......",
  str_homestory_chat_22022005 = "不過，我可以去你們聚會附近的高地——",
  str_homestory_chat_22022006 = "觀看，也算一種參與吧。",
  str_homestory_chat_22022007 = "啊？",
  str_homestory_chat_22023001 = "妳找我有什麼事？",
  str_homestory_chat_22023002 = "可以拜託你幫忙找幾本書嗎？",
  str_homestory_chat_22023003 = "可以啊",
  str_homestory_chat_22023004 = "不過，幾天前，妳剛買了那麼高一摞書......",
  str_homestory_chat_22023005 = "現在都讀完了？",
  str_homestory_chat_22023006 = "是的。有時候，看書太快，也會成為一種煩惱。",
  str_homestory_chat_22399999 = "您好啊！",
  str_homestory_chat_22301001 = "妳好！柯蒂！",
  str_homestory_chat_22301002 = "今天我也在認真維護這裡的治安呢！",
  str_homestory_chat_22301003 = "啊，辛苦妳了。",
  str_homestory_chat_22301004 = "只要能為大家創造一個安全的環境，我做什麼都不辛苦！",
  str_homestory_chat_22321001 = "妳這就要走了嗎？",
  str_homestory_chat_22321002 = "唔，我想起來，今天還沒有收拾屋子......",
  str_homestory_chat_22321003 = "我們還沒說上兩句話呢",
  str_homestory_chat_22321004 = "雖然我很想和您多聊一會......",
  str_homestory_chat_22321005 = "但是，一想到屋子還沒有收拾，我就忍不住走神......",
  str_homestory_chat_22321006 = "嗚哇，我無法忍受了，我必須馬上回去一趟，非常抱歉！",
  str_homestory_chat_22322001 = "妳今天的心情看起來不錯",
  str_homestory_chat_22322002 = "是啊。因為我今天拿到了新分發的制服！",
  str_homestory_chat_22322003 = "妳很喜歡穿新衣服？",
  str_homestory_chat_22322004 = "不是什麼新衣服都喜歡啦......",
  str_homestory_chat_22322005 = "這次的新制服還沒有經過漿洗，摸起來異常柔軟。",
  str_homestory_chat_22322006 = "一想到可以穿這麼柔軟的衣服，我就忍不住偷笑......",
  str_homestory_chat_22322007 = "哎，您不要笑話我啦。",
  str_homestory_chat_22323001 = "咦，妳看起來好像哭過......",
  str_homestory_chat_22323002 = "發生什麼事了嗎？",
  str_homestory_chat_22323003 = "沒......沒有......",
  str_homestory_chat_22323004 = "說給我聽沒有關係啦",
  str_homestory_chat_22323005 = "我......我不是因為傷心才......才哭的......",
  str_homestory_chat_22323006 = "當......當治安官，總會遇到一些突發事件......真的很嚇人......",
  str_homestory_chat_22323007 = "喔，這樣啊。",
  str_homestory_chat_22323008 = "下次遇到突發事件，可以找我幫忙喔。",
  str_homestory_chat_22323009 = "真的沒事嗎？",
  str_homestory_chat_22323010 = "沒，沒事......您去忙吧。",
  str_homestory_chat_22323011 = "那......我走了？有事的話一定要和我說啊。",
  str_homestory_chat_11599999 = "PlayerName，天氣真好啊。",
  str_homestory_chat_11501001 = "你好啊",
  str_homestory_chat_11501002 = "你要不要買一幅畫呢？",
  str_homestory_chat_11501003 = "天氣好和買畫之間有什麼聯繫嗎？",
  str_homestory_chat_11501004 = "只要PlayerName認為有關係，不就行了。",
  str_homestory_chat_11501005 = "不過，你說話的方式愈來愈像那傢伙了......",
  str_homestory_chat_11521001 = "你在想什麼呢？",
  str_homestory_chat_11521002 = "我們什麼時候才買得起空艇啊......",
