  str_homestory_chat_11521008 = "說得有道理。",
  str_homestory_chat_11521009 = "不過，你會做嗎？",
  str_homestory_chat_11521010 = "我......我又不是紅油扳手裡的那些怪才......",
  str_homestory_chat_11522001 = "今天有點熱呢",
  str_homestory_chat_11522002 = "今天？好像有點冷......",
  str_homestory_chat_11522003 = "奇怪",
  str_homestory_chat_11522004 = "我們的感覺不一樣呢。",
  str_homestory_chat_11522005 = "畢竟我們差別有點大......",
  str_homestory_chat_11522006 = "也是，那我回去把大衣加上！",
  str_homestory_chat_11523001 = "聽說有人要舉辦沙龍？",
  str_homestory_chat_11523002 = "不是普通聚會嗎？",
  str_homestory_chat_11523003 = "難道是誰傳錯話了......",
