  str_homestory_chat_11523006 = "看來......是普通聚會了。",
  str_homestory_chat_23199999 = "真巧啊，PlayerName。",
  str_homestory_chat_23101001 = "你好，諾維亞",
  str_homestory_chat_23101002 = "閣下也在這裡散步？",
  str_homestory_chat_23101003 = "是啊。",
  str_homestory_chat_23101004 = "要一起走走嗎？",
  str_homestory_chat_23121001 = "在這裡感覺如何？",
  str_homestory_chat_23121002 = "以往，我每次走出北境，都會感到非常不適。",
