  str_homestory_chat_23123009 = "現在給誰好呢？",
  str_homestory_chat_23123010 = "哎，還是收起來吧。",
  str_homestory_chat_23124001 = "你似乎在聽什麼？",
  str_homestory_chat_23124002 = "是的，我在聽這些自然的聲音，有時候它比樂曲還好聽。",
