  str_homestory_chat_23124008 = "啊，只是隨便問問而已。",
  str_homestory_chat_23125001 = "在散步呢？",
  str_homestory_chat_23125002 = "沒錯，前些日子想到一些事情，鬱悶糾結不開，於是便出來散心。",
  str_homestory_chat_23125003 = "當閣下遇到這種情況的時候，會去做什麼？",
