  str_homestory_chat_23125005 = "在附近隨便走走，什麼也不想。",
  str_homestory_chat_23125006 = "讀書。",
  str_homestory_chat_23125007 = "尤其是那些不用動腦子的書，比如影鎮連載的三流俠盜故事……",
  str_homestory_chat_23125008 = "看來閣下您為了保證頭腦清醒，也確實下了不少功夫。",
  str_homestory_chat_23125009 = "看來守護此地責任帶來的壓力，確實很大啊。",
  str_homestory_chat_23125010 = "那個，還好吧。",
  str_homestory_chat_23299999 = "嘻嘻，又見到你啦！",
  str_homestory_chat_23201001 = "是呀！",
  str_homestory_chat_23201002 = "想來一塊蜂蜜小蛋糕嗎？",
  str_homestory_chat_23201003 = "愛洛拉的祕製蛋糕，吃完不會長胖喔！",
