  str_homestory_chat_24224005 = "話說，這裡的伙食很好呢！",
  str_homestory_chat_24224006 = "吃完早餐，就開始期待午餐了。",
  str_homestory_chat_24224007 = "還有好久呢",
  str_homestory_chat_24224008 = "啊......怎麼會這樣......",
  str_homestory_chat_24224009 = "難道上一餐不是一百年前的事了嗎？",
  str_homestory_chat_24224010 = "喂，妳開始說胡話了啊！",
  str_homestory_chat_24399999 = "哎呀，是導航員大人呢。",
  str_homestory_chat_24301001 = "妳好，凜音",
  str_homestory_chat_24301002 = "今天需要巫女為您祛除污穢嗎？",
  str_homestory_chat_24301003 = "不......不用了......",
  str_homestory_chat_24321001 = "妳對這裡怎麼看呢？",
  str_homestory_chat_24321002 = "這片土地異常潔淨呢。",
  str_homestory_chat_24321003 = "看來，並不是很需要巫女......",
  str_homestory_chat_24321004 = "才沒有這回事！",
  str_homestory_chat_24321005 = "我......我是說，凜音可以作為客人留下來。",
  str_homestory_chat_24321006 = "不需要管巫女的身分。",
  str_homestory_chat_24321007 = "好啊，那我就作為凜音留在這裡吧。",
  str_homestory_chat_24322001 = "找我有事？",
  str_homestory_chat_24322002 = "導航員大人，不如我們定一個「清掃日」吧。",
  str_homestory_chat_24322003 = "好啊！",
  str_homestory_chat_24322004 = "哎呀，你答應得這麼快......",
  str_homestory_chat_24322005 = "我想好的勸說詞都沒機會說了呢。",
  str_homestory_chat_24322006 = "啊？為什麼？",
  str_homestory_chat_24322007 = "定時清除污穢，會幫居民們趕走厄運，保持健康與好心情——",
  str_homestory_chat_24322008 = "這個理由，您覺得怎麼樣？",
  str_homestory_chat_24323001 = "有什麼新鮮事？",
  str_homestory_chat_24323002 = "導航員大人，最近我找到一個修行的好地方呢。",
  str_homestory_chat_24323003 = "什麼地方？",
  str_homestory_chat_24323004 = "很難講出具體的地點，但是我可以替您描繪一番——",
  str_homestory_chat_24323005 = "那塊地方距離河流不遠......",
  str_homestory_chat_24323006 = "如果想要找到具體位置的話，需要仔細聆聽。",
  str_homestory_chat_24323007 = "在傍晚時分，那裡總會準時響起悠揚的音樂。",
  str_homestory_chat_24323008 = "我想，妳可能發現某個愛好音樂的光靈的祕密基地了。",
  str_homestory_chat_24499999 = "啊......",
  str_homestory_chat_24401001 = "妳好，柏乃",
  str_homestory_chat_24401002 = "您......您在和我打招呼嗎？啊，真高興啊......",
  str_homestory_chat_24401003 = "妳看起來精神很好呢。",
  str_homestory_chat_24401004 = "那......那是因為，今天「那些東西」很安靜。",
  str_homestory_chat_24421001 = "我不常遇見妳......",
  str_homestory_chat_24421002 = "即便是妳來到這裡之後也是這樣。",
  str_homestory_chat_24421003 = "是，是嗎......大概是因為，我總是忍不住躲起來......",
  str_homestory_chat_24421004 = "為什麼？",
  str_homestory_chat_24421005 = "這裡有太多......太多光靈了......",
  str_homestory_chat_24421006 = "並......並且，「那些東西」很危險......",
  str_homestory_chat_24421007 = "這樣啊......",
  str_homestory_chat_24422001 = "覺得這裡如何？",
  str_homestory_chat_24422002 = "很幸運能留在這裡呢......",
  str_homestory_chat_24422003 = "不用打工就可以吃飽飯，一個人待著也不會被打擾......",
  str_homestory_chat_24422004 = "唔......您，您什麼也沒有聽見，那些話不，不是我說的......",
  str_homestory_chat_24422005 = "不用緊張",
  str_homestory_chat_24422006 = "妳願意留在這裡，我很高興呢。",
  str_homestory_chat_24422007 = "是......是嗎？",
  str_homestory_chat_24423001 = "妳的個子很高呢",
  str_homestory_chat_24423002 = "唉......可是......算了。",
  str_homestory_chat_24423003 = "您會因為身高苦惱嗎？",
  str_homestory_chat_24423004 = "有一點......",
  str_homestory_chat_24423005 = "可我覺得您的身高剛剛好呢。",
  str_homestory_chat_24423006 = "完全沒有",
  str_homestory_chat_24423007 = "這樣很好呢。",
  str_homestory_chat_24423008 = "妳這麼問，是因為妳不滿意自己的身高嗎？",
  str_homestory_chat_24423009 = "唔，沒有啊，雖然身高給我帶來了一些麻煩......",
  str_homestory_chat_24423010 = "但是，我已經習慣總是看到別人的頭頂了。",
  str_homestory_chat_24423011 = "如果需要仰視對方，反而會有些不適應呢。",
  str_homestory_chat_24599999 = "大人，你好。",
  str_homestory_chat_24521001 = "不用這麼嚴肅啦",
  str_homestory_chat_24521002 = "這是我表達尊敬的方式，如果你不喜歡的話......",
  str_homestory_chat_24521003 = "還請你忍耐一下。",
  str_homestory_chat_24522001 = "妳在看什麼？",
  str_homestory_chat_24522002 = "清晨，在這裡醒來，會有一瞬間恍惚......",
  str_homestory_chat_24522003 = "彷彿自己回到了幼年的時候。",
  str_homestory_chat_24522004 = "這裡和妳的故鄉很像？",
  str_homestory_chat_24522005 = "不，甚至可以說很不一樣。",
  str_homestory_chat_24522006 = "之所以會有那種感覺，大概是因為這裡讓我感受到了久違的寧靜。",
  str_homestory_chat_24523001 = "妳怎麼了？",
  str_homestory_chat_24523002 = "大人，你有沒有聞到空氣中有一股難聞的味道？",
  str_homestory_chat_24523003 = "好像有......",
  str_homestory_chat_24523004 = "果然，你和在下一樣，無法忍受韭菜的氣味。",
  str_homestory_chat_24523005 = "明明這麼難聞，韭菜卻常被冠以「香」字，真是不可理喻。",
  str_homestory_chat_24523006 = "原......原來是韭菜味嗎？",
  str_homestory_chat_24523007 = "沒什麼味道啊......",
  str_homestory_chat_24523008 = "看來你的鼻子不是很靈敏。",
  str_homestory_chat_24523009 = "也好，這樣就不用受這股味道的折磨了。",
  str_homestory_chat_24524001 = "咦，妳的衣服......",
  str_homestory_chat_24524002 = "一個小時前，妳好像穿的不是這套。",
  str_homestory_chat_24524003 = "快速換裝是忍者的必備技能。",
  str_homestory_chat_24524004 = "換裝可以讓我們靈活地甩掉追蹤者。",
  str_homestory_chat_24524005 = "喔，這樣啊......",
  str_homestory_chat_24524006 = "但是，這裡也有追蹤者嗎？",
  str_homestory_chat_24524007 = "......",
  str_homestory_chat_24524008 = "咳咳，對忍者來說，因為心情好所以換一身打扮，也是可以的。",
  str_homestory_chat_24699999 = "嗨！今天也看到你了！",
  str_homestory_chat_24601001 = "妳好啊，瑤",
  str_homestory_chat_24601002 = "有什麼不平之事，需要我用拳頭平一平的嗎？",
  str_homestory_chat_24601003 = "好像沒有......",
  str_homestory_chat_24601004 = "真好，又是太平的一天。",
  str_homestory_chat_24621001 = "找我有事？",
  str_homestory_chat_24621002 = "PlayerName，我能拜託你一件事嗎？",
  str_homestory_chat_24621003 = "事成之後有十萬白夜幣相贈！",
  str_homestory_chat_24621004 = "真......真的嗎？",
  str_homestory_chat_24621005 = "赴湯蹈火，在所不辭！",
  str_homestory_chat_24621006 = "用不著赴湯蹈火，你只需要——",
  str_homestory_chat_24621007 = "幫忙採購兩箱辣椒粉，就好了。",
  str_homestory_chat_24621008 = "哎，話說這裡的飲食真清淡啊......",
  str_homestory_chat_24621009 = "原來，在瑤的世界裡，採購辣椒粉，就值十萬白夜幣嗎......",
  str_homestory_chat_24622001 = "妳看我做什麼？",
  str_homestory_chat_24622002 = "PlayerName，你的衣服穿著舒服嗎？",
  str_homestory_chat_24622003 = "我覺得挺舒服的",
  str_homestory_chat_24622004 = "哇，真的嗎？可以告訴我，你的衣服是在哪裡買的嗎？",
  str_homestory_chat_24622005 = "我也去添置幾件！",
  str_homestory_chat_24622006 = "感覺不太舒服......",
  str_homestory_chat_24622007 = "不太舒服怎麼不換一套啊？",
  str_homestory_chat_24622008 = "有一家店我常去，他們家的衣服可舒服了。",
  str_homestory_chat_24622009 = "下次，我買衣服的時候，帶你一起去吧。",
  str_homestory_chat_24623001 = "妳的功夫......",
  str_homestory_chat_24623002 = "啊！我又進步了不少呢！",
  str_homestory_chat_24623003 = "想試試我嗎？",
  str_homestory_chat_24623004 = "可......可是我不會功夫",
  str_homestory_chat_24623005 = "放心啦，我不會對著你比劃的。",
  str_homestory_chat_24623006 = "你站在一邊，看我用手掌劈開石頭——",
  str_homestory_chat_24623007 = "還......還是不了吧......",
  str_homestory_chat_24624001 = "上次的辣椒粉......",
  str_homestory_chat_24624002 = "味道不錯！",
  str_homestory_chat_24624003 = "為了表示感謝，我決定親自下廚，為你做麻婆豆腐！",
  str_homestory_chat_24624004 = "好啊！",
  str_homestory_chat_24624005 = "哈哈，看來你也覺得麻婆豆腐很好吃啊！",
  str_homestory_chat_24624006 = "我做了，你可要多吃點！",
  str_homestory_chat_24624007 = "不麻煩了......",
  str_homestory_chat_24624008 = "不用害怕，吃了不會怎麼樣的，頂多七竅噴火。",
  str_homestory_chat_24799999 = "您好啊！",
  str_homestory_chat_24701001 = "妳好！",
  str_homestory_chat_24701002 = "您吃了嗎？",
  str_homestory_chat_24701003 = "吃了吃了，還飽著呢。",
  str_homestory_chat_24721001 = "聽說妳要開分店？",
  str_homestory_chat_24721002 = "是，所以我來問問你！",
  str_homestory_chat_24721003 = "我支持開店！",
  str_homestory_chat_24721004 = "感謝您對蟹家拉麵的支持！",
  str_homestory_chat_24721005 = "那就為開店做準備吧！",
  str_homestory_chat_24721006 = "我需要考慮一下......",
  str_homestory_chat_24721007 = "如果您同意的話......",
  str_homestory_chat_24721008 = "以後吃拉麵免單喔！",
  str_homestory_chat_24722001 = "什麼味道？",
  str_homestory_chat_24722002 = "是熟悉的香味——",
  str_homestory_chat_24722003 = "一定是上次的香草！",
  str_homestory_chat_24722004 = "「上次」？",
  str_homestory_chat_24722005 = "這裡長著一種奇異的香草......",
  str_homestory_chat_24722006 = "放在拉麵裡非常好吃！",
  str_homestory_chat_24722007 = "上次就摘了許多。",
  str_homestory_chat_24722008 = "原來......那片草地是這樣禿掉的......",
  str_homestory_chat_24723001 = "找我有事？",
  str_homestory_chat_24723002 = "貴客最近辦聚會嗎？",
  str_homestory_chat_24723003 = "營收下降了......",
  str_homestory_chat_24723004 = "沒有這個打算......",
  str_homestory_chat_24723005 = "難道蟹家拉麵......",
  str_homestory_chat_24723006 = "要倒閉了嗎？",
  str_homestory_chat_24723007 = "不會的，我可以找人打廣告。",
  str_homestory_chat_24723008 = "一言為定——",
  str_homestory_chat_24723009 = "不許反悔喔！",
  str_homestory_chat_24723010 = "辦啊！",
  str_homestory_chat_24723011 = "太好了——",
  str_homestory_chat_24723012 = "蟹家拉麵有救了！",
  str_homestory_chat_24723013 = "辦一次聚會——",
  str_homestory_chat_24723014 = "賣掉一百碗！",
  str_homestory_chat_26399999 = "唔喔喔，是風船大大！",
  str_homestory_chat_26301001 = "不......不是",
  str_homestory_chat_26301002 = "別再這麼叫我了，好怪！",
  str_homestory_chat_26301003 = "那就......巨像大大？",
  str_homestory_chat_26301004 = "......你隨意吧......",
  str_homestory_chat_26321001 = "住得還習慣嗎？",
  str_homestory_chat_26321002 = "還好吧，多謝大大的招待。",
  str_homestory_chat_26321003 = "對了，大大玩《白XX光》嗎？",
  str_homestory_chat_26321004 = "不玩",
  str_homestory_chat_26321005 = "唔喔喔，你真的要拒絕這麼宏大、細膩、熱血......",
  str_homestory_chat_26321006 = "不玩就是不玩，你怎麼推薦都沒用的！",
  str_homestory_chat_26321007 = "玩！",
  str_homestory_chat_26321008 = "唔喔喔，太好了！",
  str_homestory_chat_26321009 = "我這就去替你找遊戲機！",
  str_homestory_chat_26322001 = "你在找我？",
  str_homestory_chat_26322002 = "最近，這裡有沒有新來厲害的繪師？",
  str_homestory_chat_26322003 = "有啊",
  str_homestory_chat_26322004 = "真的嗎？可以介紹給我嗎？",
  str_homestory_chat_26322005 = "事成之後，我會把你做成角色，加進《白XX光》中的！",
  str_homestory_chat_26322006 = "沒有......",
  str_homestory_chat_26322007 = "可惡......",
  str_homestory_chat_26322008 = "看來我要開始新一輪的大陸環遊了。",
  str_homestory_chat_26323001 = "你看起來很高興",
  str_homestory_chat_26323002 = "前幾天，我看到了一幅堪稱完美的畫作！",
  str_homestory_chat_26323003 = "線條優美靈動！用色大膽卻和諧！",
  str_homestory_chat_26323004 = "畫作內容——彷彿囊括了宇宙的奧祕！",
  str_homestory_chat_26323005 = "為了它，我已經傾家蕩產，甚至不惜獻上了生活費！",
  str_homestory_chat_26323006 = "你想說什麼......",
  str_homestory_chat_26323007 = "大大，我沒錢了......我能去你家蹭飯嗎？",
  str_homestory_chat_24899999 = "唷，是小空裔啊？",
  str_homestory_chat_24801001 = "妳好，青瞳",
  str_homestory_chat_24801002 = "來找姐姐玩嗎？",
  str_homestory_chat_24801003 = "只......只是打個招呼......",
  str_homestory_chat_24801004 = "只打個招呼？真的不做點別的什麼嗎？",
  str_homestory_chat_24821001 = "妳準備去做什麼？",
  str_homestory_chat_24821002 = "洗車。你想一起來嗎？",
  str_homestory_chat_24821003 = "去哪裡洗車？",
  str_homestory_chat_24821004 = "我記得，附近沒有洗車的地方......",
  str_homestory_chat_24821005 = "洗車這種事，只要有足夠多乾淨的水就行了。",
  str_homestory_chat_24821006 = "所以，你猜猜，我會去哪裡洗車？",
  str_homestory_chat_24821007 = "怎麼洗車？",
  str_homestory_chat_24821008 = "哈哈，你怎麼問出了這麼傻的問題？",
  str_homestory_chat_24821009 = "自然是用水洗囉。",
  str_homestory_chat_24821010 = "別愣著了，要姐姐帶你去見識見識「怎麼洗車」嗎？",
  str_homestory_chat_24822001 = "妳要問我什麼？",
  str_homestory_chat_24822002 = "這裡沒有靶場嗎？",
  str_homestory_chat_24822003 = "沒有......",
  str_homestory_chat_24822004 = "哎，還真是無聊啊......",
  str_homestory_chat_24822005 = "這樣的話，我只能把花盆當作瞄準對象了。",
  str_homestory_chat_24822006 = "不要隨意破壞啊......",
  str_homestory_chat_24822007 = "我只說「瞄準」，沒說會「射擊」喔。",
  str_homestory_chat_24822008 = "有！",
  str_homestory_chat_24822009 = "在我面前撒謊，可是要付出代價的喔。",
  str_homestory_chat_24822010 = "如果，我找不到你所說的靶場，猜猜我會給你什麼懲罰？",
  str_homestory_chat_24823001 = "妳在找人？",
  str_homestory_chat_24823002 = "影鎮的那些傢伙，都躲到哪裡去了？",
  str_homestory_chat_24823003 = "我也沒看見......",
  str_homestory_chat_24823004 = "哎......不知道你能不能喝酒。",
  str_homestory_chat_24823005 = "找不到那些傢伙，叫上你陪我喝一杯，好像也不錯。",
  str_homestory_chat_24823006 = "他們好像在那邊",
  str_homestory_chat_24823007 = "......他們啊......暫時還沒資格成為我的酒友。",
  str_homestory_chat_24823008 = "我想想，去找誰呢......",
  str_homestory_chat_24824001 = "住得還好嗎？",
  str_homestory_chat_24824002 = "有點無聊......",
  str_homestory_chat_24824003 = "唯一的樂趣，大概就是觀賞可愛的男孩子了。",
  str_homestory_chat_24824004 = "PlayerName，在這裡，你覺得誰最可愛啊？",
  str_homestory_chat_24824005 = "無法比較......",
  str_homestory_chat_24824006 = "在我眼裡，大家都很可愛！",
  str_homestory_chat_24824007 = "我也很「可愛」嗎？",
  str_homestory_chat_24824008 = "這......這......",
  str_homestory_chat_24824009 = "我",
  str_homestory_chat_24824010 = "......哪，哪有自己說自己可愛的？",
  str_homestory_chat_24999999 = "怎麼想起來問候大叔我了？",
  str_homestory_chat_24901001 = "遇到而已",
  str_homestory_chat_24901002 = "所以就順便問候問候......",
  str_homestory_chat_24901003 = "你啊，未免也太誠實了。",
  str_homestory_chat_24901004 = "還是說，面對大叔我，實在講不出哄人的話？",
  str_homestory_chat_24921001 = "你很喜歡玩偶？",
  str_homestory_chat_24921002 = "是的！年輕人，你喜歡嗎？",
  str_homestory_chat_24921003 = "喜歡！",
  str_homestory_chat_24921004 = "上次賽跑，剩了幾隻獎品玩偶，你介意收留它們嗎？",
  str_homestory_chat_24921005 = "完全不介意！",
  str_homestory_chat_24921006 = "好，我等下給你帶過來。",
  str_homestory_chat_24921007 = "不喜歡......",
  str_homestory_chat_24921008 = "這樣啊......我看家裡的年輕人都還滿喜歡的......",
  str_homestory_chat_24921009 = "以為你也會喜歡。",
  str_homestory_chat_24921010 = "既然這樣的話，我那些兔子玩偶只好繼續堆在房子裡了。",
  str_homestory_chat_24922001 = "你似乎有點無聊呢",
  str_homestory_chat_24922002 = "是的......前幾天，家裡的年輕人都去爬山了......",
  str_homestory_chat_24922003 = "留下大叔我一個人，還真有些寂寞呢。",
  str_homestory_chat_24922004 = "你為什麼沒去？",
  str_homestory_chat_24922005 = "你瞧瞧我這腿——",
  str_homestory_chat_24922006 = "路走多了，還會嘎吱嘎吱響。",
  str_homestory_chat_24922007 = "爬山這種活動，已經不再適合我了。",
  str_homestory_chat_24923001 = "這裡感覺如何？",
  str_homestory_chat_24923002 = "......真是好地方啊。",
  str_homestory_chat_24923003 = "那個傢伙如果還活著的話，應該也很喜歡這裡......",
  str_homestory_chat_24923004 = "......我剛才在自言自語，你應該沒聽到吧......",
  str_homestory_chat_24923005 = "聽到了......",
  str_homestory_chat_24923006 = "......還好我沒說這裡的壞話。",
  str_homestory_chat_24923007 = "下次靠近我之前，記得先招呼啊！",
  str_homestory_chat_24923008 = "沒聽到",
  str_homestory_chat_24923009 = "哎，你完全不會撒謊嘛......",
  str_homestory_chat_24923010 = "算了，聽到了也沒關係。",
  str_homestory_chat_25299999 = "......",
  str_homestory_chat_25201001 = "妳好，梅",
  str_homestory_chat_25201002 = "你......你在向我打招呼？",
  str_homestory_chat_25201003 = "怎......怎麼辦，我該怎麼回應啊？",
  str_homestory_chat_25201004 = "......我不是故意不回答你的......你不會討厭我吧？",
  str_homestory_chat_25201005 = "只是打個招呼，不是什麼嚴重的事情啦。",
  str_homestory_chat_25221001 = "妳在做什麼？",
  str_homestory_chat_25221002 = "寶寶乖乖，媽媽在這裡......",
  str_homestory_chat_25221003 = "當然是照顧寶寶啦。",
  str_homestory_chat_25221004 = "寶寶的毛髮太容易打結了，真煩躁啊......",
  str_homestory_chat_25221005 = "不行，作為媽媽，要有耐心！",
  str_homestory_chat_25221006 = "（我是不是應該默默走開......）",
  str_homestory_chat_25222001 = "在想什麼？",
  str_homestory_chat_25222002 = "你是不是很喜歡花？",
  str_homestory_chat_25222003 = "是啊",
  str_homestory_chat_25222004 = "那我去摘些花，縫在你衣服上好不好？",
  str_homestory_chat_25222005 = "我......把你喜歡的東西送給你......",
  str_homestory_chat_25222006 = "你會不會更喜歡我一點呢？",
  str_homestory_chat_25222007 = "不啊",
  str_homestory_chat_25222008 = "你不喜歡花嗎？那......你喜歡什麼？",
  str_homestory_chat_25222009 = "為什麼突然問這個？",
  str_homestory_chat_25222010 = "我，我只是......你不願意說，就算了。",
  str_homestory_chat_25223001 = "妳剛剛在啃手指嗎？",
  str_homestory_chat_25223002 = "唔......",
  str_homestory_chat_25223003 = "不要啃手指啊！",
  str_homestory_chat_25223004 = "很不衛生！",
  str_homestory_chat_25223005 = "啊......PlayerName，你不會開始討厭我了吧？",
  str_homestory_chat_25223006 = "沒......沒有......",
  str_homestory_chat_25223007 = "妳沒意識到嗎？",
  str_homestory_chat_25223008 = "我先看一看......手指上有沒有牙齒印......",
  str_homestory_chat_25099999 = "PlayerName，終於有任務給蓮了嗎？",
  str_homestory_chat_25001001 = "沒有沒有",
  str_homestory_chat_25001002 = "只是打個招呼。",
  str_homestory_chat_25001003 = "那......蓮該做什麼呢？",
  str_homestory_chat_25001004 = "先這樣待著吧......",
  str_homestory_chat_25021001 = "什麼聲音？",
  str_homestory_chat_25021002 = "我的肚子又向我說話了。",
  str_homestory_chat_25021003 = "啊？",
  str_homestory_chat_25021004 = "你聽——咕咕的聲音。",
  str_homestory_chat_25021005 = "妳餓了啊？",
  str_homestory_chat_25021006 = "要不要去找點東西吃？",
  str_homestory_chat_25021007 = "這是PlayerName的命令嗎？",
  str_homestory_chat_25021008 = "如果這樣能讓你不捱餓的話......可以理解成「命令」。",
  str_homestory_chat_25022001 = "妳在念叨什麼？",
  str_homestory_chat_25022002 = "要記得......今天需要擰發條......",
  str_homestory_chat_25022003 = "擰發條？",
  str_homestory_chat_25022004 = "啊......我忘了，我已經不需要再擰發條了。",
  str_homestory_chat_25022005 = "有些習慣，變成光靈後，還沒能改掉......",
  str_homestory_chat_25022006 = "沒關係，妳有很多時間，可以慢慢適應。",
  str_homestory_chat_25023001 = "妳在看我？",
  str_homestory_chat_25023002 = "PlayerName，你看到別人開心，也會變得開心嗎？",
  str_homestory_chat_25023003 = "會",
  str_homestory_chat_25023004 = "快樂就是會傳染啊！",
  str_homestory_chat_25023005 = "蓮猜對了。",
  str_homestory_chat_25023006 = "蓮看到了你們，蓮感受到的是開心。",
  str_homestory_chat_25023007 = "今天又學到了新的東西。",
  str_homestory_chat_25023008 = "不會",
  str_homestory_chat_25023009 = "蓮今天看到你們在笑......蓮也想笑——",
  str_homestory_chat_25023010 = "這到底是什麼情緒呢？",
  str_homestory_chat_25024001 = "妳好像走了很久？",
  str_homestory_chat_25024002 = "蓮今天走了很長的路。",
  str_homestory_chat_25024003 = "以前，蓮走路的時候，只是在走路......",
  str_homestory_chat_25024004 = "現在，蓮能感受到風、花香和鞋底的石子......",
  str_homestory_chat_25024005 = "妳的感受好細膩啊......",
  str_homestory_chat_25024006 = "PlayerName也可以和蓮一起來走路。",
  str_homestory_chat_25199999 = "嗯？PlayerName......",
  str_homestory_chat_25101001 = "你好啊，賈爾斯",
  str_homestory_chat_25101002 = "你來找我，一定是知道我新編了童謠吧！",
  str_homestory_chat_25101003 = "想听聽嗎？",
  str_homestory_chat_25101004 = "這......這......",
  str_homestory_chat_25121001 = "你有沒有聞到一股香味？",
  str_homestory_chat_25121002 = "香味嗎？當然有啊——",
  str_homestory_chat_25121003 = "不過，產生香味的東西，已經被我吃下去了。",
  str_homestory_chat_25121004 = "你......你把什麼吃了？",
  str_homestory_chat_25121005 = "哈哈，你的表情是叫「驚恐」嗎？",
  str_homestory_chat_25121006 = "我吃的當然是——",
  str_homestory_chat_25121007 = "肉啦！",
  str_homestory_chat_25122001 = "你怎麼了？",
  str_homestory_chat_25122002 = "......剛才好像......又做夢了。",
  str_homestory_chat_25122003 = "我有說夢話嗎？",
  str_homestory_chat_25122004 = "沒聽到......",
  str_homestory_chat_25122005 = "還好你沒聽到，不然你也要做噩夢了。",
  str_homestory_chat_25122006 = "好像有......",
  str_homestory_chat_25122007 = "你應該沒有聽清楚......",
  str_homestory_chat_25122008 = "如果聽清了的話......你應該不是這副表情。",
  str_homestory_chat_25123001 = "你好像在說什麼？",
  str_homestory_chat_25123002 = "好久沒有編新童謠了......",
  str_homestory_chat_25123003 = "PlayerName，你想听關於什麼的童謠？",
  str_homestory_chat_25123004 = "光靈？",
  str_homestory_chat_25123005 = "「愚笨又聰明，吵鬧難安靜......」",
  str_homestory_chat_25123006 = "「導航員猜猜，什麼是光靈？」",
  str_homestory_chat_25123007 = "暗鬼？",
  str_homestory_chat_25123008 = "好啊！",
  str_homestory_chat_25123009 = "只要PlayerName不怕做噩夢～",
  str_homestory_chat_25123010 = "家園？",
  str_homestory_chat_25123011 = "說到家園，哈～欠，我又想睡覺了......",
  str_homestory_chat_25123012 = "也許，我睡醒後，能給你一首關於家園的童謠。",
  str_homestory_chat_25399999 = "嗯，你好！",
  str_homestory_chat_25301001 = "哇！",
  str_homestory_chat_25301002 = "忍不住就站直了......",
  str_homestory_chat_25321001 = "您在看什麼？",
  str_homestory_chat_25321002 = "餓嗎？",
  str_homestory_chat_25321003 = "有點......",
  str_homestory_chat_25321004 = "今天吃燴飯，怎麼樣？",
  str_homestory_chat_25321005 = "把大家都叫來，嚐嚐我的手藝！",
  str_homestory_chat_25321006 = "不餓",
  str_homestory_chat_25321007 = "不餓也沒關係。",
  str_homestory_chat_25321008 = "我打算，為這裡所有人做一次燴飯。",
  str_homestory_chat_25321009 = "您親自煮飯？",
  str_homestory_chat_25321010 = "哈哈，很意外？",
  str_homestory_chat_25321011 = "我做什麼，你都不應該感到意外才是。",
  str_homestory_chat_25322001 = "感覺這裡如何？",
  str_homestory_chat_25322002 = "真是清閒。",
  str_homestory_chat_25322003 = "待久了，連戰爭是什麼樣，都會想不起來了吧。",
  str_homestory_chat_25322004 = "您覺得這樣不好嗎？",
  str_homestory_chat_25322005 = "胡說。我什麼時候說這樣不好了？",
  str_homestory_chat_25322006 = "讓啟光......或者說，讓整片大陸——",
  str_homestory_chat_25322007 = "都變成這樣，就是我畢生的夢想。",
  str_homestory_chat_25323001 = "嗨......今天如何？",
  str_homestory_chat_25323002 = "......你看起來有些疲憊。",
  str_homestory_chat_25323003 = "是嗎？",
  str_homestory_chat_25323004 = "難道是因為......昨天晚上熬夜打遊戲了？",
  str_homestory_chat_25323005 = "去跑兩圈，吹吹風，就會更有精神了。",
  str_homestory_chat_25323006 = "您這話有些奇怪",
  str_homestory_chat_25323007 = "哈哈，難道是因為——我平時都直接說「打起精神來」嗎？",
  str_homestory_chat_25323008 = "可能是這樣......",
  str_homestory_chat_25323009 = "在這裡，你是主人，我是客人。",
  str_homestory_chat_25323010 = "主客之道，我還是懂的。",
  str_homestory_chat_25324001 = "您最近找我？",
  str_homestory_chat_25324002 = "我和薇絲那孩子聊天時，聽說你最近鍛鍊得很勤。",
  str_homestory_chat_25324003 = "啊......這您都知道？",
  str_homestory_chat_25324004 = "我無意干涉你的活動——",
  str_homestory_chat_25324005 = "只是由衷覺得，有一個可靠的隊友，是件好事。",
  str_homestory_chat_25324006 = "鍛鍊時，如果遇到了麻煩，可以來找我。",
  str_homestory_chat_25324007 = "我隨時幫你解決。",
  str_homestory_chat_25499999 = "嗨，PlayerName，今天天氣不錯。",
  str_homestory_chat_25401001 = "嗨，薇絲",
  str_homestory_chat_25401002 = "今天的打扮......",
  str_homestory_chat_25401003 = "偶爾也要換一下衣著，怎麼樣？",
  str_homestory_chat_25401004 = "很適合妳！",
  str_homestory_chat_25421001 = "今天怎麼樣？",
  str_homestory_chat_25421002 = "剛才去練習了一下射擊。",
  str_homestory_chat_25421003 = "用那柄弩嗎？",
  str_homestory_chat_25421004 = "是的，而且我還想到了快速射擊的方法。",
  str_homestory_chat_25421005 = "主要就是如何快速上弦......",
  str_homestory_chat_25421006 = "啊，看來是要藉用某種啟光科技了。",
  str_homestory_chat_25421007 = "看來你已經想到啦。",
  str_homestory_chat_25421008 = "不過缺陷還很大，主要是用上一會，弦就會斷。",
  str_homestory_chat_25421009 = "看來還需要改進。",
  str_homestory_chat_25422001 = "妳最近有新計畫？",
  str_homestory_chat_25422002 = "是的，想重新整理一下靶場。",
  str_homestory_chat_25422003 = "靶場......我們有這種地方嗎？",
  str_homestory_chat_25422004 = "啊？那邊那幾顆樹......",
  str_homestory_chat_25422005 = "我一直拿它們當做靶子來著......",
  str_homestory_chat_25422006 = "這......也好，反正那些樹皮糙肉厚。",
  str_homestory_chat_25422007 = "不過，其實用石頭當做靶子也沒問題。",
  str_homestory_chat_25422008 = "石頭靶子......有點太矮了。",
  str_homestory_chat_25422009 = "而且會損壞弩矢的頭呢。",
  str_homestory_chat_25422010 = "嗯......看來還是需要專門的靶場。",
  str_homestory_chat_25423001 = "妳找我？",
  str_homestory_chat_25423002 = "PlayerName，你會釣魚嗎？",
  str_homestory_chat_25423003 = "會",
  str_homestory_chat_25423004 = "真的？",
  str_homestory_chat_25423005 = "前些日子剛剛釣上來一些......",
  str_homestory_chat_25423006 = "那是你運氣好吧......",
  str_homestory_chat_25423007 = "不太行......",
  str_homestory_chat_25423008 = "沒事，我有祕密武器。",
  str_homestory_chat_25423009 = "就是把我那柄弩改造一下......",
  str_homestory_chat_25423010 = "將弩矢加上捕魚用的頭，連上繩子......",
  str_homestory_chat_25423011 = "不僅讓你能抓到魚，而且會很快地抓到魚。",
  str_homestory_chat_25423012 = "這個......那就不叫釣魚了吧。",
  str_homestory_chat_25599999 = "你好啊，哈哈！",
  str_homestory_chat_25501001 = "你的衣服......",
  str_homestory_chat_25501002 = "別被這副樣子嚇到，我會經常這麼穿的。",
  str_homestory_chat_25501003 = "嗯，我會習慣的。",
  str_homestory_chat_25501004 = "對，畢竟很多人說這樣看起來更加威風。",
  str_homestory_chat_25501005 = "這個很多人......我很疑惑是誰。",
  str_homestory_chat_25521001 = "你要問我什麼事？",
  str_homestory_chat_25521002 = "在戰鬥中，你覺得用刀好還是用槍好？",
  str_homestory_chat_25521003 = "刀",
  str_homestory_chat_25521004 = "說的對！因為它能給敵人帶來壓迫感。",
  str_homestory_chat_25521005 = "而且在近身格鬥中，還能迅速地連擊。",
  str_homestory_chat_25521006 = "這也是我為什麼選擇它作為我的武器的原因。",
  str_homestory_chat_25521007 = "槍",
  str_homestory_chat_25521008 = "嗯......是基於空裔的角度？",
  str_homestory_chat_25521009 = "畢竟你們感知能力很強，射擊應該也很準確吧。",
  str_homestory_chat_25521010 = "可是......我......",
  str_homestory_chat_25521011 = "你是訓練太少了，過幾天我給你來一個特訓！",
  str_homestory_chat_25521012 = "保證你成為特等射手！",
  str_homestory_chat_25521013 = "好......好的。",
  str_homestory_chat_25521014 = "我不知道......",
  str_homestory_chat_25521015 = "確實，你不太擅長戰鬥。",
  str_homestory_chat_25521016 = "也許我應該換一個其他人問，比如說薇絲......",
  str_homestory_chat_25521017 = "在這裡，你就不要天天想著戰鬥的事情了......",
  str_homestory_chat_25522001 = "找我有事情？",
  str_homestory_chat_25522002 = "話說，刀似乎有點鈍了，這附近有好的磨刀石嗎？",
  str_homestory_chat_25522003 = "有",
  str_homestory_chat_25522004 = "要好的磨刀石，就是那種又光滑又有點毛刺的......",
  str_homestory_chat_25522005 = "這種的話......可能就沒有了。",
  str_homestory_chat_25522006 = "沒有",
  str_homestory_chat_25522007 = "唉......不愧是空裔。",
  str_homestory_chat_25522008 = "果然是愛好和平的人......",
  str_homestory_chat_25522009 = "連武器都不懂得保養啊。",
  str_homestory_chat_25523001 = "妳在做什麼？",
  str_homestory_chat_25523002 = "......真是好安靜的地方啊。",
  str_homestory_chat_25523003 = "看來退役了，就可以在這裡隱居。",
  str_homestory_chat_25523004 = "巴頓......",
  str_homestory_chat_25523005 = "啊？你聽到了？我剛才在自言自語！",
  str_homestory_chat_25523006 = "退役......",
  str_homestory_chat_25523007 = "不過巴頓你還很年輕......",
  str_homestory_chat_25523008 = "啊，我剛才是抽風了。",
  str_homestory_chat_25523009 = "如果可以的話，我其實不想退役。",
  str_homestory_chat_25523010 = "如果太老了，那最好在一場大戰中被最後一顆子彈幹掉。",
  str_homestory_chat_25523011 = "那才是一名士兵的最好歸宿。",
  str_homestory_chat_25523012 = "可是......你是將軍啊......",
  str_homestory_chat_25699999 = "嗨，PlayerName，又見到你了。",
  str_homestory_chat_25601001 = "嗨，妮娜。",
  str_homestory_chat_25601002 = "每次只要來到這裡，本小姐都不禁想問你一個問題。",
  str_homestory_chat_25601003 = "問題？",
  str_homestory_chat_25601004 = "空裔的審美，都如此樸素？",
  str_homestory_chat_25601005 = "這......確實。",
  str_homestory_chat_25601006 = "不過意外地，和這附近的環境滿搭配，住得還算舒服。",
  str_homestory_chat_25601007 = "今後就保持這樣吧，不要學影鎮的那些俗氣潮流。",
