  str_homestory_chat_27221006 = "真的沒有......",
  str_homestory_chat_27222001 = "妳要買什麼？",
  str_homestory_chat_27222002 = "有沒有支架？最好是帶滑輪，可以在地上移動的那種。",
  str_homestory_chat_27222003 = "妳要它做什麼？",
  str_homestory_chat_27222004 = "拍攝啊。總是讓塞洛洛提著機器也不太好，牠也會累的。",
  str_homestory_chat_27222005 = "現在又不太富裕，僱不起專門的攝影師......",
  str_homestory_chat_27222006 = "原來是這樣，不過想來這種東西，應該是在影鎮才有吧？",
  str_homestory_chat_27222007 = "但是影鎮的很貴呀～",
  str_homestory_chat_27223001 = "妳似乎很閒的樣子？",
