  str_homestory_chat_27223003 = "沒有。",
  str_homestory_chat_27223004 = "有吧......",
  str_homestory_chat_27223005 = "有時候會看看薇絲他們送過來的書。",
  str_homestory_chat_27223006 = "唉，聽起來似乎從你這裡沒法發現什麼。",
  str_homestory_chat_27223007 = "我還想讓你幫忙推薦一些短篇故事呢，尤其是那種驚悚的......",
  str_homestory_chat_27223008 = "感覺妳很喜歡看那種故事，完全不害怕？",
  str_homestory_chat_27223009 = "哼！比起窮日子來說，那些都算不上什麼！",
  str_homestory_chat_27223010 = "而且，萬一根據這些故事拍了電影，或許我就可以當女主角。",
  str_homestory_chat_27223011 = "成為真正的大明星......嘿嘿。",
  str_homestory_chat_27223012 = "咳咳，我先走了。",
  str_homestory_chat_27224001 = "粉絲？",
  str_homestory_chat_27224002 = "你似乎也小有名氣，有沒有粉絲？",
  str_homestory_chat_27224003 = "應該有。",
  str_homestory_chat_27224004 = "喔？是誰！",
  str_homestory_chat_27224005 = "其實......我也不太清楚。",
  str_homestory_chat_27224006 = "沒有。",
  str_homestory_chat_27224007 = "太可惜了。",
  str_homestory_chat_27224008 = "不過，無論有沒有粉絲，你都應該朝著自己的方向努力！",
  str_homestory_chat_27224009 = "這是應該的。",
  str_homestory_chat_27224010 = "所以說偶爾也要給自己加油，對吧？",
