  str_homestory_chat_27224012 = "只是......偶爾會累而已。",
  str_homestory_chat_27225001 = "妳要買什麼？",
  str_homestory_chat_27225002 = "想吃魚了......",
  str_homestory_chat_27225003 = "河裡不是有很多嗎？讓那個塞洛洛抓一些就好了。",
  str_homestory_chat_27225004 = "可是我想吃的是海鮮，不是河鮮。",
