  str_homestory_chat_27225010 = "妳這形容，真的是在吃飯嗎......",
  str_homestory_chat_27399999 = "尊敬的PlayerName，米洛斯隨時為您服務。",
  str_homestory_chat_27301001 = "你好，米洛斯。",
  str_homestory_chat_27301002 = "感覺你總是彬彬有禮的，在空庭完全可以放鬆一些。",
