  str_homestory_chat_27321003 = "有。",
  str_homestory_chat_27321004 = "是哪位丘布？",
  str_homestory_chat_27321005 = "咳咳......牠們可不會，應該有某位夥伴會吧。",
  str_homestory_chat_27321006 = "沒有。",
  str_homestory_chat_27321007 = "唉，真是可惜。",
  str_homestory_chat_27321008 = "你的槍壞了？",
  str_homestory_chat_27321009 = "沒有，作為管家，時刻保持武器的良好運作，也是分內工作。",
  str_homestory_chat_27321010 = "因為不能確定主人什麼時候會遇到危險。",
  str_homestory_chat_27321011 = "你實在是太盡職盡責......",
  str_homestory_chat_27322001 = "妳找我有什麼事？",
  str_homestory_chat_27322002 = "尊敬的PlayerName，我需要您為我提供準確的時間。",
  str_homestory_chat_27322003 = "你的錶......出問題了？",
  str_homestory_chat_27322004 = "再精密的儀器也會有出現差錯之時，就在今天早上......",
  str_homestory_chat_27322005 = "我感覺它似乎比昨天走慢了一絲。",
