  str_homestory_chat_27322009 = "我，我可以羨慕你的主人嗎？",
  str_homestory_chat_27322010 = "如果能有你這樣一個幫手，該多好啊......",
  str_homestory_chat_27323001 = "你似乎在思考什麼。",
  str_homestory_chat_27323002 = "是的，您認為管家應該怎樣對待主人呢？",
  str_homestory_chat_27323003 = "服從。",
