  str_homestory_chat_27323005 = "恕我直言，我並不認同這一點。",
  str_homestory_chat_27323006 = "輔佐。",
  str_homestory_chat_27323007 = "說得對！",
  str_homestory_chat_27323008 = "管家不能只是聽命而行，更多的時候要提醒主人發現自己的錯誤。",
  str_homestory_chat_27323009 = "因此，管家與主人在人格上是平等的。",
  str_homestory_chat_27323010 = "也確實應該如此。",
  str_homestory_chat_27324001 = "感覺這裡如何？",
  str_homestory_chat_27324002 = "真是個美麗的地方，雖然很大，但是很乾淨。",
  str_homestory_chat_27324003 = "看來丘布們把這裡打掃得很好。",
  str_homestory_chat_27324004 = "不不，也有大家努力維護的結果。",
  str_homestory_chat_27324005 = "尊敬的PlayerName，您真的太謙虛了。",
  str_homestory_chat_27324006 = "來到空庭，只能感嘆這裡真的很適合居住。",
  str_homestory_chat_27324007 = "無論是環境、氣候還是日照程度，都是上佳的。",
