  str_homestory_chat_28223002 = "對，暈船藥，你有嗎？",
  str_homestory_chat_28223003 = "沒有。",
  str_homestory_chat_28223004 = "可能有……",
  str_homestory_chat_28223005 = "不過等下！妳找這個幹什麼？",
  str_homestory_chat_28223006 = "妳是老船長了呀！",
  str_homestory_chat_28223007 = "當然是給別人準備的，有很多人都暈船的。",
  str_homestory_chat_28223008 = "甚至一些老水手偶爾也會的。",
  str_homestory_chat_28223009 = "原來如此，我會去找一下的。",
  str_homestory_chat_28224001 = "聽說妳要找船？",
  str_homestory_chat_28224002 = "對，我看到河流自然就想起來。",
  str_homestory_chat_28224003 = "空庭對外閉塞，山路不通，但是這河道似乎還算順暢。",
  str_homestory_chat_28224004 = "於是我就在想能不能用這河道做一些日常貿易。",
  str_homestory_chat_28224005 = "別了。",
  str_homestory_chat_28224006 = "為何？",
  str_homestory_chat_28224007 = "河道雖然順暢，不過根據丘布們說，似乎逆流很多。",
  str_homestory_chat_28224008 = "而且很多時候暗礁特別多，吃水淺，很容易翻船的。",
  str_homestory_chat_28224009 = "可以考慮。",
  str_homestory_chat_28224010 = "真的嗎？不會有什麼問題？",
  str_homestory_chat_28224011 = "聽丘布說似乎河道裡的水文情況挺複雜的……",
  str_homestory_chat_28224012 = "但是具體什麼樣子，我也不清楚。",
  str_homestory_chat_28224013 = "複雜的河道嗎？有必要先要探查一番。",
  str_homestory_chat_28224014 = "看來……是我唐突了。",
  str_homestory_chat_28225001 = "妳的那柄刀……",
  str_homestory_chat_28225002 = "怎麼了？",
  str_homestory_chat_28225003 = "有人投訴妳來著……",
  str_homestory_chat_28225004 = "啊？是誰？為什麼？",
  str_homestory_chat_28225005 = "是那些丘布。牠們看到妳總在把玩那柄刀。",
  str_homestory_chat_28225006 = "總感覺妳會對牠們動手似的。",
  str_homestory_chat_28225007 = "沒錯……",
  str_homestory_chat_28225008 = "我來空庭的目的就是做這個，狩獵丘布。",
  str_homestory_chat_28225009 = "真的？！",
  str_homestory_chat_28225010 = "你相信？",
  str_homestory_chat_28225011 = "肯定不會的啊。",
  str_homestory_chat_28225012 = "所以你在擔心什麼？就這樣回去告訴丘布吧。",
  str_homestory_chat_28225013 = "牠們根本是在害怕莫須有的東西，我只是習慣性耍弄刀而已。",
  str_homestory_chat_28225014 = "好、好吧。",
  str_homestory_chat_28399999 = "嗨，PlayerName，要來點草藥嚐嚐嗎？",
  str_homestory_chat_28301001 = "嗨！看來找到了不少！",
  str_homestory_chat_28301002 = "沒錯！這裡的氣候真適合各種草藥生長！",
  str_homestory_chat_28301003 = "僅僅是自然中的各種植物，就有很多不同的藥效了。",
  str_homestory_chat_28301004 = "更別提那些奇妙的樹……",
  str_homestory_chat_28301005 = "你、你把目標放到了奇異樹？",
  str_homestory_chat_28301006 = "暫時還沒有，畢竟丘布們對它們的管理似乎很嚴格。",
  str_homestory_chat_28301007 = "所以最近考慮在此地移種一些龍洲的草藥。",
  str_homestory_chat_28301008 = "啊，這個方向好。",
  str_homestory_chat_28321001 = "零食？",
  str_homestory_chat_28321002 = "這裡有什麼零食？最近都在吃粥……",
  str_homestory_chat_28321003 = "我問了丘布商人，牠告訴我什麼都沒有！",
  str_homestory_chat_28321004 = "難道整個艾斯特拉大陸，都沒有什麼好的零食嗎？",
  str_homestory_chat_28321005 = "不，有的！",
  str_homestory_chat_28321006 = "說來聽聽！",
  str_homestory_chat_28321007 = "北境的軟糖。",
  str_homestory_chat_28321008 = "軟綿可口，不太甜，也不沾牙，滾進喉嚨中都有回甜。",
  str_homestory_chat_28321009 = "影鎮的巧克力。",
  str_homestory_chat_28321010 = "純巧克力是苦的，所以很多店鋪都會加入牛奶、糖，甚至各種乾果。",
  str_homestory_chat_28321011 = "比如榛子、松子、橡果……",
  str_homestory_chat_28321012 = "你別說了……",
  str_homestory_chat_28321013 = "你的口水……",
  str_homestory_chat_28321014 = "哎呀！終有一天我要去吃這些零食，這段時間看來只能靠……",
  str_homestory_chat_28321015 = "想像度日了。",
  str_homestory_chat_28321016 = "從某種角度來說，你也很厲害。",
  str_homestory_chat_28322001 = "秤？",
  str_homestory_chat_28322002 = "對，看看我的這個傢伙。",
  str_homestory_chat_28322003 = "來到艾斯特拉大陸後，發現這裡稱重量和我們那邊不一樣呢！",
  str_homestory_chat_28322004 = "都是用擺在地上的那個東西，兩邊各自有一個盤子的。",
  str_homestory_chat_28322005 = "你說的應該是天平。",
  str_homestory_chat_28322006 = "對，但是似乎攜帶起來很不方便，而且還需要有平整地面。",
  str_homestory_chat_28322007 = "我的秤就好用多啦，艾斯特拉大陸的人都這麼不開竅嗎？",
  str_homestory_chat_28322008 = "那個……其實在影鎮，也有用秤的。",
  str_homestory_chat_28322009 = "啊？",
  str_homestory_chat_28322010 = "起碼林家商會如此，而且天平很準確的。",
  str_homestory_chat_28322011 = "秤……多少會受到操作者的影響。",
  str_homestory_chat_28322012 = "我明白了，果然還是那句老話——「卜子曰，因地制宜」！",
  str_homestory_chat_28322013 = "是「各有所長」吧。",
  str_homestory_chat_28323001 = "你要找貓？",
  str_homestory_chat_28323002 = "對，準確說是我的哥哥想要個夥伴呢。",
  str_homestory_chat_28323003 = "你的哥哥？",
  str_homestory_chat_28323004 = "就是小尾巴。到底有沒有貓？",
  str_homestory_chat_28323005 = "這裡還真沒有……不過來入住的夥伴們可能會帶上那麼一兩隻。",
  str_homestory_chat_28323006 = "你不如去問問他們。",
  str_homestory_chat_28323007 = "可是他們都是艾斯特拉大陸的人啦，多少有些不太熟悉。",
  str_homestory_chat_28323008 = "都住在這裡了還不熟悉！沒事的！",
  str_homestory_chat_28323009 = "真、真的？",
  str_homestory_chat_28323010 = "你這麼活潑，一定沒問題的。",
  str_homestory_chat_28323011 = "果然！看來還是要依靠我出馬才行，我過幾日就去問問～",
  str_homestory_chat_28499999 = "空裔小哥，今天怎麼這麼有空。",
  str_homestory_chat_28421001 = "你看起來也挺閒的啊。",
  str_homestory_chat_28421002 = "我只是在散步。",
  str_homestory_chat_28421003 = "散步？",
  str_homestory_chat_28421004 = "因為沒有特別的工作可做。況且在此空庭之中，工作本就不多。",
  str_homestory_chat_28421005 = "更別提能引起我興趣的工作，所以就變成這樣了。",
  str_homestory_chat_28421006 = "好吧。",
  str_homestory_chat_28422001 = "聊一聊食物的話題？",
  str_homestory_chat_28422002 = "也好。不曉得空裔小哥喜歡吃什麼？",
  str_homestory_chat_28422003 = "甜點。",
  str_homestory_chat_28422004 = "居然喜歡甜的……很普通呢。",
  str_homestory_chat_28422005 = "大家不都喜歡嗎？例如巧克力。",
  str_homestory_chat_28422006 = "但巧克力本身是苦的，讓你感覺甜的是額外添加的糖。",
  str_homestory_chat_28422007 = "所以說……難道你喜歡的是苦味？",
  str_homestory_chat_28422008 = "不是啦……",
  str_homestory_chat_28422009 = "肉。",
  str_homestory_chat_28422010 = "好胃口！那肝臟呢？特別是肝臟做的那種小零食。",
  str_homestory_chat_28422011 = "抱歉，我不能接受那個。",
  str_homestory_chat_28422012 = "唉，太可惜了。",
  str_homestory_chat_28423001 = "妳要找木材？",
  str_homestory_chat_28423002 = "對，我想在我的房間裡造一座小窩，可以嗎？",
  str_homestory_chat_28423003 = "可以。",
  str_homestory_chat_28423004 = "還是不要吧。",
  str_homestory_chat_28423005 = "不過，妳造窩要做什麼？",
  str_homestory_chat_28423006 = "為那孩子造個家呀，最近牠經常睡不好……",
  str_homestory_chat_28423007 = "那孩子？",
  str_homestory_chat_28423008 = "就是幽青巨蟒，總不能老是任牠睡在別人床上吧……",
  str_homestory_chat_28423009 = "當、當然不行囉！會嚇到人的。",
  str_homestory_chat_28423010 = "聽起來你是允許建造囉？",
  str_homestory_chat_28423011 = "那……就在妳床下建一座吧。",
  str_homestory_chat_28424001 = "書？",
  str_homestory_chat_28424002 = "對。想問問空裔小哥喜歡看哪種書？",
  str_homestory_chat_28424003 = "小說。",
  str_homestory_chat_28424004 = "相當普遍的類型呢……",
  str_homestory_chat_28424005 = "但有不少小說都很精彩呢，尤其是影鎮的各種推理小說……",
  str_homestory_chat_28424006 = "看來這確實是頗大眾的喜好呢……",
  str_homestory_chat_28424007 = "人物傳記。",
  str_homestory_chat_28424008 = "哦？有點意思。你對歷史有興趣？",
  str_homestory_chat_28424009 = "想多瞭解一下艾斯特拉大陸的過去。",
  str_homestory_chat_28424010 = "話說回來，耶利亞喜歡看什麼書呢？",
  str_homestory_chat_28424011 = "哲學。",
  str_homestory_chat_28424012 = "竟然！",
  str_homestory_chat_28424013 = "你好像很驚訝，其實哲學真的很有意思。有機會我來推薦你幾本。",
  str_homestory_chat_28424014 = "好、好吧。",
  str_homestory_chat_28425001 = "丘布？",
  str_homestory_chat_28425002 = "對，我發現那個丘布真的很有智慧。",
  str_homestory_chat_28425003 = "哪個丘布？",
  str_homestory_chat_28425004 = "就是風信塔廣場那個呀，有鬍子的那位。",
  str_homestory_chat_28425005 = "丘布長老？",
  str_homestory_chat_28425006 = "對啊。你看牠都頂著「長老」名號了，當然有智慧。",
  str_homestory_chat_28425007 = "就只因為這樣嗎……",
  str_homestory_chat_28425008 = "其實那個「長老」不外乎是慣稱，至於那道鬍子……",
  str_homestory_chat_28425009 = "鬍子怎麼了？",
  str_homestory_chat_28425010 = "好像是牠自己戴上的，其實是假鬍子啦。",
