  str_homestory_chat_28425012 = "實在是太尷尬了……",
  str_homestory_chat_28425013 = "那……我先走了。",
  str_homestory_chat_28599999 = "嗨，PlayerName，今天有計畫嗎？",
  str_homestory_chat_28501001 = "沒什麼事啊，妳呢？",
  str_homestory_chat_28501002 = "我想在空庭內找份兼差。",
  str_homestory_chat_28501003 = "妳要兼差？",
  str_homestory_chat_28501004 = "我已經問過丘布長老與丘布商人，他們似乎都沒有需求。",
