  str_homestory_chat_28521006 = "願聞其詳。",
  str_homestory_chat_28521007 = "就是傷害同伴的傢伙。",
  str_homestory_chat_28521008 = "原來如此。",
  str_homestory_chat_28521009 = "那凱雅討厭什麼東西呢？",
  str_homestory_chat_28521010 = "遲到的人！",
  str_homestory_chat_28521011 = "怎能不守時呢……況且大多時候都是事先講定的。",
  str_homestory_chat_28521012 = "說遲到一下下無所謂的那種傢伙……都應該好好地教訓一番！",
