  str_homestory_chat_28522011 = "可惜價格太貴了，工作十年才買得起。若有折扣就只需要工作兩年半……",
  str_homestory_chat_28522012 = "呃……妳們的薪水這麼少嗎……",
  str_homestory_chat_28522013 = "一切都是因為影鎮賣得太貴了！一群奸商！",
  str_homestory_chat_28522014 = "沒錯！",
  str_homestory_chat_28523001 = "食物？",
  str_homestory_chat_28523002 = "對啊，不曉得PlayerName平常都吃什麼？",
  str_homestory_chat_28523003 = "嗯……有什麼吃什麼啊。",
  str_homestory_chat_28523004 = "這麼隨意？",
  str_homestory_chat_28523005 = "我時常在喝巨像調配的營養液呢。",
  str_homestory_chat_28523006 = "唉……這麼不求享受……但和我差不多呢。",
  str_homestory_chat_28523007 = "咦？什麼差不多？",
  str_homestory_chat_28523008 = "有時為了不耽誤時間，我只吃硬麵包或乾肉條呢。",
