  str_homestory_chat_28523011 = "那個……妳徹底解讀錯誤了。",
  str_homestory_chat_28699999 = "好悠閒啊，PlayerName。",
  str_homestory_chat_28621001 = "妳也是。",
  str_homestory_chat_28621002 = "確實。這種感覺真的很放鬆，讓人好想睡覺……哈欠～",
  str_homestory_chat_28621003 = "哈欠～",
  str_homestory_chat_28621004 = "咦，看來你也是嘛？",
