  str_homestory_chat_28623001 = "暗鬼？",
  str_homestory_chat_28623002 = "暗鬼好像從沒跑進來這裡過。",
  str_homestory_chat_28623003 = "沒錯。",
  str_homestory_chat_28623004 = "如果真的跑進來，那可不得了。",
  str_homestory_chat_28623005 = "唉……那要怎麼找牠……",
  str_homestory_chat_28623006 = "「牠」？",
  str_homestory_chat_28623007 = "啊，沒事！就算沒有暗鬼，我問一下哪裡有暗鬼的蹤跡也是很合理的吧。",
  str_homestory_chat_28623008 = "你知道些什麼嗎？",
  str_homestory_chat_28623009 = "反正這裡沒有，妳就打消這念頭吧。",
