  str_homestory_chat_28624004 = "因為太遠啦！就想在附近逛逛有沒有書店，隨便買本來打發時間啦。",
  str_homestory_chat_28624005 = "白夜城離影鎮不是很近嗎……",
  str_homestory_chat_28624006 = "可是我已經來到這裡啦。那個丘布商人沒有賣嗎？",
  str_homestory_chat_28624007 = "據我所知沒有。",
  str_homestory_chat_28624008 = "哎呀，看來只能……哈欠……",
  str_homestory_chat_28624009 = "去小睡一下吧，這樣也可以打發時間。",
  str_homestory_chat_28625001 = "零食？",
  str_homestory_chat_28625002 = "對，不知道PlayerName喜歡吃什麼零食呢？",
  str_homestory_chat_28625003 = "小蛋糕。",
  str_homestory_chat_28625004 = "居然喜歡吃甜的……吃了不會不舒服嗎？",
  str_homestory_chat_28625005 = "沒有。妳不喜歡吃甜的嗎，蒂娜？",
  str_homestory_chat_28625006 = "餅乾。",
  str_homestory_chat_28625007 = "尤其是稍微帶點鹹味的，配上熱水十分美味。",
  str_homestory_chat_28625008 = "你的選擇非常正確！零食不能只有甜的……",
  str_homestory_chat_28625009 = "多種口味的零食才是王道！",
  str_homestory_chat_28625010 = "妳好像很不喜歡甜食……",
  str_homestory_chat_28625011 = "很不喜歡。因為吃了以後會莫名焦躁，睡不著。",
  str_homestory_chat_28625012 = "輾轉反側很難受的，你懂吧？",
  str_homestory_chat_28625013 = "我能理解，而且隔天也會很疲累。",
  str_homestory_chat_28625014 = "是啊，所以我有時候才要在白天也睡覺。",
  str_homestory_chat_28625015 = "明明沒吃甜食的時候妳也一直在睡……",
  str_homestory_chat_28999999 = "PlayerName，需要我做什麼？",
  str_homestory_chat_28921001 = "啊？隨便聊聊就好。",
  str_homestory_chat_28921002 = "看來您也是很閒。要不要培養一些嗜好？",
  str_homestory_chat_28921003 = "比如說？",
  str_homestory_chat_28921004 = "像種花就很不錯。",
  str_homestory_chat_28921005 = "看著它播種、抽芽、成長，最終盛開出瑰麗的花朵……",
  str_homestory_chat_28921006 = "就不由得感嘆自然的美妙。",
  str_homestory_chat_28921007 = "我已經種樹了……",
  str_homestory_chat_28921008 = "種樹也很好。只要付出耐心，終會等到有所感悟的那天。",
  str_homestory_chat_28922001 = "你的武器......",
  str_homestory_chat_28922002 = "怎麼了？",
  str_homestory_chat_28922003 = "有時候覺得它不像武器，尤其那個鑽頭。",
  str_homestory_chat_28922004 = "我明白，看起來不像是白夜城騎士所用的一般武器吧。",
  str_homestory_chat_28922005 = "沒錯，很多騎士用的都是劍、長矛什麼的……",
  str_homestory_chat_28922006 = "所以這背後有什麼原因嗎？",
  str_homestory_chat_28922007 = "原因不重要，就像騎士的武器也不重要。",
  str_homestory_chat_28922008 = "不重要？",
  str_homestory_chat_28922009 = "因為決定一名騎士的，乃是人身上的騎士精神。",
  str_homestory_chat_28922010 = "我知道！就是「騎士之美德」，謙卑、寬容什麼的……",
  str_homestory_chat_28922011 = "沒錯。一個人有了它才是騎士，而不是什麼武器。",
  str_homestory_chat_28922012 = "我懂了……",
  str_homestory_chat_28923001 = "你要買什麼？",
  str_homestory_chat_28923002 = "想買一些油。",
  str_homestory_chat_28923003 = "什麼油呢？",
  str_homestory_chat_28923004 = "如果是食用油，應該買得到。",
  str_homestory_chat_28923005 = "用來潤滑機件的，在影鎮就能買到。",
  str_homestory_chat_28923006 = "這個……",
  str_homestory_chat_28923007 = "不太好弄到吧？畢竟這裡是個綠意盎然的地方。",
  str_homestory_chat_28923008 = "嗯……這裡確實用不太到這種東西。",
  str_homestory_chat_28923009 = "主要是我想保養一下這武器，它最近有點卡卡的。",
