  str_homestory_chat_28923011 = "那……還是抽空去一趟影鎮吧。",
  str_homestory_chat_28924001 = "你在想什麼？",
  str_homestory_chat_28924002 = "我在思考一件很重要的事情，但是總覺得找不到答案。",
  str_homestory_chat_28924003 = "不妨說來聽聽？",
  str_homestory_chat_28924004 = "您認為公正重要，還是平等重要？",
  str_homestory_chat_28924005 = "公正。",
  str_homestory_chat_28924006 = "那麼您是否認同讓弱勢者擁有較多的權利？",
  str_homestory_chat_28924007 = "比如即便他們犯下一些輕罪，也應給予豁免？",
  str_homestory_chat_28924008 = "我想想……",
  str_homestory_chat_28924009 = "平等。",
  str_homestory_chat_28924010 = "如果有一場短跑比賽，有兩名選手。",
  str_homestory_chat_28924011 = "一位經常練習短跑，另一位則是斷了一條腿的士兵。",
  str_homestory_chat_28924012 = "按照您的說法，獲勝的標準不應參考這兩位的身體狀況。",
  str_homestory_chat_28924013 = "是的。",
  str_homestory_chat_28924014 = "可是這樣真的好嗎？",
  str_homestory_chat_28924015 = "哎呀……這些問題真的好煩人，感覺找不到答案。",
  str_homestory_chat_28924016 = "是啊……這也是我在這裡走來走去的原因。",
  str_homestory_chat_28925001 = "紅油沙漠？",
  str_homestory_chat_28925002 = "聽說您走訪過許多地方，可有去過那裡？",
  str_homestory_chat_28925003 = "沒什麼印象了。",
  str_homestory_chat_28925004 = "唉......太可惜了。",
  str_homestory_chat_28925005 = "看來零恩去過？",
  str_homestory_chat_28925006 = "有幸造訪幾次。那裡的光景確實與白夜城大相逕庭。",
  str_homestory_chat_28925007 = "人們的觀念也與白夜城差很多。縱使生活艱難，人群中卻也不乏勇者。",
  str_homestory_chat_28925008 = "看來零恩在紅油沙漠還有什麼故事……",
