  str_homestory_chat_28925013 = "的確如此，雖然不太能適應，卻也是大陸上必要的存在。",
  str_homestory_chat_28925014 = "世界上很多事情都是如此。",
  str_homestory_chat_29099999 = "PlayerName，今天很適合散步。",
  str_homestory_chat_29001001 = "你好呀，馬太。",
  str_homestory_chat_29001002 = "感覺你今天一樣很悠閒。這裡的庶民很鬆懈呀。",
  str_homestory_chat_29001003 = "這裡沒有庶民，大家都是平等的。",
