  str_homestory_chat_29022001 = "餐具？",
  str_homestory_chat_29022002 = "此地的餐具太粗糙了。看著它們，再美味的餐點也難以下嚥呀。",
  str_homestory_chat_29022003 = "沒這麼誇張吧！",
