  str_homestory_chat_29323001 = "妳要問丘布什麼事？",
  str_homestory_chat_29323002 = "我想問一下，可以讓他們做我的侍從嗎？",
  str_homestory_chat_29323003 = "空庭裡倒是沒有這個先例，而且白夜城允許這樣做嗎？",
  str_homestory_chat_29323004 = "我是一名騎士，自然有招募侍從的權利，您能不能答應？空庭的主人。",
  str_homestory_chat_29323005 = "能。",
  str_homestory_chat_29323006 = "我要考慮一下。",
  str_homestory_chat_29323007 = "等一下！為什麼突然想要讓它們做妳的侍從？",
  str_homestory_chat_29323008 = "因為感覺他們很適合啊！",
  str_homestory_chat_29323009 = "方方正正的腦袋，方方正正的身材……",
  str_homestory_chat_29323010 = "一定會成為遵守騎士美德的好侍從！",
  str_homestory_chat_29323011 = "我覺得妳完全理解錯了……",
  str_homestory_chat_29323012 = "不會的！俗話說「相由心生」，一定可以的！",
  str_homestory_chat_29323013 = "那恕我不能答應……因為真的不行。",
  str_homestory_chat_29324001 = "歌劇？",
  str_homestory_chat_29324002 = "想問您對歌劇有什麼印象？",
  str_homestory_chat_29324003 = "還不錯。",
  str_homestory_chat_29324004 = "那就沒問題了！",
  str_homestory_chat_29324005 = "沒什麼感覺……",
  str_homestory_chat_29324006 = "唉，看來難辦了。",
  str_homestory_chat_29324007 = "妳要做什麼？",
  str_homestory_chat_29324008 = "我想在空庭裡建一座舞台，這樣就可以請歌劇團來表演了。",
  str_homestory_chat_29324009 = "如果有餘力的話……弄一個歌劇院也不錯，再加上常駐的歌劇團。",
