  str_homestory_chat_29324011 = "這個……不可能達成吧。",
  str_homestory_chat_29999999 = "嗨，最近怎麼樣？",
  str_homestory_chat_29901001 = "很好呀，妳呢？",
  str_homestory_chat_29901002 = "已經適應了空庭的生活，只是覺得步調有點緩慢。",
  str_homestory_chat_29901003 = "緩慢？",
  str_homestory_chat_29901004 = "如果偶爾來些有挑戰性的活動就好了，比如砍樹大賽？",
  str_homestory_chat_29901005 = "還是好好享受悠閒的時光吧。",
  str_homestory_chat_29921001 = "飲料？",
  str_homestory_chat_29921002 = "你喜歡什麼飲料？",
  str_homestory_chat_29921003 = "咖啡。",
  str_homestory_chat_29921004 = "很大眾的口味，看來是受夥伴影響？",
