  str_homestory_chat_29921006 = "如果去咖啡廳喝咖啡，也能順便和朋友們聊聊天。",
  str_homestory_chat_29921007 = "有道理。",
  str_homestory_chat_29921008 = "茶。",
  str_homestory_chat_29921009 = "為什麼喜歡茶呢？聽說有些茶很苦呢。",
