  str_homestory_chat_29921011 = "入口雖苦，嚥下後喉嚨會有一股甘香。",
  str_homestory_chat_29921012 = "聽說還可以提神。",
  str_homestory_chat_29921013 = "沒錯，推薦妳下次試試。",
  str_homestory_chat_29921014 = "果汁。",
  str_homestory_chat_29921015 = "偏好自然的口味嗎……果然是空裔。",
  str_homestory_chat_29921016 = "有些濃縮還原的果汁也不錯……我覺得可能是喜歡這種清新的感覺吧。",
