  str_homestory_chat_29922001 = "妳想種東西？",
  str_homestory_chat_29922002 = "我想在空庭這裡闢一片田，專門種豆子。",
  str_homestory_chat_29922003 = "好。",
  str_homestory_chat_29922004 = "這裡應該還有很多空地……不過先要問問丘布們。",
  str_homestory_chat_29922005 = "不行。",
  str_homestory_chat_29922006 = "等下，為什麼是豆子？",
  str_homestory_chat_29922007 = "根據啟光的研究，這種豆子最適合大規模種植，營養價值也很高。",
  str_homestory_chat_29922008 = "那口味呢？",
  str_homestory_chat_29922009 = "簡直千變萬化！尤其是各種豆製品！",
  str_homestory_chat_29922010 = "我記得影鎮也有很多……好像還有什麼「豆腐」。",
  str_homestory_chat_29922011 = "我知道！聽說那是從東方傳來的食物，簡直化腐朽為神奇！",
  str_homestory_chat_29922012 = "口感軟嫩，不調味的話，還帶有豆子的清香……",
