  str_homestory_chat_29922014 = "確實很厲害……",
  str_homestory_chat_29923001 = "妳想去影鎮？",
  str_homestory_chat_29923002 = "來空庭這麼久，忽然發現這裡和影鎮的交流很少。",
  str_homestory_chat_29923003 = "嗯，空庭整體來說還是個比較偏僻的地方。",
