  str_homestory_chat_29224013 = "考慮到這裡很安全，我可以將收藏品放在這裡，才想說建造一座專門的博物館。",
  str_homestory_chat_29224014 = "容我考慮一下。",
  str_homestory_chat_30099999 = "今天有什麼新消息？",
