  str_homestory_chat_30221004 = "不愧是此地的主人！有什麼結果？",
  str_homestory_chat_30221005 = "我查看過了，考慮到空庭的地形，保持現在這樣就很好。",
  str_homestory_chat_30221006 = "保持現在這樣嗎……感覺多少有些鬆懈，還是要加強戒備比較好。",
  str_homestory_chat_30221007 = "我會考慮的。",
  str_homestory_chat_30221008 = "沒有。",
  str_homestory_chat_30221009 = "如此鬆懈可不行！",
  str_homestory_chat_30221010 = "畢竟這裡很難被外人發現，大家來此地還是盡量放鬆一點。",
  str_homestory_chat_30221011 = "不用考慮這些安全問題啦。",
  str_homestory_chat_30221012 = "你確定？",
  str_homestory_chat_30221013 = "一定沒問題的！",
  str_homestory_chat_30221014 = "您想過嗎？",
  str_homestory_chat_30221015 = "這些日子巡視了幾遍，確實從一般意義上來說很安全。",
  str_homestory_chat_30221016 = "您這麼說，那就可以安心了。",
  str_homestory_chat_30221017 = "不過還是不能放鬆警惕，畢竟智者千慮必有一失……",
  str_homestory_chat_30221018 = "好、好吧。",
  str_homestory_chat_30221019 = "不用考慮。",
  str_homestory_chat_30221020 = "居然如此懈怠！你真的有在為此地考慮嗎？",
  str_homestory_chat_30221021 = "那個……我會仔細想想的。",
  str_homestory_chat_30222001 = "我在想空谷的事情。",
  str_homestory_chat_30222002 = "看來你終於在思考如何治理此地了！",
  str_homestory_chat_30222003 = "是的。",
  str_homestory_chat_30222004 = "但是現在還沒多少頭緒。",
  str_homestory_chat_30222005 = "啊……還沒有。",
  str_homestory_chat_30222006 = "您有什麼好的想法嗎？",
  str_homestory_chat_30222007 = "治理一處領地，最好用當地居民。",
  str_homestory_chat_30222008 = "當地居民……是指……",
  str_homestory_chat_30222009 = "自然是那些丘布。",
  str_homestory_chat_30222010 = "確實有點道理。",
  str_homestory_chat_30223001 = "其實是……",
  str_homestory_chat_30223002 = "看到今天天氣不錯，所以就出來散散步。",
  str_homestory_chat_30223003 = "看來你也喜歡在這種天氣散步，這確實會令人感到心神愉悅。",
  str_homestory_chat_30223004 = "晴天、安靜的氛圍、悠閒地散步，是一個能夠專心思考事情的環境。",
  str_homestory_chat_30223005 = "也不用非要思考什麼事情吧，單純地休息放鬆也是可以的。",
  str_homestory_chat_30223006 = "畢竟來到這裡，就是要享受一下輕鬆的氛圍的。",
  str_homestory_chat_30223007 = "這裡的氛圍的確輕鬆，但是對於我來說卻不太習慣。",
  str_homestory_chat_30223008 = "為什麼？",
  str_homestory_chat_30223009 = "身處白夜城之內，即便是萬里晴空，但肩膀上卻總是無比沉重。",
  str_homestory_chat_30223010 = "名為「責任」的重擔，讓我無時無刻不在思考。",
  str_homestory_chat_30223011 = "是不是太累了？既然來到空庭，最好還是休息一下。",
  str_homestory_chat_30223012 = "不，這種重擔能保護我、磨礪我，讓我能夠安心迎接挑戰。",
  str_homestory_chat_30223013 = "還是……不要那麼緊繃吧……",
  str_homestory_chat_30224001 = "我在想前幾天看的書。",
  str_homestory_chat_30224002 = "是什麼書？",
  str_homestory_chat_30224003 = "推理小說。",
  str_homestory_chat_30224004 = "最近在影鎮很流行的小說，還滿吸引人的，主要是人物情感方面……",
  str_homestory_chat_30224005 = "小說嗎……它們只能用於放鬆，能獲得的知識也相當有限。",
  str_homestory_chat_30224006 = "如果要真正地閱讀，還是要讀一些歷史方面的書。",
  str_homestory_chat_30224007 = "歷史書。",
  str_homestory_chat_30224008 = "好選擇。",
  str_homestory_chat_30224009 = "您看來也很喜歡讀歷史書？",
  str_homestory_chat_30224010 = "是的。",
  str_homestory_chat_30224011 = "畢竟以史為鏡，可知興衰，甚至能推測將來。",
  str_homestory_chat_30224012 = "雖然推測將來有點誇張，但是起碼能知道很多知識。",
  str_homestory_chat_30224013 = "比人工構造的虛假之事，要更有收穫。",
  str_homestory_chat_30224014 = "好，我會多讀一些的。",
  str_homestory_chat_30225001 = "是的。",
  str_homestory_chat_30225002 = "「日夜播撒種，從不曾停歇。」",
  str_homestory_chat_30225003 = "這是？",
  str_homestory_chat_30225004 = "白夜城的一句俗語，意思就是需要時時刻刻保持勤奮，你做到了，希望你能保持下去。",
  str_homestory_chat_30225005 = "我會的。",
  str_homestory_chat_30225006 = "如此一來，我可以考慮為你封爵，白夜城能多一些你這樣的貴族就好了。",
  str_homestory_chat_30225007 = "真的？！",
  str_homestory_chat_30225008 = "當然是開玩笑的。",
  str_homestory_chat_30225009 = "啊……這個，那就算了。",
  str_homestory_chat_30199999 = "你也是獨自一人？",
  str_homestory_chat_30121001 = "是的。",
  str_homestory_chat_30121002 = "看、看來你也喜歡獨處……",
  str_homestory_chat_30121003 = "不，只是在散步，畢竟天氣很不錯，又沒有什麼事情。",
  str_homestory_chat_30121004 = "你的休息方式就是散步嗎？感覺你很喜歡。",
  str_homestory_chat_30121005 = "還是有什麼其他的獨處方式？",
  str_homestory_chat_30121006 = "嗯……散步只是其中一種吧，我也喜歡偶爾找朋友聊天什麼的。",
  str_homestory_chat_30121007 = "是、是這樣啊……",
  str_homestory_chat_30122001 = "不是。",
  str_homestory_chat_30122002 = "咦？你的夥伴在哪裡？",
  str_homestory_chat_30122003 = "不，我不是那個意思，我是說正想找個人聊聊天，就碰上了妳……",
  str_homestory_chat_30122004 = "看來你很喜歡和人聊天啊。",
  str_homestory_chat_30122005 = "是的。",
  str_homestory_chat_30122006 = "有時候確實有想和朋友聊天的念頭……不知道妳有沒有？",
  str_homestory_chat_30122007 = "有的。",
  str_homestory_chat_30122008 = "啊……我還以為妳只喜歡獨處呢。",
  str_homestory_chat_30122009 = "確實，但是也會和你一樣，有時候想和別人說一些什麼。",
  str_homestory_chat_30122010 = "偶爾吧。",
  str_homestory_chat_30122011 = "嗯？我還以為你很喜歡聊天呢。",
  str_homestory_chat_30122012 = "也不是，有時候也喜歡一個人靜靜地待著，有時候就想和別人閒談。",
  str_homestory_chat_30122013 = "看心情……吧。妳呢？",
  str_homestory_chat_30122014 = "我大部分時間更喜歡獨處，但偶爾也和你一樣，想和別人說點什麼。",
  str_homestory_chat_30122015 = "尤其是她……我總是在想，如果能見到她，就要和她說一大堆的話呢。",
  str_homestory_chat_30122016 = "……希望妳能快點遇見她。",
  str_homestory_chat_30123001 = "妳在做什麼？",
  str_homestory_chat_30123002 = "我在想這裡要怎麼製作「騎士紅茶」。",
  str_homestory_chat_30123003 = "「騎士紅茶」？",
  str_homestory_chat_30123004 = "白夜城的一種飲料，很受人歡迎的。",
  str_homestory_chat_30123005 = "我聽說過，似乎原料有點不好弄。",
  str_homestory_chat_30123006 = "沒錯，要用到作為舶來品的茶葉……",
  str_homestory_chat_30123007 = "還需要上好的茶具、精心地沏泡和調味。",
  str_homestory_chat_30123008 = "要做好一杯可口的「騎士紅茶」，恐怕要等上一個下午呢。",
  str_homestory_chat_30123009 = "這麼久！",
  str_homestory_chat_30123010 = "對啊，畢竟是「下午茶」。",
  str_homestory_chat_30123011 = "如果是從上午開始做，是不是中午就可以喝到了。",
  str_homestory_chat_30123012 = "那不就是「中午茶」？甚至如果更早，就是「上午茶」？",
  str_homestory_chat_30123013 = "這個……我沒想過……",
  str_homestory_chat_30124001 = "妳喜歡玩什麼遊戲？",
  str_homestory_chat_30124002 = "一個人玩的那種……",
  str_homestory_chat_30124003 = "一個人玩的遊戲，自己和自己下棋？還是散步？",
