  str_homestory_chat_30124006 = "確實是很好的活動，據說特別能讓人靜下心來呢。",
  str_homestory_chat_30124007 = "據說？妳沒有釣過魚？",
  str_homestory_chat_30124008 = "嗯……嘗試得比較少，而且沒多少機會出去。",
