  str_homestory_chat_30124010 = "打牌？",
  str_homestory_chat_30124011 = "說到打牌，正好和我說一下，那個單人撲克牌要怎麼玩呢？",
  str_homestory_chat_30124012 = "規則……有點複雜呢，有機會再教你。",
