  str_homestory_chat_30125004 = "是的，因為我的身分……嗯……",
  str_homestory_chat_30125005 = "明白了。",
  str_homestory_chat_30125006 = "不過這裡和影鎮之類的地方，還是不太一樣吧。",
  str_homestory_chat_30125007 = "是的……沒什麼街道，也沒有商店。",
  str_homestory_chat_30125008 = "是不是……有點無聊？",
  str_homestory_chat_30125009 = "沒、沒有。",
  str_homestory_chat_30125010 = "雖然樸素了一點，但是自然風景也是很好的。",
  str_homestory_chat_30125011 = "有時候聽聽蟲鳴鳥叫，在陽光下欣賞波光粼粼的小溪……",
  str_homestory_chat_30125012 = "感覺多少有點勉強……下次請丘布們多買一點商品吧。",
  str_homestory_chat_30125013 = "祈望池、風信塔和陳列館其實也滿好玩的……",
  str_homestory_chat_30125014 = "那個……我知道了……",
  str_homestory_chat_30399999 = "要占卜嗎！",
  str_homestory_chat_30321001 = "想問一下……",
  str_homestory_chat_30321002 = "啊！終於有工作了！你要占卜什麼？",
  str_homestory_chat_30321003 = "工作。",
  str_homestory_chat_30321004 = "財運。",
  str_homestory_chat_30321005 = "戀愛。",
