  str_homestory_chat_30321009 = "其實我是想問一下妳的那個占卜，真的有用？",
  str_homestory_chat_30321010 = "你在說什麼？我可是從小就在練習的！",
  str_homestory_chat_30321011 = "那、那不就能預測未來？什麼事都占卜一下就好了？",
