  str_homestory_chat_30321015 = "原來如此。",
  str_homestory_chat_30323001 = "暫時不用……",
  str_homestory_chat_30323002 = "唉，剛剛才有了靈感，你這麼一說，又都沒了。",
  str_homestory_chat_30323003 = "啊……對不起。",
  str_homestory_chat_30323004 = "只好想想怎麼設計新的「親子裝」了。",
  str_homestory_chat_30323005 = "「親子裝」？",
  str_homestory_chat_30323006 = "就是給小蛇幽呼的啊，我們要穿著成套的衣服才好。",
  str_homestory_chat_30323007 = "牠、牠也要穿衣服？",
  str_homestory_chat_30323008 = "對啊，如果幽呼被冷到了，就會很難受的。",
  str_homestory_chat_30323009 = "穿上衣服就可以保暖，而且還能互相搭配！",
