  str_homestory_chat_30323011 = "那就要由我自己設計和製作啦！",
  str_homestory_chat_30322001 = "聽說妳喜歡故事？",
  str_homestory_chat_30322002 = "沒錯！尤其是在占卜的時候！",
  str_homestory_chat_30322003 = "占卜還要講故事？",
  str_homestory_chat_30322004 = "因為要將對方的注意力吸引住，這樣他才能全神貫注地聽我的占卜。",
