  str_homestory_chat_30322009 = "露易絲？",
  str_homestory_chat_30322010 = "對，她也是北境人，也很擅長說故事的。",
  str_homestory_chat_30322011 = "感覺妳們能去影鎮當小說家了……",
  str_homestory_chat_30324001 = "妳在找石頭？",
  str_homestory_chat_30324002 = "對的，你知道哪裡有好看的石頭嗎？",
  str_homestory_chat_30324003 = "河邊。",
  str_homestory_chat_30324004 = "樹林中。",
  str_homestory_chat_30324005 = "多謝了！",
  str_homestory_chat_30324006 = "妳尋找好看的石頭，是要用來占卜用的嗎？",
  str_homestory_chat_30324007 = "不是，是用來打扮的。",
  str_homestory_chat_30324008 = "我看到那些丘布，天天穿著白色衣服晃來晃去，覺得太單調了。",
  str_homestory_chat_30324009 = "雖然很素雅，但是讓丘布們帶上各種五彩斑斕的石頭項鍊不是很好嗎？",
  str_homestory_chat_30324010 = "等一下！妳還沒問過丘布呢！",
  str_homestory_chat_30324011 = "沒事！丘布們一定會喜歡的！",
  str_homestory_chat_30324012 = "還、還是慎重一點吧……",
  str_homestory_chat_30499999 = "又見到你啦，真是勤奮。",
  str_homestory_chat_30421001 = "嗯，正在巡視此地。",
  str_homestory_chat_30421002 = "聽說你去過很多地方，一定有哪裡適合隱居吧？",
  str_homestory_chat_30421003 = "隱居？是那種一個人就能生活的地方？",
  str_homestory_chat_30421004 = "不太準確，最好是個不引人注意，但是周圍也有鄰居的那種。",
  str_homestory_chat_30421005 = "嗯……讓我想想。",
  str_homestory_chat_30421006 = "影鎮。",
  str_homestory_chat_30421007 = "記得有句話說——「身處鬧市之中，反而不會引人注意」。",
  str_homestory_chat_30421008 = "畢竟繁華的地方，人也多，什麼人都有，不會有人注意到妳的。",
  str_homestory_chat_30421009 = "是一個可以考慮的地方。",
  str_homestory_chat_30421010 = "北境。",
  str_homestory_chat_30421011 = "世界之脊的腳下嗎……",
  str_homestory_chat_30421012 = "清冷、安靜、偏僻，是個好去處。",
  str_homestory_chat_30421013 = "可能人比較少，聽說那邊地廣人稀，而且有些封閉。",
  str_homestory_chat_30421014 = "這也是安全和隱祕的代價吧……",
  str_homestory_chat_30421015 = "紅油扳手。",
  str_homestory_chat_30421016 = "咦？那不是一群四處亂跑的傢伙嗎？",
  str_homestory_chat_30421017 = "雖然如此，但是聽說那裡有很多其他組織的傢伙。",
  str_homestory_chat_30421018 = "而且一旦加入，習慣那裡的氣氛，就感覺都是一群好夥伴。",
  str_homestory_chat_30421019 = "聽起來也不錯。",
  str_homestory_chat_30421020 = "某處小鎮。",
  str_homestory_chat_30421021 = "這樣的話，感覺隨處可見呢，作為最後的選擇吧。",
  str_homestory_chat_30421022 = "也是如此。",
  str_homestory_chat_30422001 = "妳似乎很喜歡笑。",
  str_homestory_chat_30422002 = "因為我很喜歡這裡。",
  str_homestory_chat_30422003 = "多謝妳這麼說。",
  str_homestory_chat_30422004 = "雖然景色普通……但卻給人一種很安心的感覺。",
  str_homestory_chat_30422005 = "這種感覺，在其他地方很難找到的。",
  str_homestory_chat_30422006 = "可能是因為這裡比較偏僻？",
  str_homestory_chat_30422007 = "不，應該與整體的氛圍有關，尤其是其他人的狀態。",
  str_homestory_chat_30422008 = "大家臉上的笑容，還有那些悠哉悠哉的丘布……",
  str_homestory_chat_30422009 = "悠哉悠哉……牠們又偷懶了嗎？",
  str_homestory_chat_30422010 = "你放錯重點了，孩子。",
  str_homestory_chat_30423001 = "妳起得真早。",
