  str_homestory_chat_30423005 = "沒想到妳居然會親自做這種家事。",
  str_homestory_chat_30423006 = "為什麼？是因為我過去的那個身分嗎？",
  str_homestory_chat_30423007 = "這個……",
  str_homestory_chat_30423008 = "沒事啦，我主要是喜歡為孩子們整理床鋪。",
  str_homestory_chat_30423009 = "有時候早上起來，看到她們躺在床上的樣子，就下意識去整理了。",
  str_homestory_chat_30423010 = "為此她們不得不早起，有時候也會埋怨我。",
  str_homestory_chat_30423011 = "可以理解。",
  str_homestory_chat_30423012 = "不過這也是教育的必要一環，所以不能賴床，你也是喔～",
  str_homestory_chat_30423013 = "啊？對、對。",
  str_homestory_chat_30424001 = "音樂？",
  str_homestory_chat_30424002 = "對，你喜歡聽什麼音樂呢？",
  str_homestory_chat_30424003 = "輕柔一點的。",
  str_homestory_chat_30424004 = "上次在白夜城聽到的幾首就滿不錯的。",
  str_homestory_chat_30424005 = "舒緩、優雅的感覺。",
  str_homestory_chat_30424006 = "那種輕音樂確實不錯。",
  str_homestory_chat_30424007 = "激烈一點的。",
  str_homestory_chat_30424008 = "就是那種聽起來像是噪音……",
  str_homestory_chat_30424009 = "不能那麼說，也是有旋律的。",
  str_homestory_chat_30424010 = "是嗎……",
  str_homestory_chat_30424011 = "不過，在這裡好像聽不到音樂，不會覺得寂寞嗎？",
  str_homestory_chat_30424012 = "聽聽這些自然的聲音就行，也是一種音樂。",
  str_homestory_chat_30424013 = "如果想聽那些音樂的話，還是要去專門的地方吧。",
  str_homestory_chat_30424014 = "也是，在這裡就要享受空庭的這種音樂了。",
  str_homestory_chat_30425001 = "我討厭什麼？",
  str_homestory_chat_30425002 = "一時還真想不到。妳怎麼突然想問這個問題？",
  str_homestory_chat_30425003 = "可能是前幾天下了雨，今天早上發現宿舍裡有點潮濕……",
  str_homestory_chat_30425004 = "於是就想到了在影鎮中逗留的一些日子。",
  str_homestory_chat_30425005 = "影鎮……也是趕上下雨的天氣了？",
  str_homestory_chat_30425006 = "唉，那段日子陰雨綿綿，床鋪怎麼打掃也不舒服……",
  str_homestory_chat_30425007 = "聽說影鎮確實那樣，尤其那幾個月……",
  str_homestory_chat_30425008 = "不過這種日子在空庭內不會太多的。",
  str_homestory_chat_30425009 = "所以在這裡感覺很舒服。",
  str_homestory_chat_30599999 = "在忙什麼呢？",
  str_homestory_chat_30521001 = "聽說妳要買香水？",
  str_homestory_chat_30521002 = "是的，雖然這裡空氣很清新，不過如果有香水作為點綴也很好。",
  str_homestory_chat_30521003 = "為什麼要香水點綴呢？",
  str_homestory_chat_30521004 = "主要是為那些丘布準備的，感覺牠們很適合作為引路人幫手。",
  str_homestory_chat_30521005 = "不過很多丘布看起來不容易辨認，如果有香水就好了。",
  str_homestory_chat_30521006 = "只、只是用來辨認用的嗎？香水用在這上面，是不是有點浪費？",
  str_homestory_chat_30521007 = "確實……那就用筆畫一下？像是「1號」、「2號」之類的。",
  str_homestory_chat_30521008 = "這個……還是算了吧。",
  str_homestory_chat_30522001 = "飲料店？",
  str_homestory_chat_30522002 = "這裡沒有這樣的地方呢。",
  str_homestory_chat_30522003 = "啊，不是，我是想在這裡開一家飲料店，正在調查中。",
  str_homestory_chat_30522004 = "調查什麼？",
  str_homestory_chat_30522005 = "大家的口味呀，您喜歡喝什麼飲料？",
  str_homestory_chat_30522006 = "牛奶。",
  str_homestory_chat_30522007 = "嗯……很健康的喜好。",
  str_homestory_chat_30522008 = "氣泡水。",
  str_homestory_chat_30522009 = "喔？很特別嘛。",
  str_homestory_chat_30522010 = "咖啡。",
  str_homestory_chat_30522011 = "不錯呀。",
  str_homestory_chat_30522012 = "紅茶。",
  str_homestory_chat_30522013 = "好品味！",
  str_homestory_chat_30522014 = "話說，除了我，其他人的意見也要收集吧。",
  str_homestory_chat_30522015 = "現在有多少了？",
  str_homestory_chat_30522016 = "還在一一詢問，而且還會根據早午晚來區分，每隔一段時間還要更新。",
  str_homestory_chat_30522017 = "這麼麻煩啊……",
  str_homestory_chat_30522018 = "因為要這樣才能獲得更詳細的資料，確定飲料店的招牌飲料。",
  str_homestory_chat_30522019 = "總覺得……開不起來的樣子。",
  str_homestory_chat_30523001 = "舞會？",
  str_homestory_chat_30523002 = "是的，這幾天突然有點提不起勁。",
  str_homestory_chat_30523003 = "仔細想來，感覺好久沒參加舞會了。",
  str_homestory_chat_30523004 = "可是……這裡似乎沒有那樣的地方。",
  str_homestory_chat_30523005 = "那就舉辦一次啦，只要很簡單的佈置就行了。",
  str_homestory_chat_30523006 = "像是廣場、桌椅、彩布條什麼的。",
  str_homestory_chat_30523007 = "不過請樂團可能就比較麻煩，我想或許可以請些幫手。",
  str_homestory_chat_30523008 = "例如……丘布？",
  str_homestory_chat_30523009 = "慢著，牠們不會演奏樂器啊。",
  str_homestory_chat_30523010 = "那就……從現在開始訓練吧。",
  str_homestory_chat_30523011 = "而且是魔鬼訓練，十天速成的那種。",
  str_homestory_chat_30523012 = "十、十天！",
  str_homestory_chat_30523013 = "太久了？那就三天。",
  str_homestory_chat_30523014 = "妳還是去白夜城參加舞會吧……",
  str_homestory_chat_30524001 = "引路人？",
  str_homestory_chat_30524002 = "是的，我自從來到這裡，就感覺此地好大。",
  str_homestory_chat_30524003 = "有必要安排一位引路人，免得新來的夥伴迷路。",
  str_homestory_chat_30524004 = "嗯……",
  str_homestory_chat_30524005 = "看來您同意了？",
  str_homestory_chat_30524006 = "確實，妳說得有道理。",
  str_homestory_chat_30524007 = "畢竟這裡很大，引路人作用不小。",
  str_homestory_chat_30524008 = "讓我再思考一下。",
  str_homestory_chat_30524009 = "不過，話說回來，妳有適合的人選了嗎？",
  str_homestory_chat_30524010 = "丘布！",
  str_homestory_chat_30524011 = "啊？牠們？",
  str_homestory_chat_30524012 = "牠們天天待在這裡，既熟悉又熱愛此地，再適合不過了。",
  str_homestory_chat_30524013 = "這樣……啊。我還是再考慮一下吧。",
  str_homestory_chat_30699999 = "有什麼好的計畫嗎？",
  str_homestory_chat_30621001 = "造個樂園？",
  str_homestory_chat_30621002 = "點子挺好的，但這裡太偏遠了，要怎麼吸引遊客？還是說要開發當地的遊客？",
  str_homestory_chat_30621003 = "丘布？",
  str_homestory_chat_30621004 = "沒錯！雖然他們人數不多，但考慮到未來的話……",
  str_homestory_chat_30621005 = "丘布的出生率如何？他們繁衍得快嗎？怎麼生孩子的？",
  str_homestory_chat_30621006 = "就像……光靈？",
  str_homestory_chat_30621007 = "聽你的語氣似乎不太確定啊。",
  str_homestory_chat_30621008 = "好像不能繁衍。",
  str_homestory_chat_30621009 = "真的嗎？",
  str_homestory_chat_30621010 = "真的，我沒見過他們出生，好像是從石頭縫裡蹦出來一樣。",
  str_homestory_chat_30621011 = "真是有趣的種族，看來不能掙他們的錢了。",
  str_homestory_chat_30621012 = "等一下！如果換個思路……新點子！有了！",
  str_homestory_chat_30621013 = "說來聽聽？",
  str_homestory_chat_30621014 = "少就稀有，稀有就貴，貴就有人看，看就要掏錢！",
  str_homestory_chat_30621015 = "妳難道想……",
  str_homestory_chat_30621016 = "讓他們變成大明星！在艾斯特拉大陸四處表演！",
  str_homestory_chat_30621017 = "主題就是《再現！神祕種族的世界之旅！》如何？",
  str_homestory_chat_30621018 = "妳還是趁早打消這個念頭吧。",
  str_homestory_chat_30621019 = "為什麼？",
  str_homestory_chat_30621020 = "這不就是把丘布變成展覽品了嗎……",
  str_homestory_chat_30621021 = "可以考慮。",
  str_homestory_chat_30621022 = "提議挺有趣的，「大明星丘布」，不過要先徵詢他們的意見。",
  str_homestory_chat_30621023 = "沒問題！等你的好消息。",
  str_homestory_chat_30622001 = "還是聊聊空庭吧。",
  str_homestory_chat_30622002 = "正好我想和你討論一下空庭的建設。",
  str_homestory_chat_30622003 = "關於哪方面的？",
  str_homestory_chat_30622004 = "土地開發。這裡自然氣息太濃了，不方便啊。 ",
  str_homestory_chat_30622005 = "食品街、購物街、娛樂街都沒有，客人才不會來呢。",
  str_homestory_chat_30622006 = "我也沒想要吸引客人啊……能讓夥伴們住得舒適就行了。",
