  str_homestory_chat_30622009 = "與其擔心未來，不如著眼現在！讓我來經營空庭如何？",
  str_homestory_chat_30622010 = "妳要幹什麼？",
  str_homestory_chat_30622011 = "賣給我吧，我絕對會將空庭建設成大陸第一商業區！",
  str_homestory_chat_30622012 = "還是維持現狀比較好。",
  str_homestory_chat_30623001 = "不如談談妳的頭髮。",
  str_homestory_chat_30623002 = "我的頭髮？沒什麼可聊的，普普通通。",
  str_homestory_chat_30623003 = "這髮型打理起來很麻煩吧。",
  str_homestory_chat_30623004 = "去美髮沙龍就好了，每次也就幾千白夜幣而已。",
  str_homestory_chat_30623005 = "幾千！做什麼要花那麼多！",
  str_homestory_chat_30623006 = "修剪、養護、定型之類的。說到這個我忽然想到個計畫。",
  str_homestory_chat_30623007 = "什麼？",
  str_homestory_chat_30623008 = "在這裡開一家美髮店如何？需要做頭髮的夥伴應該不少吧？",
