  str_homestory_chat_30623013 = "才8折啊……",
  str_homestory_chat_30623014 = "看來你答應了？我明天就去聯絡！",
  str_homestory_chat_30623015 = "等一下！我只是想想而已！",
  str_homestory_chat_30624001 = "聽說妳最近看上了丘布？",
  str_homestory_chat_30624002 = "沒錯，有興趣把他們轉讓給我嗎？",
  str_homestory_chat_30624003 = "他們不是商品！",
  str_homestory_chat_30624004 = "不行的！",
  str_homestory_chat_30624005 = "懂了，他們和你簽了合約了吧？那好吧，你開個價。",
  str_homestory_chat_30624006 = "有關賠償金、轉讓費、簽字費什麼的，都好談。",
