  str_homestory_chat_30624013 = "平日兩倍！假日三倍！",
  str_homestory_chat_30624014 = "等一下！他們還不一定想來呢！",
  str_homestory_chat_30625001 = "別想什麼計畫了，喝點東西吧。",
  str_homestory_chat_30625002 = "但空庭沒什麼喝的，放眼望去只有冷開水。",
