  str_homestory_chat_30625009 = "既然你推薦了，有空的話我會去調查的。",
  str_homestory_chat_30799999 = "在幹什麼呢？",
  str_homestory_chat_30721001 = "正在巡視空庭。",
  str_homestory_chat_30721002 = "老弟啊，你就不能做點有意思的事嗎？",
  str_homestory_chat_30721003 = "這就是我的樂趣，倒是你閒得發慌了吧？",
  str_homestory_chat_30721004 = "確實……空庭裡有什麼推薦的活動嗎？",
  str_homestory_chat_30721005 = "釣魚？",
  str_homestory_chat_30721006 = "太安靜了，而且釣不上來很沒面子。",
  str_homestory_chat_30721007 = "養花種草？",
  str_homestory_chat_30721008 = "這裡只有那些奇怪的大樹吧？造型太彆扭了，我不喜歡。",
  str_homestory_chat_30721009 = "去陳列館轉轉。",
  str_homestory_chat_30721010 = "沒什麼好看的……",
  str_homestory_chat_30721011 = "搞半天你什麼都不喜歡啊！那就在宿舍睡大覺吧。",
  str_homestory_chat_30721012 = "喂，老弟你先別急。我剛才的意思是想讓你休息休息。",
  str_homestory_chat_30721013 = "每次看到你不是在巡視空庭，就是在安排工作，真令人擔心……",
