  str_homestory_chat_30721015 = "沒差啦，巡視就是在休息了，你可以理解為散步。",
  str_homestory_chat_30721016 = "好吧，我明白了，請繼續。",
  str_homestory_chat_30722001 = "正在閒逛。你呢？",
