  str_homestory_chat_30722006 = "你難道有事求我？",
  str_homestory_chat_30722007 = "你不考慮約別人？",
  str_homestory_chat_30722008 = "還是說……你沒有其他人可約了？",
  str_homestory_chat_30722009 = "你小看我們之間的友誼了吧！就不能只是單純吃個飯？",
  str_homestory_chat_30722010 = "我考慮一下吧。",
  str_homestory_chat_30723001 = "正想去看看奇異樹。",
  str_homestory_chat_30723002 = "奇異樹啊……我聽說有的奇異樹香氣很迷人。",
  str_homestory_chat_30723003 = "我在考慮能不能用來做香水。",
  str_homestory_chat_30723004 = "那些樹好不容易才長大，不要隨便亂動它們。",
  str_homestory_chat_30723005 = "不光是我，丘布也會很不高興喔。",
