  str_homestory_chat_30723009 = "那又是什麼……",
  str_homestory_chat_30723010 = "奇異樹花粉與夜露的調和物，專門為她訂製，全大陸僅此一份。",
  str_homestory_chat_30723011 = "那真的會很香嗎？",
  str_homestory_chat_30723012 = "不一定，主要是讓對方感覺到特別就行。",
