  str_homestory_chat_30723014 = "好吧，看來我只能想些其他的「技巧」了。",
  str_homestory_chat_30724001 = "你找丘布們有事嗎？",
  str_homestory_chat_30724002 = "沒錯，我想和你談談他們的管理問題。",
  str_homestory_chat_30724003 = "出了什麼事了？",
  str_homestory_chat_30724004 = "丘布擔任空庭的管理人員實在太缺乏個人魅力。",
  str_homestory_chat_30724005 = "能讓空庭良好運作，並且服務大家就行了吧？",
