  str_homestory_chat_30724010 = "大家來這裡也只是為了放鬆，丘布只要維持日常運作就行了。",
  str_homestory_chat_30724011 = "這樣的經營目標啊……懂了。",
  str_homestory_chat_30725001 = "聽說你找我？",
  str_homestory_chat_30725002 = "我主要是想在這裡買塊地。",
  str_homestory_chat_30725003 = "不會是有人要蓋什麼度假村然後又請你當主管吧？",
