  str_homestory_chat_30725005 = "那還早吧。",
  str_homestory_chat_30725006 = "也只是個突發的想法，畢竟這裡環境確實不錯，隱祕、幽靜……",
  str_homestory_chat_30725007 = "希望我能有退休到這裡養老的那一天吧。",
  str_homestory_chat_30899999 = "我在這裡～",
  str_homestory_chat_30801001 = "嗨！叭噗。",
  str_homestory_chat_30801002 = "你居然看到我了！",
  str_homestory_chat_30801003 = "因為妳對我打招呼啊。",
  str_homestory_chat_30801004 = "紅油扳手的夥伴總是無視我，我打招呼時經常得不到回應。",
  str_homestory_chat_30801005 = "居然會如此！妳試過多多表現自己嗎？比如說出出主意之類的？",
  str_homestory_chat_30801006 = "所以我當了軍師啊！但似乎只有大蜥蜴願意聽我的計畫……",
  str_homestory_chat_30801007 = "什麼時候醒山老大能採納幾句就好了。",
  str_homestory_chat_30801008 = "總會有那麼一天的，加油叭噗！",
  str_homestory_chat_30821001 = "最近在做什麼啊？",
  str_homestory_chat_30821002 = "我在想等等要吃什麼東西，肚子有點餓了。",
  str_homestory_chat_30821003 = "空庭距離紅油沙漠有點遠，或許沒有我喜歡吃的。",
  str_homestory_chat_30821004 = "紅油沙漠的食物……蜥蜴乾、仙人掌嗎？",
  str_homestory_chat_30821005 = "並不是只有那些啦。在這空庭裡有什麼吃的嗎？",
  str_homestory_chat_30821006 = "麵包。",
  str_homestory_chat_30821007 = "很普通的食物，就直接吃嗎？不配醬料？",
