  str_homestory_chat_30821013 = "如果配菜好吃的話，很適合填飽肚子。",
  str_homestory_chat_30821014 = "水果派。",
  str_homestory_chat_30821015 = "你居然喜歡甜食，看不出來呀。",
  str_homestory_chat_30821016 = "看來叭噗對這些食物沒什麼興趣啊。",
  str_homestory_chat_30821017 = "是啊，一說到吃的就開始想念紅油沙漠了。",
  str_homestory_chat_30821018 = "雖然風沙大，但那些食物很好吃……",
  str_homestory_chat_30821019 = "蜥蜴味的冰淇淋和泡芙，紅油炸蚯蚓什麼的。",
