  str_homestory_chat_32024007 = "那可不是我們普通人碰得起的啊，空裔。",
  str_homestory_chat_32024008 = "「普通人」？",
  str_homestory_chat_32024009 = "有生之年，我竟然聽到妳以「普通人」自稱……",
  str_homestory_chat_32024010 = "還屈尊與我並列……",
  str_homestory_chat_32024011 = "多謝啦，龍洲大陸！",
  str_homestory_chat_32024012 = "這麼貴？",
  str_homestory_chat_32024013 = "龍洲的家具竟然這麼貴……我都不知道。",
  str_homestory_chat_32024014 = "失敬了，龍洲大陸！",
  str_homestory_chat_32024015 = "……可惡，我對龍洲家具的渴望又被勾起來了。",
  str_homestory_chat_32024016 = "你給我負起責任！",
  str_homestory_chat_32024017 = "我可沒錢啊！",
  str_homestory_chat_32025001 = "空裔風格。",
  str_homestory_chat_32025002 = "真是出乎我意料的回答，你竟然推薦了自己。",
  str_homestory_chat_32025003 = "不是，我推薦的是空裔的裝潢風格……",
  str_homestory_chat_32025004 = "你要親自來替我裝修嗎？",
  str_homestory_chat_32025005 = "怎麼會解讀成這種意思啊？！",
  str_homestory_chat_32025006 = "畢竟，當今世界——",
  str_homestory_chat_32025007 = "熟悉空裔風格的人就只有你了。",
  str_homestory_chat_32025008 = "也、也不能這麼說吧！",
  str_homestory_chat_32025009 = "像啟光、白夜城之類的地方，絕對有很多歷史學家、考古學家……",
  str_homestory_chat_32025010 = "對空裔的風格研究很深。",
  str_homestory_chat_32025011 = "但我放著你不找，偏要去找他們的理由……",
  str_homestory_chat_32025012 = "你能想出哪怕一個嗎？",
  str_homestory_chat_32025013 = "……想不出。",
  str_homestory_chat_32025014 = "非找我不可的理由，我倒能想到好幾個。",
  str_homestory_chat_32025015 = "比如我更便宜啦、我更便宜啦、我更便宜啦……",
  str_homestory_chat_32025016 = "哈哈哈，倒也不必這樣妄自菲薄。",
  str_homestory_chat_32025017 = "我相信你能設計出賞心悅目的房間。",
  str_homestory_chat_32025018 = "而且，跟你說話很開心。",
  str_homestory_chat_32025019 = "僅此而已。",
  str_homestory_chat_32199999 = "想許什麼願望？",
  str_homestory_chat_32121001 = "世界和平",
  str_homestory_chat_32121002 = "哇，會許下這樣無私心願的人——",
  str_homestory_chat_32121003 = "要麼沒把願望當回事……",
  str_homestory_chat_32121004 = "要麼就是所圖甚大。",
  str_homestory_chat_32121005 = "小PlayerName是哪一種呢？",
  str_homestory_chat_32121006 = "沒當回事",
  str_homestory_chat_32121007 = "哈哈，果然是你的風格。",
  str_homestory_chat_32121008 = "從不將未來寄望在祈願上。想要什麼，就著手去實現……",
  str_homestory_chat_32121009 = "所圖甚大",
  str_homestory_chat_32121010 = "也就是說，「世界和平」是個真實的目標囉。",
  str_homestory_chat_32121011 = "你會非常認真地去考慮，如何一步步往目標邁進……",
  str_homestory_chat_32121012 = "活了數千年，你這樣的人讓阿霓最頭痛。",
  str_homestory_chat_32121013 = "咦，為什麼？",
  str_homestory_chat_32121014 = "因為改變世界的，往往就是這類人呀。",
  str_homestory_chat_32122001 = "親人朋友都平平安安",
  str_homestory_chat_32122002 = "這樣的心願，阿霓在廟中也時常聽到。",
  str_homestory_chat_32122003 = "阿霓時常想，如此許願的人，究竟是幸福還是不幸呢？",
  str_homestory_chat_32122004 = "當然是幸福啦！",
  str_homestory_chat_32122005 = "這表示他的朋友都在身邊，帶給他許多歡樂……",
  str_homestory_chat_32122006 = "怎麼會是不幸呢？",
  str_homestory_chat_32122007 = "因為歡樂往往是易逝的。",
  str_homestory_chat_32122008 = "......！",
  str_homestory_chat_32122009 = "許願之人也是明白這一點，才會來許願，不是嗎？",
  str_homestory_chat_32122010 = "……妳說得沒錯。",
  str_homestory_chat_32122011 = "在這暗鬼橫行的世界，每一個人都可能遭遇不測。",
  str_homestory_chat_32122012 = "我也想盡我所能，保護我的朋友。",
  str_homestory_chat_32122013 = "哪怕是「許願」這樣微不足道的小事。",
  str_homestory_chat_32122014 = "呵，天行無常，人子卻總能從無常中尋獲力量。",
  str_homestory_chat_32122015 = "正因如此，凡人才可敬可畏啊。",
  str_homestory_chat_32123001 = "踏遍世界的每一個角落",
  str_homestory_chat_32123002 = "喔？小PlayerName許了個很新奇的願望呢。",
  str_homestory_chat_32123003 = "若想遊歷世界，去便是了，何必特意許願？",
