  str_homestory_chat_32123005 = "沒有資金",
  str_homestory_chat_32123006 = "「亦有愛閒人，又為窮餓逼。」",
  str_homestory_chat_32123007 = "小事一樁！阿霓身上這些首飾，你拿去典當吧。",
