  str_homestory_chat_32123009 = "「熊羆對我蹲，虎豹夾路啼。」",
  str_homestory_chat_32123010 = "有阿霓陪著你，猛獸、暗鬼又何足道哉？",
  str_homestory_chat_32123011 = "說來，小PlayerName也懂阿霓唸的詩？",
  str_homestory_chat_32123012 = "在龍洲旅行時，這些詩很常見嘛。",
  str_homestory_chat_32123013 = "經常聽一聽，看一看，總能懂的。",
