  str_homestory_chat_32123017 = "我也會以遊歷世界為目標，努力成長的！",
  str_homestory_chat_32123018 = "甚善，甚善，阿霓等著你。",
  str_homestory_chat_32124001 = "窩在巨像家裡蹲",
