  str_homestory_chat_32821008 = "無需那種世俗之物。當真理指引的契機到來，你我自然會攜手合作。",
  str_homestory_chat_32821009 = "反之強求也不會有好結果。",
  str_homestory_chat_32821010 = "這工作感覺不太穩定啊……",
  str_homestory_chat_32821011 = "不是在畫餅吧？",
  str_homestory_chat_32821012 = "您竟會有這種想法，真令我大吃一驚。",
  str_homestory_chat_32821013 = "在您看來，真理結社是信口開河、唬弄信眾的可疑團體嗎？",
  str_homestory_chat_32821014 = "絕無此意！只是我最近見了太多無良老闆。",
  str_homestory_chat_32822001 = "隱身衣",
  str_homestory_chat_32822002 = "噢？",
  str_homestory_chat_32822003 = "為什麼……露出那樣的眼神？",
  str_homestory_chat_32822004 = "呵呵……",
  str_homestory_chat_32822005 = "為什麼還笑了起來？！",
  str_homestory_chat_32822006 = "不必感到羞恥，導航員。在您這個年紀，有這一類的想法是很自然的。",
  str_homestory_chat_32822007 = "什麼想法啊！我只是覺得，有了隱身衣，祕密潛入時會很方便！",
  str_homestory_chat_32822008 = "當然，當然，否則您也不會想要它了。",
  str_homestory_chat_32822009 = "妳究竟誤會了些什麼啊啊啊——！",
  str_homestory_chat_32823001 = "自動除塵的掃帚",
  str_homestory_chat_32823002 = "哎呀，都是魔法物品了，卻只想要掃帚嗎？您的慾望相當淡薄呢。",
  str_homestory_chat_32823003 = "不想自己動手打掃的話，僱傭人就可以了吧？",
  str_homestory_chat_32823004 = "像妳這樣身居高位的人可能難以理解吧。",
  str_homestory_chat_32823005 = "對一個活人發號施令，哪怕是我花錢僱來的，還是會有點不自在。",
  str_homestory_chat_32823006 = "但如果是魔法掃帚，就可以隨便使喚了！",
  str_homestory_chat_32823007 = "原來如此，您是非常溫柔的人啊。",
  str_homestory_chat_32823008 = "不過，太過壓抑自我而顧慮他人，反而會使您遠離真知喔。",
  str_homestory_chat_32823009 = "顧慮他人是自我的一部分",
  str_homestory_chat_32823010 = "反駁得好，您的智慧與覺悟非同凡響。",
  str_homestory_chat_32823011 = "的確，您若能將溫柔的性情發揚到極致……",
  str_homestory_chat_32823012 = "一定能成為充滿犧牲精神的聖徒，猶如聖釘一般。",
  str_homestory_chat_32823013 = "那、那還是不用了，我普普通通的就好！",
  str_homestory_chat_32823014 = "只有自大狂才能接近真理？",
  str_homestory_chat_32823015 = "呵呵……您言辭帶刺，真是相當可愛。",
  str_homestory_chat_32823016 = "是的，以結果而論，得窺真理的人，往往都是些自大狂。",
  str_homestory_chat_32823017 = "而您性情中宛如帶刺玫瑰的一面，正是真理在您身上的顯現，也未可知。",
  str_homestory_chat_32823018 = "這位「真理大人」是不是不太好相處啊？",
  str_homestory_chat_32824001 = "逆轉時間的沙漏",
  str_homestory_chat_32824002 = "逆轉時間嗎？很經典的選擇。",
  str_homestory_chat_32824003 = "恕我冒昧，您是想回到十七年前，改變空谷的歷史嗎？",
  str_homestory_chat_32824004 = "當然",
  str_homestory_chat_32824005 = "對您來說，這是極為自然的想法。",
  str_homestory_chat_32824006 = "若您真有實現的機會，或許……我會與您站在一起。",
  str_homestory_chat_32824007 = "什麼？我以為這麼大的歷史變動，大家都會反對的。",
  str_homestory_chat_32824008 = "不敢改變那麼大",
  str_homestory_chat_32824009 = "整個艾斯特拉都會受影響的吧。",
  str_homestory_chat_32824010 = "最多也就是回到前天把掉的錢撿回來之類的，哈哈。",
  str_homestory_chat_32824011 = "時間的構造非常玄妙。",
  str_homestory_chat_32824012 = "過往的形成，也遠比常人想像的複雜。",
  str_homestory_chat_32824013 = "有時候，也許是未來造就了過往。",
  str_homestory_chat_32824014 = "……",
  str_homestory_chat_32825001 = "能讓人一邊睡覺一邊用功的藥水",
  str_homestory_chat_32825002 = "……",
  str_homestory_chat_32825003 = "從、從妳的眼神中，我感受到深深的譴責……",
  str_homestory_chat_32825004 = "呵呵，您是個聰明人，真是太好了。",
  str_homestory_chat_32825005 = "世上有許多以「魔法」為題材的幻想小說。",
  str_homestory_chat_32825006 = "但就連它們都很少描繪您夢想中的藥水。您可知道為什麼？",
  str_homestory_chat_32825007 = "作者不夠大膽？",
  str_homestory_chat_32825008 = "因為知識是通往真理的唯一門徑。",
  str_homestory_chat_32825009 = "唯有用功唸書不可糊弄。",
  str_homestory_chat_32825010 = "您瞭解了嗎？",
  str_homestory_chat_32825011 = "完全瞭解了，維多利亞老師！",
  str_homestory_chat_32999999 = "您曾經為了什麼事懺悔過？",
  str_homestory_chat_32921001 = "沉迷遊戲三天沒睡",
  str_homestory_chat_32921002 = "遊戲？那是什麼？",
  str_homestory_chat_32921003 = "是魔鬼。",
  str_homestory_chat_32921004 = "魔鬼……！是像暗鬼、死徒一樣卑劣的怪物嗎？",
  str_homestory_chat_32921005 = "我會保護您的，PlayerName，主正是為此賜予我「聖血」的力量。",
  str_homestory_chat_32921006 = "「聖血」對此無能為力",
  str_homestory_chat_32921007 = "名為遊戲的魔鬼會以快樂作為誘餌，毀我青春、葬我錢財。",
  str_homestory_chat_32921008 = "再強大的戰士也逃不出遊戲的魔爪！",
  str_homestory_chat_32921009 = "但這樣聽起來，好像只是您不做抵抗，任其誘惑。",
  str_homestory_chat_32921010 = "務必保護我",
  str_homestory_chat_32921011 = "下次貢露再拿遊戲來引誘我，你就擋在我前面！",
  str_homestory_chat_32921012 = "貢露……？",
  str_homestory_chat_32921013 = "她是地獄中掌管遊戲的魔王。若不是她，我也不會淪落到今天……",
  str_homestory_chat_32921014 = "您這不是……把責任推卸給別人嗎？",
  str_homestory_chat_32921015 = "您真正該懺悔的，是不是這件事呢？",
  str_homestory_chat_32921016 = "唔咕……！這個話題就談到這裡，晚點聊！",
  str_homestory_chat_32922001 = "在餐廳堆水果塔",
  str_homestory_chat_32922002 = "水果塔？",
  str_homestory_chat_32922003 = "咳，不是有那種餐廳嗎？只要點了主食，水果沙拉可以自助。",
  str_homestory_chat_32922004 = "拿多少都可以，但只能拿一次。",
  str_homestory_chat_32922005 = "怎樣在這一盤裡裝下越多越好的沙拉，就成了一門學問。",
  str_homestory_chat_32922006 = "於是，您在盤子上，用水果蓋了一座……塔？",
  str_homestory_chat_32922007 = "別、別用那種悲哀的眼神看著我嘛。",
  str_homestory_chat_32922008 = "這可是需要非常高超的技巧呢！！",
  str_homestory_chat_32922009 = "既然您如此自豪，為什麼又懺悔了呢？",
  str_homestory_chat_32922010 = "我吃光整座塔，回去拉了三天肚子……",
  str_homestory_chat_32922011 = "那您已接受了主的懲罰，洗淨罪孽了，PlayerName。",
  str_homestory_chat_32922012 = "你的眼神又變得這麼溫暖，我感覺更怪了。",
  str_homestory_chat_32923001 = "超速駕駛",
  str_homestory_chat_32923002 = "超速……原來巨像還有速限？",
  str_homestory_chat_32923003 = "現在的天空雖然任我馳騁……",
  str_homestory_chat_32923004 = "但據說在天上還有許多巨像的年代，確實有約定俗成的速限。",
  str_homestory_chat_32923005 = "這是為了其他巨像和鳥類的安全考量，我通常都會遵守。",
  str_homestory_chat_32923006 = "那超速又是為了什麼呢？",
  str_homestory_chat_32923007 = "薇絲生日",
  str_homestory_chat_32923008 = "我趕去影鎮，搶一天限定五十個的超豪華水果蛋糕。",
  str_homestory_chat_32923009 = "卡蓮生日",
  str_homestory_chat_32923010 = "我極限趕往白夜城參加生日宴，中間還得去乾洗店拿我的晚禮服。",
  str_homestory_chat_32923011 = "這樣啊。",
  str_homestory_chat_32923012 = "既然事關那位小姐，那就怪不了您了。",
  str_homestory_chat_32923013 = "而且，您有好好懺悔過了吧？",
  str_homestory_chat_32923014 = "當、當然了！",
  str_homestory_chat_32923015 = "儘管無人約束，您仍會遵守一族的習俗，還會為破壞它而懺悔。",
  str_homestory_chat_32923016 = "您高潔的品性令我欽佩。",
  str_homestory_chat_32923017 = "真理之主會庇佑您的，PlayerName。",
  str_homestory_chat_32923018 = "謝謝你……不是，謝謝祂！",
  str_homestory_chat_32924001 = "三分鐘熱度",
  str_homestory_chat_32924002 = "做事難以持之以恆嗎？",
  str_homestory_chat_32924003 = "對，尤其是每次下定決心要運動。",
  str_homestory_chat_32924004 = "鍛鍊身體是一件苦痛的事。我也經歷過，可以理解您。",
  str_homestory_chat_32924005 = "其實您不必勉強，您的強大本來就不在肉體方面。",
  str_homestory_chat_32924006 = "運動不適合您，但您一定有能持之以恆的事，對吧？",
  str_homestory_chat_32924007 = "算是……有吧？",
  str_homestory_chat_32924008 = "例如說呢？",
  str_homestory_chat_32924009 = "吃飯、睡覺……？",
  str_homestory_chat_32924010 = "……",
  str_homestory_chat_32924011 = "還、還有其他的！像是……",
  str_homestory_chat_32924012 = "呼、呼吸……？",
  str_homestory_chat_32924013 = "…………",
  str_homestory_chat_33099999 = "你喜歡讀哪一類的書？",
  str_homestory_chat_33021001 = "小說",
  str_homestory_chat_33021002 = "有趣。",
  str_homestory_chat_33021003 = "你知道嗎？你們稱之為「小說」的東西，其實歷史非常短暫。",
  str_homestory_chat_33021004 = "在我那個年代才剛剛開始發展。",
  str_homestory_chat_33021005 = "第一次聽說！",
  str_homestory_chat_33021006 = "我以為小說是一直都有的？",
  str_homestory_chat_33021007 = "這是常見的認知偏差。將人文、社會方面的新概念誤認為自古就有。",
  str_homestory_chat_33021008 = "不僅小說，童年、愛情、理性等概念，都是近代才出現的產物。",
  str_homestory_chat_33021009 = "你們一旦習慣，便難以想像「並非如此」的生活……",
  str_homestory_chat_33021010 = "「古已有之」的誤解因此而生。",
  str_homestory_chat_33021011 = "有點難以置信",
  str_homestory_chat_33021012 = "以前的光靈沒有故事看嗎？",
  str_homestory_chat_33021013 = "從前我們有史詩、戲劇、寓言。具有故事的元素，但都與小說相去甚遠。",
  str_homestory_chat_33021014 = "我最近也讀了一些書店陳列的熱銷小說。與史詩之類相比……",
  str_homestory_chat_33021015 = "情節更複雜，情感更細膩，無疑是社會富足後的產物。",
  str_homestory_chat_33021016 = "一百年前的光靈，可無暇思考這麼多「無用」的東西。",
  str_homestory_chat_33021017 = "原來如此……與您聊天真是增長見識！",
  str_homestory_chat_33022001 = "歷史書",
  str_homestory_chat_33022002 = "你這個年齡會對歷史感興趣，倒是罕見。",
  str_homestory_chat_33022003 = "讀點歷史是好事，但也要留心，不要認為一本書上記載的便是所有真相。",
  str_homestory_chat_33022004 = "我明白，威廉先生，您是想說「歷史是勝利者書寫的」吧？",
  str_homestory_chat_33022005 = "這句話僅僅反映了當權者刻意扭曲歷史的情況。實際情況還要複雜得多。",
  str_homestory_chat_33022006 = "歷史學家在書寫歷史時，即使百分之百懷著「還原真相」的善意……",
  str_homestory_chat_33022007 = "也會受到他們實際生活的時代風貌所的影響。",
  str_homestory_chat_33022008 = "他們寫下的是「當代人看到的歷史」，而非「歷史」本身。",
  str_homestory_chat_33022009 = "您是說……歷史無法準確還原嗎？",
  str_homestory_chat_33022010 = "不愧是讀過歷史的年輕人。你發現了所謂「歷史與真相」的吊詭之處。",
  str_homestory_chat_33023001 = "詩歌",
  str_homestory_chat_33023002 = "哼，有時覺得你太過少年老成，原來也有些年輕人的喜好。",
  str_homestory_chat_33023003 = "有句話說「夭折在青春未逝時是詩人的幸運」，你怎麼看？",
  str_homestory_chat_33023004 = "同意",
  str_homestory_chat_33023005 = "你的想法很危險。",
  str_homestory_chat_33023006 = "寫詩需要青春的激情，與其等激情消退後詩情枯竭，不如提早死去。",
  str_homestory_chat_33023007 = "無法燃燒的生命不值得活，你是這麼看的嗎？",
  str_homestory_chat_33023008 = "我當然不這麼看。但對詩人來說，又是怎樣呢？",
  str_homestory_chat_33023009 = "總有人會將某個事物視作生命的全部吧？",
  str_homestory_chat_33023010 = "生命的全部嗎……對我來說，或許就是接近主的路途吧。",
  str_homestory_chat_33023011 = "你很有洞察力，PlayerName。",
  str_homestory_chat_33023012 = "不同意",
  str_homestory_chat_33023013 = "你難道是「天賦論」的批判者？",
  str_homestory_chat_33023014 = "怎麼說？",
  str_homestory_chat_33023015 = "所有文學體裁裡，再沒有比詩歌更需要天賦，更燃燒天賦的了。",
  str_homestory_chat_33023016 = "許多大詩人都在十幾二十歲時橫空出世，猛烈燃燒，隨後便化作灰燼，寂寂沉默。",
  str_homestory_chat_33023017 = "而你不認同這樣的命運。",
  str_homestory_chat_33023018 = "只要活著，便能用閱盡人世的靈魂追上神明賜予的詩情。",
  str_homestory_chat_33023019 = "你是這樣想的嗎？",
  str_homestory_chat_33023020 = "也許吧。我覺得用什麼「青春」去限制人生，非常不甘心。",
  str_homestory_chat_33023021 = "仔細想想，就是您說的意思。",
  str_homestory_chat_33023022 = "但我下輩子也沒法表達得像您這麼好！您太厲害了，威廉先生！",
  str_homestory_chat_33024001 = "科普讀物",
  str_homestory_chat_33024002 = "「科學」嗎？在造福民眾方面，科學無疑發揮了巨大的作用。",
  str_homestory_chat_33024003 = "但在目前的科學體系下，光靈無疑是離真理愈發遙遠了。",
  str_homestory_chat_33024004 = "咦，怎麼說？",
  str_homestory_chat_33024005 = "維多利亞是否和你說過一句話：「真理是多維度的」？",
  str_homestory_chat_33024006 = "她常常提！",
  str_homestory_chat_33024007 = "奧祕就在這裡。",
  str_homestory_chat_33024008 = "科學建立在可預測的基礎上。",
  str_homestory_chat_33024009 = "重複一萬次，每次都得出一樣的結果，才可稱之為「科學結論」。",
  str_homestory_chat_33024010 = "而真理存在於萬中無一的火花中。",
  str_homestory_chat_33024011 = "你窺見它只需一瞥。而這一瞥，你千萬次去看，又是千萬種不同。",
  str_homestory_chat_33024012 = "你聽得懂嗎？",
  str_homestory_chat_33024013 = "懂了",
  str_homestory_chat_33024014 = "胡說。我這麼隨口一說你就懂，還要真理結社幹什麼？",
  str_homestory_chat_33024015 = "……",
  str_homestory_chat_33024016 = "不懂",
  str_homestory_chat_33024017 = "沒關係。你喜歡科學，多學學也無妨。",
  str_homestory_chat_33024018 = "當科學發展到極致時，或許能成為又一扇通往真理的門徑。",
  str_homestory_chat_33025001 = "神學典籍",
  str_homestory_chat_33025002 = "？？？",
  str_homestory_chat_33025003 = "……喔，我明白了。",
  str_homestory_chat_33025004 = "你最近是不是在讀……叫什麼？「奇幻小說」？而且是有神話原型的那一種。",
  str_homestory_chat_33025005 = "因此對其中的概念、世界觀產生了興趣，對吧？",
  str_homestory_chat_33025006 = "咦？不是的，威廉先生。",
  str_homestory_chat_33025007 = "我是聽您常提起「真理」、「神明」什麼的，想要更瞭解您說的話題。",
  str_homestory_chat_33025008 = "？！",
  str_homestory_chat_33025009 = "為了……我？",
