  str_homestory_chat_33025013 = "您怎麼了？",
  str_homestory_chat_33025014 = "沒有！去讀書吧，快去。",
  str_homestory_chat_33025015 = "若有不懂的……可以問我。",
  str_homestory_chat_33199999 = "你最近有夢見什麼有趣的東西嗎？",
  str_homestory_chat_33121001 = "有趣的夢？",
  str_homestory_chat_33121002 = "沒有耶……",
  str_homestory_chat_33121003 = "咦，會不會是壓力太大了？",
  str_homestory_chat_33121004 = "沒有美夢的話，睡覺不會很累嗎？",
