  str_homestory_chat_33121006 = "只要睡得香，本身就能紓解壓力了。",
  str_homestory_chat_33121007 = "原來如此。",
  str_homestory_chat_33121008 = "有啊。",
  str_homestory_chat_33121009 = "喔，看來PlayerName果然是很樂觀的人！",
  str_homestory_chat_33121010 = "嗯？樂不樂觀從做夢就能看出來嗎？",
  str_homestory_chat_33121011 = "對啊，開心地生活，樂觀地對待別人……",
  str_homestory_chat_33121012 = "夢裡大家就會陪你一起創造許多美好的事情！",
  str_homestory_chat_33121013 = "不過，嘿嘿，也有更簡單的方法。",
  str_homestory_chat_33121014 = "你要是想做美夢，隨時都可以來找摩耶喔！",
  str_homestory_chat_33121015 = "好，沒問題！",
