  str_homestory_chat_33122003 = "那就是……沒有雜色的泡泡呢！",
  str_homestory_chat_33122004 = "那一定會是最美麗無瑕的泡泡！",
  str_homestory_chat_33122005 = "你在那個世界做了什麼呢？",
  str_homestory_chat_33122006 = "和大家一起環遊世界。",
  str_homestory_chat_33122007 = "哇，聽起來超棒的！",
  str_homestory_chat_33122008 = "大家一起在巨像上感受風，欣賞新生的世界……",
  str_homestory_chat_33122009 = "和大家一起重建家園。",
  str_homestory_chat_33122010 = "不愧是你，在夢裡也這麼友善無私！",
  str_homestory_chat_33122011 = "讓泡泡重新恢復色彩，的確是一件很重要的事情。",
  str_homestory_chat_33122012 = "那下次PlayerName能帶我一起體驗這樣美妙的夢嗎？",
  str_homestory_chat_33122013 = "可以是可以，只是不知道下次什麼時候才能再夢到了。",
  str_homestory_chat_33123001 = "龍洲。",
  str_homestory_chat_33123002 = "龍洲啊？摩耶在童話書裡讀過。",
  str_homestory_chat_33123003 = "那邊的童話都滿深奧的。",
  str_homestory_chat_33123004 = "而且咬文嚼字的，摩耶看不太懂。",
  str_homestory_chat_33123005 = "龍洲的文化的確博大精深。",
  str_homestory_chat_33123006 = "無論是機巧、曆法還是光靈，都很有意思。",
  str_homestory_chat_33123007 = "真的嗎？摩耶還沒有見過龍洲的光靈。",
  str_homestory_chat_33123008 = "今晚做夢的時候，就請先祖大人帶我飛過去看看吧！",
  str_homestory_chat_33123009 = "這、這樣也行嗎？",
  str_homestory_chat_33123010 = "下次介紹龍洲的光靈給妳認識！",
  str_homestory_chat_33123011 = "好呀！你果然和先祖大人一樣，都對摩耶好好喔！",
