  str_homestory_chat_33124002 = "嗯，表演嗎？",
  str_homestory_chat_33124003 = "摩耶以前在馬戲團的時候也看過很多表演～",
  str_homestory_chat_33124004 = "雖然大多數的表演都記不太得了。",
  str_homestory_chat_33124005 = "但是大家都很厲害這點，摩耶記得很清楚！",
