  str_homestory_chat_33125001 = "空谷。",
  str_homestory_chat_33125002 = "空谷……是你的家鄉，對嗎？",
  str_homestory_chat_33125003 = "摩耶出生在船上，對家鄉沒什麼印象。",
  str_homestory_chat_33125004 = "PlayerName很喜歡空谷嗎？",
  str_homestory_chat_33125005 = "嗯，畢竟那是我們世代生活的地方。",
  str_homestory_chat_33125006 = "不過我在地下待了足足十七年。",
  str_homestory_chat_33125007 = "關於先祖的事情，我還有很多沒搞清楚。",
  str_homestory_chat_33125008 = "這也是我一直在大陸遊歷的目的之一。",
  str_homestory_chat_33125009 = "哇，空裔也很想瞭解自己的先祖大人嗎？",
  str_homestory_chat_33125010 = "我們兩個果然有很多共通點，對吧？",
