  str_homestory_chat_33125013 = "哈哈，真是有趣的想法。",
  str_homestory_chat_33125014 = "嘿嘿，所以我們現在成了好朋友，先祖大人們一定也很開心！",
  str_homestory_chat_33299999 = "你有什麼想守護的東西嗎？",
  str_homestory_chat_33221001 = "想守護的東西啊？",
  str_homestory_chat_33221002 = "有很多呢。",
  str_homestory_chat_33221003 = "可以說說看嗎？",
  str_homestory_chat_33221004 = "唔……總覺得很難形容。",
  str_homestory_chat_33221005 = "守護是指怎樣的守護呢？",
  str_homestory_chat_33221006 = "大到理想、信念這種宏觀的事物。",
  str_homestory_chat_33221007 = "小到一些具體而細微的事物。",
  str_homestory_chat_33221008 = "可以舉一點確切例子嗎？",
  str_homestory_chat_33221009 = "比如……",
