  str_homestory_chat_33221011 = "這麼說的話，我現在就有必須守護的東西！",
  str_homestory_chat_33221012 = "為了守護今天的晚餐，必須阻止薇絲開發新菜色！",
  str_homestory_chat_33222001 = "巨像。",
  str_homestory_chat_33222002 = "原來如此。",
  str_homestory_chat_33222003 = "你們的夥伴接受了放棄戰爭，與你們相伴數千年。",
  str_homestory_chat_33222004 = "甚至，還能產生共鳴的奇蹟。",
  str_homestory_chat_33222005 = "我在打開家傳至寶時也曾受過那樣的震撼。我理解了。",
  str_homestory_chat_33222006 = "這麼說來，我們也算有著相似的命運。",
  str_homestory_chat_33222007 = "的確，甚至我們的先祖在很久之前就相遇了。",
