  str_homestory_chat_33222010 = "我們一定能守護好巨像！",
  str_homestory_chat_33223001 = "先祖的榮耀。",
  str_homestory_chat_33223002 = "我能理解。",
  str_homestory_chat_33223003 = "畢竟我也是遵循著先祖的意志，才一直走到這裡。",
  str_homestory_chat_33223004 = "雖然過程曲折，也產生過迷茫……",
  str_homestory_chat_33223005 = "不過我已經達成了夙願。那麼你的守護之路，又走到哪裡了呢？",
