  str_homestory_chat_33223007 = "這樣啊，恭喜你。",
  str_homestory_chat_33223008 = "還在繼續努力呢。",
  str_homestory_chat_33223009 = "嗯，我會注視著你的努力喔。",
  str_homestory_chat_33223010 = "今後如果需要幫忙，儘管和我說。",
