  str_homestory_chat_33224003 = "你也想成為正義的夥伴嗎？",
  str_homestory_chat_33224004 = "早就是了！",
  str_homestory_chat_33224005 = "的確，在和你相處的過程中，我確實深深感受到你的正義。",
  str_homestory_chat_33224006 = "我想，你一定就是最適合的人選。",
  str_homestory_chat_33224007 = "當然想啦！",
  str_homestory_chat_33224008 = "是嗎？你有這份決心和信念，很了不起。",
  str_homestory_chat_33224009 = "但這畢竟不是一份輕鬆的工作。",
  str_homestory_chat_33224010 = "你願意來當我的助手嗎？",
