  str_homestory_chat_33225011 = "所以要說當下的話……",
  str_homestory_chat_33225012 = "和妳的友誼！",
  str_homestory_chat_33225013 = "抱歉，我剛才好像沒有提到你。",
  str_homestory_chat_33225014 = "畢竟你在我身邊，對我來說是習以為常的事情了。",
