  str_homestory_chat_33399999 = "如果有一天醒來，世界上只剩下你一個人，你會做什麼？",
  str_homestory_chat_33321001 = "倒下去繼續睡",
  str_homestory_chat_33321002 = "我一定是在做夢。",
