  str_homestory_chat_33321010 = "嗯，乍一想很多，仔細一想好像也沒有呢。",
  str_homestory_chat_33321011 = "我本來想做什麼就去做了，規則阻止不了我。",
  str_homestory_chat_33321012 = "根本就沒有「平常不能做的事」嘛！",
  str_homestory_chat_33321013 = "真是個危險的傢伙……",
