  str_homestory_chat_33324003 = "咳，不瞞妳說，我想這麼做很久了。",
  str_homestory_chat_33324004 = "但畢竟會擔心……對吧？",
  str_homestory_chat_33324005 = "不會啊，我經常去。",
  str_homestory_chat_33324006 = "什麼？！妳就不擔心——",
  str_homestory_chat_33324007 = "有人來？",
  str_homestory_chat_33324008 = "有佩蒂在啊。而且，誰會沒事盯著別人洗澡？",
  str_homestory_chat_33324009 = "再說了，人人的身體不是大同小異，有什麼好忌諱的？",
  str_homestory_chat_33324010 = "不、不對，不要想坑我現在就去河裡洗澡！",
