  str_homestory_chat_33324012 = "我去河裡洗澡時，早就都滾得滿身泥了。",
  str_homestory_chat_33324013 = "別說食人魚，鯊魚都要被我毒暈。",
  str_homestory_chat_33324014 = "好壯觀……不，我不是想看的意思！",
  str_homestory_chat_33325001 = "坐在白夜城城主的寶座上",
  str_homestory_chat_33325002 = "還要蹺二郎腿！",
  str_homestory_chat_33325003 = "哎，沒創意，我早就坐過了。",
  str_homestory_chat_33325004 = "什麼？！我、我先問一下，妳是未經許可的，對吧？",
