  str_homestory_chat_33325009 = "真希望城主大人會感謝我啊！哈哈哈！",
  str_homestory_chat_33325010 = "妳怎麼會跑到那裡去？",
  str_homestory_chat_33325011 = "那天晚上，我在一堵很漂亮的白牆上塗鴉，接著衛兵來了。",
  str_homestory_chat_33325012 = "我才知道那裡是白夜城的審判庭。",
  str_homestory_chat_33325013 = "……",
  str_homestory_chat_33325014 = "然後我就逃啊，逃進城主寶座所在的地方了！",
