  str_homestory_chat_33429999 = "方便說說這個時代的見聞給我聽嗎？",
  str_homestory_chat_33421001 = "咦？跟我說話不用那麼拘謹啦。",
  str_homestory_chat_33421002 = "我已經沉睡太久，對這個世界的認知十分匱乏。",
  str_homestory_chat_33421003 = "一直這樣的話，或許會給你添麻煩。",
  str_homestory_chat_33421004 = "還請不吝賜教。",
  str_homestory_chat_33421005 = "不會啦，你看，我也算被「封印」在地底十七年過。",
  str_homestory_chat_33421006 = "所以我對這個世界，也算是在絕讚探索中！",
  str_homestory_chat_33421007 = "我們可以互相訴說各自的見聞。",
  str_homestory_chat_33421008 = "一起去認知並感受這個世界！",
  str_homestory_chat_33421009 = "這個世界，的確值得好好去感受。",
  str_homestory_chat_33421010 = "你有這份與我分享的心，是我的榮幸。",
  str_homestory_chat_33421011 = "以阿克琉斯之名，我也將對你毫無保留地分享。",
